import { ORACLE } from "./palette.ts";

/**
 * HD-2D+ post chain. Order (normative):
 * pollen/bokeh → bloom key (pre-vignette) → vignette → warm → light shafts → haze
 * → bloom (tight + wide) → tilt-shift → grade (contrast/sat/split-tone/lift/gamma) → cloud frame.
 * Shadow and AO are native scene passes (see scene.ts). Blur sigmas are authored at the
 * 480-wide presented buffer and scaled by `w / 480`; plates run at half resolution above 480.
 *
 * Looks: `grok` (default — sharp play band, emitter-only bloom, key-light shafts, golden-hour grade,
 * light corner frame), `cinema` (the heavy tilt-shift / haze / cloud-frame variant) and `texture`
 * (the render_styles.py chain that shipped with Texture R1).
 */
export type Rgb3 = readonly [number, number, number];

export interface Look {
  readonly name: string;
  /** Floating pollen per 480×320 buffer; radius (px @480) and alpha (0–255) ranges. */
  readonly pollenN: number;
  readonly pollenR: readonly [number, number];
  readonly pollenAlpha: readonly [number, number];
  /** Larger soft bokeh discs (dream sparkle), weighted toward the lit upper half. */
  readonly bokehN: number;
  readonly bokehR: readonly [number, number];
  readonly bokehAlpha: readonly [number, number];
  readonly vigStrength: number;
  readonly vigPow: number;
  /** Per-channel offset added after the vignette. */
  readonly warm: Rgb3;
  /** Additive light shafts from the upper-left key light (0 disables). */
  readonly rayGain: number;
  readonly rayRgb: Rgb3;
  /** Atmospheric haze blended toward the far (top) edge (0 disables). */
  readonly hazeGain: number;
  readonly hazeRgb: Rgb3;
  /**
   * Bloom key. `luma`: knee from `bloomThresh` over `bloomKnee` (≤0 = hard key) plus a gold-emitter
   * weight. `emitter`: only true emitters bloom — lantern/sign/coin gold, lantern glow cores and
   * warm-white glints (water sparkle, pollen); neutral whites such as HUD panels and shirts do not.
   */
  readonly bloomKey: "luma" | "emitter";
  readonly bloomThresh: number;
  readonly bloomKnee: number;
  readonly bloomGold: number;
  readonly bloomSigma: number;
  readonly bloomGain: number;
  /** Second, wider bloom scale layered on the same plate (0 gain disables). */
  readonly bloomWideSigma: number;
  readonly bloomWideGain: number;
  readonly tiltSigma: number;
  readonly tiltFocus: number;
  readonly tiltPow: number;
  readonly gradeContrast: number;
  readonly gradeSat: number;
  readonly gradeGamma: number;
  /** Black lift (0–255) so shadows read soft like a lit miniature. */
  readonly gradeLift: number;
  /** Split-tone offsets applied at luma 0 (shadows) and luma 255 (highlights). */
  readonly shadowTint: Rgb3;
  readonly highlightTint: Rgb3;
  /** Soft cloud frame: colour, peak alpha at the corners, and the normalised radius where it starts. */
  readonly frameRgb: Rgb3;
  readonly frameAlpha: number;
  readonly frameInset: number;
}

