export const LOOKS: Readonly<Record<string, Look>> = { texture: LOOK_TEXTURE, grok: LOOK_GROK, cinema: LOOK_CINEMA };
export const DEFAULT_LOOK = LOOK_GROK;

export function lookByName(name: string | null | undefined): Look {
  return (name && Object.hasOwn(LOOKS, name) ? LOOKS[name] : undefined) ?? DEFAULT_LOOK;
}

/** Sigmas, pollen radii and densities are authored at this buffer width. */
const BRIEF_W = 480;
const BRIEF_N = 480 * 320;

/** Pocket underlay scale (240 scenes). */
export const POST_SCALE = 2;
/** Wide 480 overworld posts at native res; the canvas is CSS-scaled by integer NN. */
export const OW_POST_SCALE = 1;

export interface PostOptions {
  look?: Look;
  /** Blend the soft cloud frame around the buffer edge (overworld default; off for stages). */
  frame?: boolean;
}

interface Particle {
  x: number;
  y: number;
  r: number;
  a: number;
}

interface Scratch {
  key: string;
  w: number;
  h: number;
  look: Look;
  /** Plate downsample shift: 0 = full-res plates (≤480 wide), 1 = half-res plates. */
  shift: number;
  hw: number;
  hh: number;
  arr: Float32Array;
  /** Per-pixel multiplier (vignette) and additive light (shafts). */
  vig: Float32Array;
  rays: Float32Array;
  /** Per-row haze blend and tilt blur weight. */
  haze: Float32Array;
  tiltW: Float32Array;
  /** Cloud frame alpha; empty when the frame is off. */
  frame: Float32Array;
  bloomR: Float32Array;
  bloomG: Float32Array;
  bloomB: Float32Array;
  wideR: Float32Array;
  wideG: Float32Array;
  wideB: Float32Array;
  softR: Float32Array;
  softG: Float32Array;
  softB: Float32Array;
  tmp: Float32Array;
  pollen: Particle[];
  bokeh: Particle[];
  gamma: Uint8ClampedArray;
  idx: Uint8ClampedArray;
  bloomRadii: number[];
  wideRadii: number[];
  tiltRadii: number[];
}

const scratches = new Map<string, Scratch>();

function mulberry(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Three box passes approximating a gaussian of `sigma` (Kovesi's boxesForGauss). */
function gaussRadii(sigma: number): number[] {
  if (sigma <= 0) return [];
  const n = 3;
  const wIdeal = Math.sqrt((12 * sigma * sigma) / n + 1);
  let wl = Math.floor(wIdeal);
  if (wl % 2 === 0) wl--;
  const wu = wl + 2;
  const m = Math.round((12 * sigma * sigma - n * wl * wl - 4 * n * wl - 3 * n) / (-4 * wl - 4));
  const out: number[] = [];
  for (let i = 0; i < n; i++) out.push(((i < m ? wl : wu) - 1) / 2);
  return out.filter((r) => r > 0);
}

// ---------------------------------------------------------------------------
// static noise (precompute only; never per frame)
// ---------------------------------------------------------------------------

function latticeHash(ix: number, iy: number, salt: number): number {
  let h = Math.imul(ix | 0, 0x27d4eb2d) ^ Math.imul(iy | 0, 0x165667b1) ^ Math.imul(salt | 0, 0x9e3779b1);
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d);
  h = Math.imul(h ^ (h >>> 12), 0x297a2d39);
  return ((h ^ (h >>> 15)) >>> 0) / 4294967296;
}

function fade(t: number): number {
  return t * t * (3 - 2 * t);
}

function noise2(x: number, y: number, salt: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = fade(x - ix);
  const fy = fade(y - iy);
  const a = latticeHash(ix, iy, salt);
  const b = latticeHash(ix + 1, iy, salt);
  const c = latticeHash(ix, iy + 1, salt);
  const d = latticeHash(ix + 1, iy + 1, salt);
  return (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
}

function fbm2(x: number, y: number, salt: number, octaves: number): number {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  for (let o = 0; o < octaves; o++) {
    sum += noise2(x, y, salt + o) * amp;
    norm += amp;
    x *= 2.03;
    y *= 1.97;
    amp *= 0.5;
  }
  return sum / norm;
}

function noise1(x: number, salt: number): number {
  const ix = Math.floor(x);
  const f = fade(x - ix);
  const a = latticeHash(ix, 0, salt);
  const b = latticeHash(ix + 1, 0, salt);
  return a + (b - a) * f;
}

function smoothstep(e0: number, e1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
}

/**
 * Light shafts: a diagonal fan (≈20°–50°) of soft angular lobes from a distant key light beyond
 * the upper-left corner, strongest near that corner and fading toward the foreground.
 */
function buildRays(w: number, h: number, look: Look): Float32Array {
  const out = new Float32Array(w * h);
  if (look.rayGain <= 0) return out;
  const sx = -1.2 * w;
  const sy = -1.0 * h;
  const scale = w / BRIEF_W;
  for (let y = 0; y < h; y++) {
    const bottomFade = Math.pow(Math.max(0, 1 - (0.8 * y) / h), 0.9);
    for (let x = 0; x < w; x++) {
      const ang = Math.atan2(y - sy, x - sx);
      // Normalised distance from the lit corner: 0 at top-left, 1 at bottom-right.
      const dTL = Math.hypot(x / w, y / h) / Math.SQRT2;
      // Several shafts of varying width (two angular octaves) over a faint glow lobe.
      const n = 0.7 * noise1(ang * 22 + 2.7, 41) + 0.3 * noise1(ang * 47 + 0.4, 43);
      const shaft = smoothstep(0.5, 0.8, n);
      const glow = 0.18 * smoothstep(0.35, 0.75, noise1(ang * 7 + 1.1, 45));
      // Dust density along the shaft so it reads volumetric rather than painted.
      const dust = 0.7 + 0.3 * noise2(x / (30 * scale), y / (30 * scale), 47);
      out[y * w + x] = (shaft + glow) * Math.exp(-dTL * 1.6) * bottomFade * dust;
    }
  }
  return out;
}

/** Peach cloud frame: rounded-square edge ramp with lumpy fbm boundary and fluffy density. */
function buildFrame(w: number, h: number, look: Look): Float32Array {
  const out = new Float32Array(w * h);
  if (look.frameAlpha <= 0) return out;
  const scale = w / BRIEF_W;
  for (let y = 0; y < h; y++) {
    const ny = ((y + 0.5) / h) * 2 - 1;
    for (let x = 0; x < w; x++) {
      const nx = ((x + 0.5) / w) * 2 - 1;
      const dSq = Math.max(Math.abs(nx), Math.abs(ny));
      const dCirc = Math.hypot(nx, ny) / Math.SQRT2;
      const d = 0.5 * dSq + 0.5 * dCirc;
      const cloud = fbm2(x / (36 * scale), y / (36 * scale), 53, 3);
      const puff = fbm2(x / (11 * scale), y / (11 * scale), 59, 2);
      const edge = smoothstep(look.frameInset, 1.02, d + (cloud - 0.5) * 0.24 + (puff - 0.5) * 0.06);
      out[y * w + x] = Math.min(1, edge * edge * look.frameAlpha * (0.72 + 0.56 * cloud));
    }
  }
  return out;
}

function getScratch(w: number, h: number, look: Look, frame: boolean): Scratch {
  const key = `${w}x${h}:${look.name}:${frame ? 1 : 0}`;
  const hit = scratches.get(key);
  if (hit) return hit;
  const n = w * h;
  // Bloom and soft plates run at half resolution from 480 wide (bilinear on read-back);
  // the 240 stage keeps full-res plates so its sub-pixel sigmas survive.
  const shift = w >= 480 ? 1 : 0;
  const hw = w >> shift;
  const hh = h >> shift;
  const scale = w / BRIEF_W;
  const vig = new Float32Array(n);
  const cx = w / 2;
  const cy = h / 2;
  for (let y = 0; y < h; y++) {
    const dy = (y - cy) / cy;
    for (let x = 0; x < w; x++) {
      const dx = (x - cx) / cx;
      const dist = Math.sqrt(dx * dx + dy * dy) / Math.SQRT2;
      vig[y * w + x] = 1 - look.vigStrength * Math.pow(dist, look.vigPow);
    }
  }
  const tiltW = new Float32Array(h);
  const haze = new Float32Array(h);
  for (let y = 0; y < h; y++) {
    const t = Math.abs(y - cy) / cy;
    const k = Math.min(1, Math.max(0, (t - look.tiltFocus) / (1 - look.tiltFocus)));
    tiltW[y] = Math.pow(k, look.tiltPow);
    haze[y] = look.hazeGain * Math.pow(Math.max(0, 1 - y / (0.45 * h)), 1.6);
  }
  const rng = mulberry(7);
  const density = n / BRIEF_N;
  const count = Math.max(6, Math.round(look.pollenN * density));
  const pollen: Particle[] = [];
  for (let i = 0; i < count; i++) {
    const x = Math.floor(rng() * w);
    const y = Math.floor(rng() * h);
    const r = look.pollenR[0] + Math.floor(rng() * (look.pollenR[1] - look.pollenR[0] + 1));
    const a = look.pollenAlpha[0] + Math.floor(rng() * (look.pollenAlpha[1] - look.pollenAlpha[0] + 1));
    pollen.push({ x, y, r: Math.max(1, Math.round(r * scale)), a });
  }
  const bokeh: Particle[] = [];
  const bokehCount = Math.round(look.bokehN * density);
  for (let i = 0; i < bokehCount; i++) {
    const x = Math.floor(rng() * w);
    const y = Math.floor(Math.pow(rng(), 1.6) * h);
    const r = look.bokehR[0] + rng() * (look.bokehR[1] - look.bokehR[0]);
    const a = look.bokehAlpha[0] + Math.floor(rng() * (look.bokehAlpha[1] - look.bokehAlpha[0] + 1));
    bokeh.push({ x, y, r: Math.max(2, Math.round(r * scale)), a });
  }
  const gamma = new Uint8ClampedArray(256);
  for (let i = 0; i < 256; i++) gamma[i] = Math.round(255 * Math.pow(i / 255, look.gradeGamma));
  // Plate sigmas in plate pixels (the plate is NN-scaled back by 1 << shift).
  const plate = scale / (1 << shift);
  const bloomRadii = gaussRadii(look.bloomSigma * plate);
  // The wide plate continues from the tight one, so only the remaining variance is blurred.
  const wideExtra = Math.sqrt(Math.max(0, look.bloomWideSigma ** 2 - look.bloomSigma ** 2));
  const wideRadii = look.bloomWideGain > 0 ? gaussRadii(wideExtra * plate) : [];
  // Sub-pixel tilt at this size still needs one visible soft pass.
  const tiltRadii = gaussRadii(look.tiltSigma * plate);
  if (!tiltRadii.length) tiltRadii.push(1);
  const s: Scratch = {
    key,
    w,
    h,
    look,
    shift,
    hw,
    hh,
    arr: new Float32Array(n * 3),
    vig,
    rays: buildRays(w, h, look),
    haze,
    tiltW,
    frame: frame ? buildFrame(w, h, look) : new Float32Array(0),
    bloomR: new Float32Array(hw * hh),
    bloomG: new Float32Array(hw * hh),
    bloomB: new Float32Array(hw * hh),
    wideR: new Float32Array(wideRadii.length ? hw * hh : 0),
    wideG: new Float32Array(wideRadii.length ? hw * hh : 0),
    wideB: new Float32Array(wideRadii.length ? hw * hh : 0),
    softR: new Float32Array(hw * hh),
    softG: new Float32Array(hw * hh),
    softB: new Float32Array(hw * hh),
    tmp: new Float32Array(hw * hh),
    pollen,
    bokeh,
    gamma,
    idx: new Uint8ClampedArray(3),
    bloomRadii,
    wideRadii,
    tiltRadii,
  };
  // Keep the overworld and one stage/interior size resident; drop anything older.
  if (scratches.size >= 4) scratches.delete(scratches.keys().next().value!);
  scratches.set(key, s);
  return s;
}

function boxBlur(src: Float32Array, w: number, h: number, r: number, tmp: Float32Array): void {
  if (r <= 0) return;
  const n = r * 2 + 1;
  for (let y = 0; y < h; y++) {
    const row = y * w;
    let acc = 0;
    for (let x = -r; x <= r; x++) acc += src[row + Math.max(0, Math.min(w - 1, x))]!;
    for (let x = 0; x < w; x++) {
      tmp[row + x] = acc / n;
      acc -= src[row + Math.max(0, x - r)]!;
      acc += src[row + Math.min(w - 1, x + r + 1)]!;
    }
  }
  for (let x = 0; x < w; x++) {
    let acc = 0;
    for (let y = -r; y <= r; y++) acc += tmp[Math.max(0, Math.min(h - 1, y)) * w + x]!;
    for (let y = 0; y < h; y++) {
      src[y * w + x] = acc / n;
      acc -= tmp[Math.max(0, y - r) * w + x]!;
      acc += tmp[Math.min(h - 1, y + r + 1) * w + x]!;
    }
  }
}

function circle(rgba: Uint8ClampedArray, w: number, h: number, cx: number, cy: number, r: number, a: number): void {
  const [pr, pg, pb] = ORACLE.POLLEN;
  for (let y = cy - r; y <= cy + r; y++) {
    if (y < 0 || y >= h) continue;
    for (let x = cx - r; x <= cx + r; x++) {
      if (x < 0 || x >= w) continue;
      const dx = x - cx;
      const dy = y - cy;
      if (dx * dx + dy * dy > r * r + r) continue;
      const o = (y * w + x) * 4;
      rgba[o] = rgba[o]! * (1 - a) + pr * a;
      rgba[o + 1] = rgba[o + 1]! * (1 - a) + pg * a;
      rgba[o + 2] = rgba[o + 2]! * (1 - a) + pb * a;
    }
  }
}

/** Soft bokeh disc: filled, feathered falloff so it reads as out-of-focus sparkle. */
function bokehDisc(rgba: Uint8ClampedArray, w: number, h: number, q: Particle): void {
  const [pr, pg, pb] = ORACLE.POLLEN;
  const r = q.r;
  const peak = q.a / 255;
  for (let y = q.y - r; y <= q.y + r; y++) {
    if (y < 0 || y >= h) continue;
    for (let x = q.x - r; x <= q.x + r; x++) {
      if (x < 0 || x >= w) continue;
      const d = Math.hypot(x - q.x, y - q.y) / r;
      if (d > 1) continue;
      const a = peak * Math.pow(1 - d, 1.4);
      if (a <= 0) continue;
      const o = (y * w + x) * 4;
      rgba[o] = rgba[o]! * (1 - a) + pr * a;
      rgba[o + 1] = rgba[o + 1]! * (1 - a) + pg * a;
      rgba[o + 2] = rgba[o + 2]! * (1 - a) + pb * a;
    }
  }
}

export function applyHd2dPost(rgba: Uint8ClampedArray, w: number, h: number, opts: PostOptions = {}): void {
  const look = opts.look ?? DEFAULT_LOOK;
  const s = getScratch(w, h, look, opts.frame ?? false);
  const arr = s.arr;
  const hw = s.hw;
  const hh = s.hh;
  const [wr, wg, wb] = look.warm;
  const thresh = look.bloomThresh;
  const knee = look.bloomKnee;
  const invKnee = knee > 0 ? 1 / knee : 0;
  const goldW = look.bloomGold;
  const emitterKey = look.bloomKey === "emitter";
  const rayGain = look.rayGain;
  const rayR = look.rayRgb[0] * rayGain;
  const rayG = look.rayRgb[1] * rayGain;
  const rayB = look.rayRgb[2] * rayGain;
  const [hzR, hzG, hzB] = look.hazeRgb;

  // pollen + bokeh — warm floating particles (seeded, static), blended straight into the source
  for (const q of s.pollen) {
    if (q.a > 120) circle(rgba, w, h, q.x, q.y, q.r * 3, 24 / 255);
    circle(rgba, w, h, q.x, q.y, q.r, q.a / 255);
  }
  for (const q of s.bokeh) bokehDisc(rgba, w, h, q);

  // bloom key on PRE-vignette luma, then vignette → warm → shafts → haze; plates at plate res
  const bR = s.bloomR;
  const bG = s.bloomG;
  const bB = s.bloomB;
  const sR = s.softR;
  const sG = s.softG;
  const sB = s.softB;
  bR.fill(0);
  bG.fill(0);
  bB.fill(0);
  sR.fill(0);
  sG.fill(0);
  sB.fill(0);
  const vig = s.vig;
  const rays = s.rays;
  const haze = s.haze;
  const shift = s.shift;
  const wgtP = shift ? 0.25 : 1;
  for (let y = 0; y < h; y++) {
    const hrow = (y >> shift) * hw;
    const hz = haze[y]!;
    const ihz = 1 - hz;
    let i = y * w;
    for (let x = 0; x < w; x++, i++) {
      const o = i * 4;
      const p = i * 3;
      let r = rgba[o]!;
      let g = rgba[o + 1]!;
      let b = rgba[o + 2]!;
      const luma = 0.299 * r + 0.587 * g + 0.114 * b;
      let kw = 0;
      if (emitterKey) {
        // Lantern / sign / coin gold, lantern glow cores, then warm whites (glints, pollen).
        // Neutral whites (HUD panel, shirt) and cream cobbles stay out of the bloom plate.
        if (r >= 246 && g >= 190 && b < 80) kw = goldW;
        else if (r >= 248 && g >= 215 && b < 150) kw = 0.9;
        else if (luma >= 232 && r - b >= 20) kw = 0.7;
      } else {
        if (invKnee > 0) {
          kw = (luma - thresh) * invKnee;
          if (kw < 0) kw = 0;
          else if (kw > 1) kw = 1;
        } else kw = luma >= thresh ? 1 : 0;
        // Gold emitters (lantern gold, sign gold, coin) glow at golden hour even below the luma key.
        if (goldW > 0 && r >= 246 && g >= 190 && b < 80 && kw < goldW) kw = goldW;
      }
      const v = vig[i]!;
      const ray = rays[i]!;
      // Shafts add light soft-light style: full strength in shade, tapering on bright sand.
      r = r * v + wr + ray * rayR * (1 - 0.0032 * r);
      g = g * v + wg + ray * rayG * (1 - 0.0032 * g);
      b = b * v + wb + ray * rayB * (1 - 0.0032 * b);
      if (hz > 0) {
        r = r * ihz + hzR * hz;
        g = g * ihz + hzG * hz;
        b = b * ihz + hzB * hz;
      }
      if (r > 255) r = 255;
      else if (r < 0) r = 0;
      if (g > 255) g = 255;
      else if (g < 0) g = 0;
      if (b > 255) b = 255;
      else if (b < 0) b = 0;
      arr[p] = r;
      arr[p + 1] = g;
      arr[p + 2] = b;
      const hi = hrow + (x >> shift);
      sR[hi] += r * wgtP;
      sG[hi] += g * wgtP;
      sB[hi] += b * wgtP;
      if (kw > 0) {
        const kk = kw * wgtP;
        bR[hi] += r * kk;
        bG[hi] += g * kk;
        bB[hi] += b * kk;
      }
    }
  }
  for (const r of s.bloomRadii) {
    boxBlur(bR, hw, hh, r, s.tmp);
    boxBlur(bG, hw, hh, r, s.tmp);
    boxBlur(bB, hw, hh, r, s.tmp);
  }
  const gain = look.bloomGain;
  const wideGain = look.bloomWideGain;
  const hasWide = s.wideRadii.length > 0;
  const wR = s.wideR;
  const wG = s.wideG;
  const wB = s.wideB;
  if (hasWide) {
    wR.set(bR);
    wG.set(bG);
    wB.set(bB);
    for (const r of s.wideRadii) {
      boxBlur(wR, hw, hh, r, s.tmp);
      boxBlur(wG, hw, hh, r, s.tmp);
      boxBlur(wB, hw, hh, r, s.tmp);
    }
  }
  // soft plate = blurred (scene + bloom), used by the tilt ramp
  for (let i = 0; i < hw * hh; i++) {
    let r = sR[i]! + bR[i]! * gain;
    let g = sG[i]! + bG[i]! * gain;
    let b = sB[i]! + bB[i]! * gain;
    if (hasWide) {
      r += wR[i]! * wideGain;
      g += wG[i]! * wideGain;
      b += wB[i]! * wideGain;
    }
    sR[i] = Math.min(255, r);
    sG[i] = Math.min(255, g);
    sB[i] = Math.min(255, b);
  }
  for (const r of s.tiltRadii) {
    boxBlur(sR, hw, hh, r, s.tmp);
    boxBlur(sG, hw, hh, r, s.tmp);
    boxBlur(sB, hw, hh, r, s.tmp);
  }

  // bloom add → tilt blend → grade (contrast about 128, saturation about luma, split-tone, lift, gamma) → frame
  const con = look.gradeContrast;
  const sat = look.gradeSat;
  const gam = s.gamma;
  const off = 128 - 128 * con;
  const lift = look.gradeLift;
  const liftK = (255 - lift) / 255;
  const [shR, shG, shB] = look.shadowTint;
  const [hlR, hlG, hlB] = look.highlightTint;
  const tone = shR !== 0 || shG !== 0 || shB !== 0 || hlR !== 0 || hlG !== 0 || hlB !== 0;
  const frame = s.frame;
  const hasFrame = frame.length > 0;
  const [fR, fG, fB] = look.frameRgb;
  // Plate read-back: direct index at full res, 4-tap bilinear when plates are half res.
  let h00 = 0, h01 = 0, h10 = 0, h11 = 0;
  let w00 = 1, w01 = 0, w10 = 0, w11 = 0;
  for (let y = 0; y < h; y++) {
    const k = s.tiltW[y]!;
    const ik = 1 - k;
    let hrow0 = y * hw;
    let hrow1 = hrow0;
    let fy = 0;
    if (shift) {
      const v = (y - 0.5) / 2;
      const j0 = Math.max(0, Math.min(hh - 1, Math.floor(v)));
      const j1 = Math.min(hh - 1, j0 + 1);
      fy = Math.max(0, Math.min(1, v - j0));
      hrow0 = j0 * hw;
      hrow1 = j1 * hw;
    }
    let i = y * w;
    for (let x = 0; x < w; x++, i++) {
      const p = i * 3;
      if (shift) {
        const u = (x - 0.5) / 2;
        const i0 = Math.max(0, Math.min(hw - 1, Math.floor(u)));
        const i1 = Math.min(hw - 1, i0 + 1);
        const fx = Math.max(0, Math.min(1, u - i0));
        h00 = hrow0 + i0;
        h01 = hrow0 + i1;
        h10 = hrow1 + i0;
        h11 = hrow1 + i1;
        w00 = (1 - fx) * (1 - fy);
        w01 = fx * (1 - fy);
        w10 = (1 - fx) * fy;
        w11 = fx * fy;
      } else {
        h00 = i;
      }
      let r = arr[p]! + (bR[h00]! * w00 + bR[h01]! * w01 + bR[h10]! * w10 + bR[h11]! * w11) * gain;
      let g = arr[p + 1]! + (bG[h00]! * w00 + bG[h01]! * w01 + bG[h10]! * w10 + bG[h11]! * w11) * gain;
      let b = arr[p + 2]! + (bB[h00]! * w00 + bB[h01]! * w01 + bB[h10]! * w10 + bB[h11]! * w11) * gain;
      if (hasWide) {
        r += (wR[h00]! * w00 + wR[h01]! * w01 + wR[h10]! * w10 + wR[h11]! * w11) * wideGain;
        g += (wG[h00]! * w00 + wG[h01]! * w01 + wG[h10]! * w10 + wG[h11]! * w11) * wideGain;
        b += (wB[h00]! * w00 + wB[h01]! * w01 + wB[h10]! * w10 + wB[h11]! * w11) * wideGain;
      }
      if (r > 255) r = 255;
      if (g > 255) g = 255;
      if (b > 255) b = 255;
      if (k > 0) {
        r = r * ik + (sR[h00]! * w00 + sR[h01]! * w01 + sR[h10]! * w10 + sR[h11]! * w11) * k;
        g = g * ik + (sG[h00]! * w00 + sG[h01]! * w01 + sG[h10]! * w10 + sG[h11]! * w11) * k;
        b = b * ik + (sB[h00]! * w00 + sB[h01]! * w01 + sB[h10]! * w10 + sB[h11]! * w11) * k;
      }
      r = r * con + off;
      g = g * con + off;
      b = b * con + off;
      const l = 0.299 * r + 0.587 * g + 0.114 * b;
      r = l + (r - l) * sat;
      g = l + (g - l) * sat;
      b = l + (b - l) * sat;
      if (tone) {
        const t = l < 0 ? 0 : l > 255 ? 1 : l / 255;
        const it = 1 - t;
        r += shR * it + hlR * t;
        g += shG * it + hlG * t;
        b += shB * it + hlB * t;
      }
      if (lift > 0) {
        r = lift + r * liftK;
        g = lift + g * liftK;
        b = lift + b * liftK;
      }
      // Uint8ClampedArray clamps + rounds; the LUT index is clamped by the same store.
      s.idx[0] = r;
      s.idx[1] = g;
      s.idx[2] = b;
      r = gam[s.idx[0]!]!;
      g = gam[s.idx[1]!]!;
      b = gam[s.idx[2]!]!;
      if (hasFrame) {
        const a = frame[i]!;
        if (a > 0) {
          const ia = 1 - a;
          r = r * ia + fR * a;
          g = g * ia + fG * a;
          b = b * ia + fB * a;
        }
      }
      const o = i * 4;
      rgba[o] = r;
      rgba[o + 1] = g;
      rgba[o + 2] = b;
      rgba[o + 3] = 255;
    }
  }
}

export function nnScaleInto(src: ImageData, out: ImageData, scale: number): void {
  const w = out.width;
  for (let y = 0; y < src.height; y++) {
    for (let x = 0; x < src.width; x++) {
      const i = (y * src.width + x) * 4;
      for (let oy = 0; oy < scale; oy++) {
        const row = (y * scale + oy) * w + x * scale;
        for (let ox = 0; ox < scale; ox++) {
          const o = (row + ox) * 4;
          out.data[o] = src.data[i]!;
          out.data[o + 1] = src.data[i + 1]!;
          out.data[o + 2] = src.data[i + 2]!;
          out.data[o + 3] = 255;
        }
      }
    }
  }
}
