import type { Rgb } from "./palette.ts";

export class Pix {
  w: number;
  h: number;
  data: Uint8ClampedArray;

  constructor(w: number, h: number) {
    this.w = w;
    this.h = h;
    this.data = new Uint8ClampedArray(w * h * 4);
  }

  p(x: number, y: number, c: Rgb, a = 255): void {
    const xi = x | 0;
    const yi = y | 0;
    if (xi < 0 || yi < 0 || xi >= this.w || yi >= this.h) return;
    const o = (yi * this.w + xi) * 4;
    this.data[o] = c[0];
    this.data[o + 1] = c[1];
    this.data[o + 2] = c[2];
    this.data[o + 3] = a;
  }

  get(x: number, y: number): number {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return -1;
    return this.data[(y * this.w + x) * 4 + 3]!;
  }

  fill(x: number, y: number, w: number, h: number, c: Rgb): void {
    for (let yy = 0; yy < h; yy++) {
      for (let xx = 0; xx < w; xx++) this.p(x + xx, y + yy, c);
    }
  }

  hline(x: number, y: number, w: number, c: Rgb): void {
    this.fill(x, y, w, 1, c);
  }

  vline(x: number, y: number, h: number, c: Rgb): void {
    this.fill(x, y, 1, h, c);
  }

  oval(cx: number, cy: number, rx: number, ry: number, c: Rgb): void {
    for (let y = -ry; y <= ry; y++) {
      for (let x = -rx; x <= rx; x++) {
        if (x * x * ry * ry + y * y * rx * rx <= rx * rx * ry * ry) this.p(cx + x, cy + y, c);
      }
    }
  }

  outlineEmpty(c: Rgb): void {
    const next = new Uint8ClampedArray(this.data);
    for (let y = 0; y < this.h; y++) {
      for (let x = 0; x < this.w; x++) {
        if (this.get(x, y) >= 8) continue;
        const n =
          this.get(x - 1, y) >= 8 ||
          this.get(x + 1, y) >= 8 ||
          this.get(x, y - 1) >= 8 ||
          this.get(x, y + 1) >= 8;
        if (!n) continue;
        const o = (y * this.w + x) * 4;
        next[o] = c[0];
        next[o + 1] = c[1];
        next[o + 2] = c[2];
        next[o + 3] = 255;
      }
    }
    this.data = next;
  }

  toImage(): ImageData {
    const img = new ImageData(this.w, this.h);
    img.data.set(this.data);
    return img;
  }
}
