import { routePlan } from "../data/routePlan.ts";
import { crewCoverage } from "../data/crewCoverage.ts";
import { ZONES, zoneAt } from "../data/map.ts";
import { SPECIES } from "../data/species.ts";
import { TRAINERS } from "../data/trainers.ts";
import { TYPE_META, typeMod } from "../data/types.ts";
import { C } from "../engine/gfx.ts";
import type { Ctx } from "../game/ctx.ts";
import type { Scene } from "../game/scenes.ts";

export function routePlanScene(ctx: Ctx): Scene {
  let page = 0;
  return {
    id: "plan",
    enter() { page = 0; },
    exit() {},
    update() {
      if (ctx.input.consume("Escape")) { ctx.audio.back(); ctx.pop(); return; }
      const d = ctx.input.dirPressed();
      if (ctx.input.consume("Enter") || d?.x || d?.y) {
        page = (page + (d && (d.x < 0 || d.y < 0) ? -1 : 1) + 4) % 4;
        ctx.audio.cursor();
      }
    },
    draw() {
      const g = ctx.g, plan = routePlan(ctx.state);
      g.clear([36, 32, 28, 255]);
      g.panel(4, 4, 232, 152);
      g.fill(8, 8, 224, 14, C.goldHi);
      g.text(12, 11, `FIELD PLAN / ${["TRAIN", "DUEL", "CREW", "NOTES"][page]}`, C.ink);
      const row = (y: number, text: string, color = C.ink) => g.text(12, y, text, color);
      if (page === 0) {
        row(30, `HERE: ${ZONES[plan.zone].name}`);
        row(41, plan.local ? `Local wilds: Lv${plan.local.lo}-${plan.local.hi}` : "Safe town. Rest and stock up.");
        row(54, plan.lead ? `LEAD ${plan.lead.nick.slice(0, 12)} Lv${plan.lead.level}` : "No living lead. Visit the clinic.");
        row(65, plan.advice);
        row(78, plan.ready ? `Ready: ${plan.ready.nick.slice(0, 12)} Lv${plan.ready.level}` : "Free kettles restore HP and PP.");
        row(91, `TRY: ${ZONES[plan.training.zone].name}`);
        row(102, `${plan.training.region === "all" ? "Grass" : `${plan.training.region === "north" ? "North" : "South"} grass`}: Lv${plan.training.lo}-${plan.training.hi}`);
        row(113, `Rest: ${plan.kettle.title}`);
        row(126, "CREW L/R: choose your lead.");
      } else if (page === 1) {
        row(30, plan.repeat ? `REPEAT: ${plan.next.name}` : `NEXT: ${plan.next.name}`);
        row(41, ZONES[zoneAt(plan.next.x, plan.next.y)].name);
        row(54, plan.next.lineup ?? (plan.next.boss ? "Three-partner trial" : "Optional route duel"));
        plan.next.team.forEach((m, i) => row(67 + i * 11, `${i + 1}. ${SPECIES[m.species].name} Lv${m.level}`));
        row(105, plan.practice ? `Practice: ${TRAINERS[plan.practice].name}` : "Kettles are free between duels.");
        row(116, "Bring varied types and healing.");
        row(127, "In battle: B opens free tactics.");
      } else if (page === 2) {
        const coverage = crewCoverage(ctx.state), risk = coverage.risk, option = coverage.option;
        row(30, `NEXT: ${coverage.next.name}`);
        row(41, `CREW ${coverage.total}/4 / ${coverage.living} living`);
        if (risk) {
          const type = TYPE_META[risk.type].name;
          row(56, `Watch ${type}: ${risk.count}/${coverage.living} weak`);
          row(67, "This type hits them harder.");
          if (option?.kind === "crew" || option?.kind === "box") {
            row(82, `${option.kind === "box" ? "BOX" : "TYPE COVER"}: ${option.mon.nick.slice(0, 12)} Lv${option.mon.level}`);
            row(93, `${type} damage x${typeMod(risk.type, option.species.types)}`);
            row(106, option.kind === "box" ? "Visit Stubtown's Meme Box." : "Check its HP, PP and other matchups.");
          } else if (option?.kind === "evolve") {
            row(82, `Grow ${option.species.name} to Lv${option.species.evolveLevel}.`);
            row(93, `${option.evolved.name}: ${type} x${typeMod(risk.type, option.evolved.types)}`);
            row(106, "Living reserves also earn EXP.");
          } else if (option?.kind === "seen") {
            row(82, `SEEN OPTION: ${option.species.name}`);
            row(93, `${ZONES[option.habitat.zone].name} Lv${option.habitat.lo}-${option.habitat.hi}`);
            row(106, "Index: habitat and move kit.");
          } else {
            row(82, "Seek a different type in the wild.");
            row(93, "Index records seen kits/habitats.");
            row(106, "Weakening helps tins recruit.");
          }
          row(126, "Levels, HP and moves still matter.");
        } else {
          row(58, coverage.living < 2 ? "Rest or recruit more partners." : "No shared weakness in this kit.");
          row(80, "Check individual matchups in battle.");
          row(93, "B opens free tactics on your turn.");
          row(115, "Types alone do not promise a win.");
        }
      } else {
        ["Lead with a healthy, ready partner.", "Living reserves also earn EXP.", "Fainted reserves earn no EXP.", "Train below tough route levels.", "Three partners can already duel.", "Weak wilds are easier to recruit.", "Kettles restore the whole crew.", "Trainer RUN: preview concession."].forEach((s, i) => row(32 + i * 12, s));
      }
      g.hline(12, 140, 216, C.paperDark);
      row(145, `A / arrows: page ${page + 1}/4   B back`);
    },
  };
}
