export type Ink = 0 | 1 | 2 | 3 | 4 | 5;

export class Brush {
  w: number;
  h: number;
  px: Int8Array;

  constructor(w: number, h: number) {
    this.w = w;
    this.h = h;
    this.px = new Int8Array(w * h).fill(-1);
  }

  p(x: number, y: number, c: Ink | -1): void {
    const xi = x | 0;
    const yi = y | 0;
    if (xi < 0 || yi < 0 || xi >= this.w || yi >= this.h) return;
    this.px[yi * this.w + xi] = c;
  }

  get(x: number, y: number): number {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return -1;
    return this.px[y * this.w + x]!;
  }

  fill(x: number, y: number, w: number, h: number, c: Ink | -1): void {
    for (let yy = 0; yy < h; yy++) {
      for (let xx = 0; xx < w; xx++) this.p(x + xx, y + yy, c);
    }
  }

  oval(cx: number, cy: number, rx: number, ry: number, c: Ink, fill = true): void {
    for (let y = -ry; y <= ry; y++) {
      for (let x = -rx; x <= rx; x++) {
        if (x * x * ry * ry + y * y * rx * rx <= rx * rx * ry * ry) {
          if (fill) this.p(cx + x, cy + y, c);
        }
      }
    }
    if (!fill) {
      for (let y = -ry; y <= ry; y++) {
        for (let x = -rx; x <= rx; x++) {
          const inside = x * x * ry * ry + y * y * rx * rx <= rx * rx * ry * ry;
          const inset =
            (Math.abs(x) + 1) * (Math.abs(x) + 1) * ry * ry +
              (Math.abs(y) + 1) * (Math.abs(y) + 1) * rx * rx <=
            rx * rx * ry * ry;
          if (inside && !inset) this.p(cx + x, cy + y, c);
        }
      }
    }
  }

  dither(x: number, y: number, w: number, h: number, c: Ink): void {
    for (let yy = 0; yy < h; yy++) {
      for (let xx = 0; xx < w; xx++) {
        if (((x + xx + y + yy) & 1) === 0) this.p(x + xx, y + yy, c);
      }
    }
  }

  outline(c: Ink = 0): void {
    const next = Int8Array.from(this.px);
    for (let y = 0; y < this.h; y++) {
      for (let x = 0; x < this.w; x++) {
        if (this.get(x, y) >= 0) continue;
        const n =
          this.get(x - 1, y) >= 0 ||
          this.get(x + 1, y) >= 0 ||
          this.get(x, y - 1) >= 0 ||
          this.get(x, y + 1) >= 0;
        if (n) next[y * this.w + x] = c;
      }
    }
    this.px = next;
  }

  toImage(pal: readonly (readonly [number, number, number])[]): ImageData {
    const img = new ImageData(this.w, this.h);
    for (let i = 0; i < this.px.length; i++) {
      const v = this.px[i]!;
      if (v < 0) continue;
      const col = pal[v] ?? pal[0]!;
      const o = i * 4;
      img.data[o] = col[0];
      img.data[o + 1] = col[1];
      img.data[o + 2] = col[2];
      img.data[o + 3] = 255;
    }
    return img;
  }
}
