import { TYPE_META, type TypeId } from "../data/types.ts";
import { C, type Gfx } from "../engine/gfx.ts";

export function cursorGlyph(on: boolean): string {
  return on ? ">" : " ";
}

export function drawMenu(
  g: Gfx,
  x: number,
  y: number,
  w: number,
  items: string[],
  index: number,
  cols = 1,
): void {
  const rows = Math.ceil(items.length / cols);
  const visibleRows = Math.max(1, Math.min(rows, Math.floor((160 - y - 8) / 10)));
  const firstRow = Math.max(0, Math.floor(index / cols) - visibleRows + 1);
  const h = 8 + visibleRows * 10;
  g.panel(x, y, w, h);
  const colW = Math.floor((w - 8) / cols);
  items.forEach((label, i) => {
    const c = i % cols;
    const r = Math.floor(i / cols) - firstRow;
    if (r < 0 || r >= visibleRows) return;
    const xx = x + 4 + c * colW;
    const yy = y + 4 + r * 10;
    if (index === i) g.fill(x + 3 + c * colW, yy - 1, colW - 2, 9, C.paperDark);
    g.text(xx, yy, `${index === i ? ">" : " "}${label}`, C.ink);
  });
  if (firstRow > 0) {
    for (let row = 0; row < 3; row++) g.hline(x + w - 8 - row, y + 4 + row, 1 + row * 2, C.ink);
  }
  if (firstRow + visibleRows < rows) g.text(x + w - 10, y + h - 10, "v", C.ink);
}

export function wrapIndex(i: number, n: number, dx: number, dy: number, cols: number): number {
  if (n <= 0) return 0;
  const rows = Math.ceil(n / cols);
  let col = i % cols;
  let row = Math.floor(i / cols);
  col = (col + dx + cols) % cols;
  row = (row + dy + rows) % rows;
  let next = row * cols + col;
  if (next >= n) next = n - 1;
  return next;
}

export function drawHpBlock(
  g: Gfx,
  x: number,
  y: number,
  name: string,
  level: number,
  hp: number,
  max: number,
  types: string[],
  wide = false,
): void {
  const w = wide ? 112 : 104;
  g.panel(x, y, w, 28);
  g.text(x + 4, y + 3, name.slice(0, 10), C.ink);
  g.text(x + w - 36, y + 3, `Lv${level}`, C.ink);
  const t = max <= 0 ? 0 : hp / max;
  g.bar(x + 4, y + 13, w - 8, 5, t, g.hpColor(t));
  g.text(x + 4, y + 19, `${hp}/${max}`.padStart(7, " "), C.ink);
  if (types[0]) g.text(x + 52, y + 19, types[0]!.slice(0, 6).toUpperCase(), C.ink);
}

export function msgBox(g: Gfx, text: string, waiting: boolean): void {
  g.panel(4, 112, 232, 44);
  g.fill(8, 116, 224, 36, C.cream);
  g.rect(7, 115, 226, 38, C.ink);
  g.hline(8, 116, 224, C.white);
  g.lines(10, 118, text, 36, C.ink);
  if (waiting) {
    g.p(222, 144, C.ink);
    g.fill(221, 145, 3, 1, C.ink);
    g.fill(220, 146, 5, 1, C.ink);
  }
}

export function inkWell(g: Gfx, x: number, y: number, w: number, h: number): void {
  g.fill(x, y, w, h, C.cream);
  g.rect(x - 1, y - 1, w + 2, h + 2, C.ink);
  g.hline(x, y, w, C.white);
}

export function emptyCard(g: Gfx, title: string, body: string): void {
  g.panel(16, 40, 208, 72);
  g.text(24, 48, title, C.ink);
  g.lines(24, 64, body, 30, C.ink);
}

export function typeChip(g: Gfx, x: number, y: number, type: TypeId): number {
  const meta = TYPE_META[type];
  const w = Math.max(26, meta.chip.length * 6 + 2);
  g.fill(x, y, w, 8, meta.ink);
  g.rect(x, y, w, 8, C.ink);
  g.text(x + 1, y, meta.chip, C.cream);
  return w;
}
