export function pauseScene(ctx: Ctx): Scene {
  let i = 0;
  const items = ["CREW", "PACK", "INDEX", "PLAN", "MAP", "SAVE", "TITLE"];
  return {
    id: "pause",
    enter() {
      i = 0;
    },
    exit() {},
    update() {
      const d = ctx.input.dirPressed();
      if (d) {
        i = wrapIndex(i, items.length, 0, d.y, 1);
        ctx.audio.cursor();
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        ctx.pop();
        return;
      }
      if (ctx.input.consume("Enter")) {
        ctx.audio.confirm();
        if (i === 0) ctx.push("party");
        else if (i === 1) ctx.push("bag");
        else if (i === 2) ctx.push("index");
        else if (i === 3) ctx.push("plan");
        else if (i === 4) ctx.push("map");
        else if (i === 5) {
          ctx.save();
          ctx.pop();
          ctx.replace("overworld", { notice: "Saved to this pocket." });
        } else ctx.replace("title");
      }
    },
    draw() {
      const g = ctx.g;
      g.fill(0, 0, 240, 160, [8, 12, 10, 120]);
      drawMenu(g, 148, 8, 84, items, i, 1);
      g.panel(8, 8, 132, 54);
      g.text(14, 14, ctx.state.name, C.ink);
      g.text(14, 24, `${ctx.state.money} ${CURRENCY}`, C.ink);
      g.text(14, 34, `Caught ${ctx.state.caught.length}/${SPECIES_IDS.length}`, C.ink);
      g.text(14, 44, `SEED ${ctx.state.seed}`, C.ink);
    },
  };
}

export function partyScene(ctx: Ctx): Scene {
  let i = 0;
  return {
    id: "party",
    enter(p?: ScenePayload) {
      i = Math.max(0, Math.min(p?.partyIndex ?? 0, ctx.state.party.length - 1));
    },
    exit() {},
    update() {
      const d = ctx.input.dirPressed();
      if (d && ctx.state.party.length) {
        if (d.x) {
          const next = i + d.x;
          if (next >= 0 && next < ctx.state.party.length) {
            [ctx.state.party[i], ctx.state.party[next]] = [ctx.state.party[next]!, ctx.state.party[i]!];
            i = next;
            persist(ctx.state);
            ctx.audio.confirm();
          } else ctx.audio.back();
        } else {
          i = wrapIndex(i, ctx.state.party.length, 0, d.y, 1);
          ctx.audio.cursor();
        }
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        ctx.pop();
        return;
      }
      if (ctx.input.consume("Enter") && ctx.state.party[i]) {
        ctx.audio.confirm();
        ctx.push("summary", { partyIndex: i });
      }
    },
    draw() {
      const g = ctx.g;
      g.clear([36, 32, 28, 255]);
      g.panel(4, 4, 232, 16);
      g.text(8, 8, `CREW ${ctx.state.party.length}/4  A file  L/R order`, C.ink);
      if (!ctx.state.party.length) {
        emptyCard(g, "CREW EMPTY", "No meme in the four slots. Catch one on Drippond Route, then come back.");
      } else {
        const lead = ctx.state.party.findIndex(m => m.hp > 0);
        ctx.state.party.forEach((m, n) => {
          const y = 24 + n * 32;
          const bob = n === i ? idleBob(ctx.now, ctx.reduced) : 0;
          g.panel(4, y, 232, 30, n === i ? C.cream : C.paper);
          g.blit(creatureIcon(m.speciesId), 8, y + 6 - bob);
          g.text(44, y + 4, m.nick, C.ink);
          if (n === lead) {
            g.fill(150, y + 3, 32, 10, C.goldHi);
            g.text(154, y + 4, "LEAD", C.ink);
          }
          g.text(196, y + 4, `Lv${m.level}`, C.ink);
          g.hline(44, y + 12, 152, C.paperDark);
          const sp = SPECIES[m.speciesId];
          let chipX = 44;
          (sp?.types ?? []).forEach((id) => {
            chipX += typeChip(g, chipX, y + 14, id) + 2;
          });
          const t = m.hp / maxHp(m);
          g.fill(120, y + 16, 66, 5, C.slate);
          g.rect(120, y + 16, 66, 5, C.ink);
          g.bar(121, y + 17, 64, 3, t, g.hpColor(t), C.slate);
          g.text(190, y + 14, `${m.hp}/${maxHp(m)}`, C.ink);
        });
      }
    },
  };
}

export function summaryScene(ctx: Ctx): Scene {
  let i = 0;
  return {
    id: "summary",
    enter(p?: ScenePayload) {
      i = p?.partyIndex ?? 0;
    },
    exit() {},
    update() {
      const d = ctx.input.dirPressed();
      if (d && ctx.state.party.length) {
        i = wrapIndex(i, ctx.state.party.length, d.x, 0, ctx.state.party.length);
        ctx.audio.cursor();
      }
      if (ctx.input.consumeAny("Escape", "Enter")) {
        ctx.audio.back();
        ctx.pop();
      }
    },
    draw() {
      const g = ctx.g;
      const m = ctx.state.party[i];
      g.clear([28, 24, 22, 255]);
      if (!m) {
        emptyCard(g, "NO FILE", "Nobody to inspect. Fill a crew slot first.");
        return;
      }
      const sp = SPECIES[m.speciesId];
      g.panel(4, 4, 232, 152);
      if (!sp) {
        emptyCard(g, "NO FILE", "This slot has no species file. Catch a meme on Drippond Route.");
        return;
      }
      g.blit(creatureSprite(m.speciesId, "front"), 12, 16 - idleBob(ctx.now, ctx.reduced));
      g.text(56, 12, m.nick, C.ink);
      g.text(168, 12, `Lv${m.level}`, C.ink);
      let chipX = 56;
      sp.types.forEach((id) => {
        chipX += typeChip(g, chipX, 22, id) + 2;
      });
      g.text(56, 34, `HP ${m.hp}/${maxHp(m)}`, C.ink);
      g.text(56, 44, `ATK ${statOf(m, "atk")}  DEF ${statOf(m, "def")}`, C.ink);
      g.text(56, 54, `SPD ${statOf(m, "spd")}  DRIP ${m.drip.atk}`, C.ink);
      g.lines(12, 68, sp.blurb, 34);
      for (let n = 0; n < 4; n++) {
        const slot = m.moves[n];
        const y = 100 + n * 13;
        const mv = slot ? peekMove(slot.id) : null;
        if (!mv) {
          g.text(12, y, "--------", C.paperDark);
          g.text(186, y, "--/--", C.paperDark);
          continue;
        }
        typeChip(g, 12, y, mv.type);
        g.text(46, y, mv.name.slice(0, 16), C.ink);
        g.text(186, y, `${slot!.pp}/${mv.pp}`, C.ink);
      }
    },
  };
}

export function bagScene(ctx: Ctx): Scene {
  let i = 0;
  let note: string | null = null;
  const list = () =>
    (Object.keys(ITEMS) as ItemId[]).map((id) => ({ id, n: bagCount(ctx.state, id) })).filter((x) => x.n > 0);

  return {
    id: "bag",
    enter() {
      i = 0;
      note = null;
    },
    exit() {},
    update() {
      if (note) {
        if (ctx.input.consumeAny("Enter", "Escape")) note = null;
        return;
      }
      const items = list();
      i = Math.min(i, Math.max(0, items.length - 1));
      const d = ctx.input.dirPressed();
      if (d && items.length) {
        i = wrapIndex(i, items.length, 0, d.y, 1);
        ctx.audio.cursor();
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        ctx.pop();
        return;
      }
      if (ctx.input.consume("Enter") && items[i]) {
        const it = ITEMS[items[i]!.id];
        if (it.kind === "heal") {
          const m = ctx.state.party.find((p) => p.hp < maxHp(p));
          if (!m) {
            note = "Nobody needs a sip.";
            return;
          }
          bagAdd(ctx.state, it.id, -1);
          i = Math.min(i, Math.max(0, list().length - 1));
          healMon(m, it.heal ?? 22);
          ctx.audio.heal();
          persist(ctx.state);
          note = `${m.nick} drinks ${it.name}.`;
        } else {
          note = it.desc;
        }
      }
    },
    draw() {
      const g = ctx.g;
      g.clear([24, 28, 26, 255]);
      g.panel(4, 4, 232, 16);
      g.text(8, 8, `PACK   ${ctx.state.money} ${CURRENCY}`, C.ink);
      const items = list();
      if (!items.length) {
        emptyCard(g, "PACK EMPTY", "No tins, no sips. Signal Stall restocks the joke.");
      }
      const first = Math.max(0, i - 6);
      items.slice(first, first + 7).forEach((it, row) => {
        const n = first + row;
        const y = 24 + row * 14;
        g.text(12, y, `${n === i ? ">" : " "}${ITEMS[it.id].name}`, C.paper);
        g.text(180, y, `x${it.n}`, C.goldHi);
      });
      const cur = items[i];
      g.panel(4, 128, 232, 28);
      g.lines(10, 132, note ?? (cur ? ITEMS[cur.id].desc : "A is use / read."), 36);
    },
  };
}

export function shopScene(ctx: Ctx): Scene {
  let i = 0;
  let note: string | null = null;
  const unlocked = (id: ItemId) => !ITEMS[id].requiresTrainer || ctx.state.defeatedTrainers.includes(ITEMS[id].requiresTrainer!);
  return {
    id: "shop",
    enter() {
      i = 0;
      note = null;
    },
    exit() {},
    update() {
      const d = ctx.input.dirPressed();
      if (d) {
        i = wrapIndex(i, SHOP_STOCK.length, 0, d.y, 1);
        note = null;
        ctx.audio.cursor();
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        persist(ctx.state);
        ctx.pop();
        return;
      }
      if (ctx.input.consume("Enter")) {
        const id = SHOP_STOCK[i]!;
        const it = ITEMS[id];
        if (!unlocked(id)) {
          note = `${TRAINERS[it.requiresTrainer!].name} has the recipe. Duel in Cope Cliffs.`;
          ctx.audio.back();
          return;
        }
        if ((id === "sticker" || id === "frame") && ctx.state.cosmetics[id]) {
          note = "Already owned.";
          ctx.audio.back();
          return;
        }
        if (ctx.state.money < it.price) {
          ctx.audio.fail();
          note = "Not enough $MEME.";
          return;
        }
        ctx.state.money -= it.price;
        if (it.kind === "cosmetic") {
          if (id === "sticker") ctx.state.cosmetics.sticker = true;
          if (id === "frame") ctx.state.cosmetics.frame = true;
        } else bagAdd(ctx.state, id, 1);
        ctx.audio.buy();
        persist(ctx.state);
        note =
          it.kind === "cosmetic"
            ? `Bought ${it.name}. Yours. ${ctx.state.money} $MEME left.`
            : `Bought ${it.name}. Pack x${bagCount(ctx.state, id)}. ${ctx.state.money} $MEME left.`;
      }
    },
    draw() {
      const g = ctx.g;
      hd2dInterior(g, "shop");
      hd2dChromePanel(g, 4, 4, 188, 16);
      g.text(8, 8, `STALL   ${ctx.state.money} ${CURRENCY}`, rgba(P.HUD_INK));
      hd2dChromePanel(g, 196, 4, 40, 16);
      g.text(202, 8, `${i + 1}/${SHOP_STOCK.length}`, rgba(P.HUD_INK));
      if (!SHOP_STOCK.length) {
        emptyCard(g, "STALL WIPED", "Nothing on the board. Come back after restock.");
        return;
      }
      const first = Math.max(0, i - 6);
      SHOP_STOCK.slice(first, first + 7).forEach((id, row) => {
        const n = first + row;
        const it = ITEMS[id];
        const y = 22 + row * 14;
        hd2dChromePanel(g, 4, y, 232, 14, n === i);
        g.text(12, y + 3, `${n === i ? ">" : " "}${it.name}${unlocked(id) ? "" : " [locked]"}`, rgba(P.HUD_INK));
        g.text(176, y + 3, `${it.price}`, rgba(P.COIN_RIM));
      });
      hd2dChromePanel(g, 4, 128, 232, 28);
      hd2dChromeWell(g, 8, 132, 224, 20);
      const id = SHOP_STOCK[i]!;
      const it = ITEMS[id];
      const owned =
        id === "sticker"
          ? ctx.state.cosmetics.sticker
          : id === "frame"
            ? ctx.state.cosmetics.frame
            : false;
      const have =
        it.kind === "cosmetic"
          ? owned
            ? "  yours"
            : ""
          : bagCount(ctx.state, id)
            ? `  pack x${bagCount(ctx.state, id)}`
            : "";
      g.lines(10, 134, note ?? (unlocked(id) ? `A buy ${it.name}  ${it.price} $MEME${have}` : "Win Ilex's duel in Cope Cliffs."), 36, rgba(P.HUD_INK));
    },
  };
}

export function clinicScene(ctx: Ctx): Scene {
  let confirm = "A  done    B  done";
  return {
    id: "clinic",
    enter() {
      const needed = ctx.state.party.some(
        (m) => m.hp < maxHp(m) || m.moves.some((s) => s.pp < moveById(s.id).pp),
      );
      clinicHeal(ctx.state);
      persist(ctx.state);
      ctx.audio.heal();
      if (!ctx.state.party.length) confirm = "No crew to mend. B  leave.";
      else if (needed) confirm = "Mended. HP and PP full. A: done.";
      else confirm = "Already full. A: done.";
    },
    exit() {},
    update() {
      if (ctx.input.consumeAny("Enter", "Escape")) {
        ctx.audio.confirm();
        ctx.pop();
      }
    },
    draw() {
      const g = ctx.g;
      hd2dInterior(g, "clinic");
      hd2dChromePanel(g, 4, 4, 188, 16);
      g.text(8, 8, "COPE CLINIC", rgba(P.HUD_INK));
      if (!ctx.state.party.length) {
        emptyCard(g, "NO CREW", "Nobody on the cot. Catch a meme on Drippond Route, then come back.");
      } else {
        ctx.state.party.forEach((m, n) => {
          const y = 24 + n * 24;
          hd2dChromePanel(g, 4, y, 232, 22);
          g.blit(creatureIcon(m.speciesId), 8, y + 3);
          g.text(28, y + 4, m.nick, rgba(P.HUD_INK));
          const t = m.hp / maxHp(m);
          g.fill(120, y + 13, 72, 5, rgba(P.HUD_INK));
          g.rect(120, y + 13, 72, 5, rgba(P.SC_OUT));
          g.bar(121, y + 14, 70, 3, t, g.hpColor(t), rgba(P.HUD_INK));
          g.text(196, y + 12, `${m.hp}/${maxHp(m)}`, rgba(P.HUD_INK));
        });
      }
      hd2dChromePanel(g, 4, 128, 232, 28);
      hd2dChromeWell(g, 8, 132, 224, 20);
      g.lines(10, 134, confirm, 36, rgba(P.HUD_INK));
    },
  };
}

export function pcScene(ctx: Ctx): Scene {
  let i = 0;
  let swapI: number | null = null;
  let note = "B  leave.";
  return {
    id: "pc",
    enter() {
      i = 0;
      note = ctx.state.pc.length
        ? "A  pull into crew.  B  leave."
        : "Crate is empty.  B  leave.";
    },
    exit() {},
    update() {
      const d = ctx.input.dirPressed();
      if (swapI !== null) {
        if (d && ctx.state.party.length) {
          swapI = wrapIndex(swapI, ctx.state.party.length, 0, d.y, 1);
          ctx.audio.cursor();
        }
        if (ctx.input.consume("Escape")) {
          swapI = null;
          note = "B  leave.";
          ctx.audio.back();
          return;
        }
        if (ctx.input.consume("Enter") && ctx.state.party[swapI]) {
          const mon = ctx.state.pc[i]!;
          ctx.state.pc[i] = ctx.state.party[swapI]!;
          ctx.state.party[swapI] = mon;
          swapI = null;
          note = `${mon.nick} joins the crew.  B  leave.`;
          ctx.audio.confirm();
          persist(ctx.state);
        }
        return;
      }
      const n = ctx.state.pc.length;
      if (d && n) {
        i = wrapIndex(i, n, 0, d.y, 1);
        ctx.audio.cursor();
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        persist(ctx.state);
        ctx.pop();
        return;
      }
      if (ctx.input.consume("Enter") && ctx.state.pc[i]) {
        if (ctx.state.party.length >= PARTY_MAX) {
          swapI = 0;
          note = "Crew full. Pick who sits out.";
          return;
        }
        const mon = ctx.state.pc[i]!;
        ctx.state.pc.splice(i, 1);
        const where = stashMon(ctx.state, mon);
        if (where === "pc") {
          note = "Crew full (4). It bounced back.  B  leave.";
        } else {
          restoreAll(mon);
          persist(ctx.state);
          note = `${mon.nick} joined the crew.  B  leave.`;
        }
        i = 0;
        if (!ctx.state.pc.length && where === "party") {
          note = `${mon.nick} joined the crew. Crate empty.  B  leave.`;
        }
      }
    },
    draw() {
      const g = ctx.g;
      g.clear([22, 26, 32, 255]);
      g.panel(4, 4, 232, 16);
      if (swapI !== null) {
        g.text(8, 8, "SWAP WITH WHICH MEME?", C.ink);
        drawMenu(g, 4, 24, 232, ctx.state.party.map((m) => `${m.nick} Lv${m.level}`), swapI);
        g.panel(4, 128, 232, 28);
        inkWell(g, 8, 132, 224, 20);
        g.lines(10, 134, "A: swap. B: keep the crew.", 36);
        return;
      }
      g.text(8, 8, `MEME BOX  ${ctx.state.pc.length} stored`, C.ink);
      if (!ctx.state.pc.length) {
        emptyCard(g, "CRATE EMPTY", "Overflow sleeps here. Catch a fifth and it lands in the box.");
      } else {
        const visible = 5;
        const first = Math.max(0, Math.min(i - visible + 1, ctx.state.pc.length - visible));
        ctx.state.pc.slice(first, first + visible).forEach((m, n) => {
          const y = 24 + n * 20;
          const on = n + first === i;
          g.panel(4, y, 232, 18, on ? C.cream : C.paper);
          g.fill(8, y + 1, 16, 16, C.paperDark);
          g.rect(8, y + 1, 16, 16, C.ink);
          g.blit(creatureIcon(m.speciesId), 8, y + 1);
          g.text(28, y + 5, `${on ? ">" : " "}${m.nick} Lv${m.level}`, C.ink);
        });
      }
      g.panel(4, 128, 232, 28);
      inkWell(g, 8, 132, 224, 20);
      g.lines(10, 134, note, 36);
    },
  };
}

export function indexScene(ctx: Ctx): Scene {
  let i = 0;
  let detail = false;
  let page = 0;
  let unrecorded = false;
  return {
    id: "index",
    enter() {
      i = 0;
      detail = false;
      page = 0;
      unrecorded = false;
    },
    exit() {},
    update() {
      if (unrecorded) {
        if (ctx.input.consumeAny("Enter", "Escape")) unrecorded = false;
        return;
      }
      if (detail) {
        if (ctx.input.consume("Escape")) {
          detail = false;
          ctx.audio.back();
        } else if (ctx.input.consumeAny("Enter", "ArrowRight")) {
          page = (page + 1) % 3;
          ctx.audio.cursor();
        } else if (ctx.input.consume("ArrowLeft")) {
          page = (page + 2) % 3;
          ctx.audio.cursor();
        }
        return;
      }
      const d = ctx.input.dirPressed();
      if (d) {
        i = wrapIndex(i, SPECIES_IDS.length, d.x, d.y, 2);
        ctx.audio.cursor();
      }
      if (ctx.input.consume("Escape")) {
        ctx.audio.back();
        ctx.pop();
      } else if (ctx.input.consume("Enter")) {
        if (ctx.state.seen.includes(SPECIES_IDS[i]!)) {
          detail = true;
          page = 0;
          ctx.audio.confirm();
        } else {
          unrecorded = true;
          ctx.audio.back();
        }
      }
    },
    draw() {
      const g = ctx.g;
      g.clear([16, 20, 22, 255]);
      if (detail) {
        const id = SPECIES_IDS[i]!;
        const sp = SPECIES[id];
        g.panel(4, 4, 232, 16);
        g.text(8, 8, sp.name, C.ink);
        g.text(144, 8, ["PROFILE", "HABITAT", "KIT"][page]!, C.ink);
        g.text(210, 8, `${page + 1}/3`, C.ink);
        g.panel(4, 24, 232, 116);
        if (page === 0) {
          g.blit(creatureSprite(id, "front"), 12, 32 - idleBob(ctx.now, ctx.reduced));
          let chipX = 56;
          sp.types.forEach(type => { chipX += typeChip(g, chipX, 36, type) + 2; });
          g.text(56, 52, ctx.state.caught.includes(id) ? "OWNED" : "SEEN", C.ink);
          g.lines(12, 76, sp.blurb, 35);
          g.lines(12, 116, guideEvolution(id), 35);
        } else if (page === 1) {
          const habitats = guideHabitats(id, ctx.state.defeatedTrainers.includes("vell"));
          g.text(12, 30, "WILD GRASS", C.ink);
          if (!habitats.length) {
            g.lines(12, 50, "No wild habitat recorded.", 35);
            g.lines(12, 76, guideEvolution(id), 35);
          } else {
            habitats.forEach((row, n) => {
              const region = row.region === "north" ? " N" : row.region === "south" ? " S" : "";
              g.text(12, 48 + n * 17, `${ZONES[row.zone].name}${region}`, C.ink);
              g.text(174, 48 + n * 17, `Lv${row.lo}-${row.hi}`, C.ink);
            });
            if (habitats.some(row => row.region !== "all")) g.text(12, 128, "N north beds   S south beds", C.ink);
          }
        } else {
          g.text(12, 30, "STANDARD KIT", C.ink);
          sp.moves.forEach((id, n) => {
            const move = moveById(id);
            const y = 46 + n * 22;
            g.text(12, y, move.name, C.ink);
            typeChip(g, 198, y, move.type);
            g.text(12, y + 10, `${move.power ? `POW ${move.power}` : "STATUS"}  ${moveEffectLabel(move)}`, C.ink);
            g.text(186, y + 10, `PP ${move.pp}`, C.ink);
          });
        }
        g.text(8, 148, "L/R pages  A next  B list", C.paper);
        return;
      }
      g.panel(4, 4, 232, 16);
      g.text(8, 8, `INDEX  ${ctx.state.caught.length}/${SPECIES_IDS.length} owned`, C.ink);
      const first = Math.floor(i / 10) * 10;
      SPECIES_IDS.slice(first, first + 10).forEach((id, n) => {
        const col = n % 2;
        const row = Math.floor(n / 2);
        const x = 8 + col * 116;
        const y = 24 + row * 24;
        const seen = ctx.state.seen.includes(id);
        const got = ctx.state.caught.includes(id);
        if (seen) g.blit(creatureIcon(id), x + 8, y);
        g.text(x + 28, y + 4, `${first + n === i ? ">" : " "}${seen ? SPECIES[id].name : "????????"}`, got ? C.goldHi : C.paper);
      });
      g.text(8, 148, `${first + 1}-${Math.min(first + 10, SPECIES_IDS.length)} / ${SPECIES_IDS.length}  A file  B back`, C.paper);
      if (unrecorded) emptyCard(g, "NO FIELD RECORD", "Meet this meme in the wild or a duel to open its file. A/B: list.");
    },
  };
}
