import { encountersAt, SPOTS, VETERAN_ENCOUNTERS, ZONES, zoneAt, type EncounterRow, type ZoneId } from "./map.ts";
import { peekMove } from "./moves.ts";
import { CIRCUIT_IDS, TRAINERS, trainerEncounter, type TrainerId } from "./trainers.ts";
import { maxHp } from "../game/mon.ts";
import type { SaveState } from "../game/save.ts";

export interface TrainingBed {
  zone: ZoneId;
  region: "all" | "north" | "south";
  lo: number;
  hi: number;
}

function band(rows: EncounterRow[]): { lo: number; hi: number } | null {
  return rows.length ? { lo: Math.min(...rows.map(r => r.lo)), hi: Math.max(...rows.map(r => r.hi)) } : null;
}

/** Public habitat levels and owned resources only; advice never draws RNG or edits a save. */
export function routePlan(state: SaveState) {
  const cleared = state.defeatedTrainers.includes("vell");
  const beds: TrainingBed[] = [];
  for (const zone of Object.keys(ZONES) as ZoneId[]) {
    const base = band(ZONES[zone].encounters);
    const veteran = cleared ? band(VETERAN_ENCOUNTERS[zone] ?? []) : null;
    if (base) beds.push({ zone, region: veteran ? "north" : "all", ...base });
    if (veteran) beds.push({ zone, region: "south", ...veteran });
  }
  const lead = state.party.find(m => m.hp > 0);
  const ready = state.party.filter(m => m.hp >= maxHp(m) / 2 && m.moves.some(slot => slot.pp > 0 && (peekMove(slot.id)?.power ?? 0) > 0))
    .sort((a, b) => b.level - a.level)[0];
  const training = beds.filter(b => b.hi <= (ready?.level ?? 1) + 2)
    .sort((a, b) => b.lo - a.lo || b.hi - a.hi)[0] ?? beds.find(b => b.zone === "drippond")!;
  const local = band(encountersAt(state.x, state.y, cleared));
  const kettle = SPOTS.find(s => s.kind === "rest" && zoneAt(s.x, s.y) === training.zone)!;
  const underlevelled = !!lead && !!local && lead.level + 2 < local.lo;
  const advice = !ready ? "Rest: low HP or attack PP."
    : underlevelled ? "Lead is below these wilds."
    : lead && ready.uid !== lead.uid && ready.level >= lead.level + 3 ? "A stronger lead can help."
    : "Rest often; check type matchups.";
  const routeOrder: TrainerId[] = ["tavi", "pella", "brin", "ilex", "sable", "vell"];
  // Optional earlier stops stay on MAP; an added stop must not send established saves backwards.
  const latestRouteClear = Math.max(-1, ...routeOrder.map((id, i) => state.defeatedTrainers.includes(id) ? i : -1));
  const nextId = cleared
    ? CIRCUIT_IDS.find(id => !state.defeatedTrainers.includes(id)) ?? CIRCUIT_IDS[state.circuitRematches % CIRCUIT_IDS.length]!
    : routeOrder[latestRouteClear + 1]!;
  const next = trainerEncounter(TRAINERS[nextId], state);
  const practice = cleared && !state.defeatedTrainers.includes("nix")
    ? [...CIRCUIT_IDS].reverse().find(id => state.defeatedTrainers.includes(id)) : undefined;
  return { lead, ready, training, local, kettle, underlevelled, advice, next, practice,
    repeat: state.defeatedTrainers.includes(nextId), zone: zoneAt(state.x, state.y) };
}
