export const TYPE_IDS = ["cope", "flex", "chaos", "signal", "liquid", "viral"] as const;
export type TypeId = (typeof TYPE_IDS)[number];

export const TYPE_META: Record<
  TypeId,
  { name: string; ink: readonly [number, number, number, number]; chip: string }
> = {
  cope: { name: "COPE", ink: [196, 88, 104, 255], chip: "COPE" },
  flex: { name: "FLEX", ink: [220, 172, 56, 255], chip: "FLEX" },
  chaos: { name: "CHAOS", ink: [120, 84, 156, 255], chip: "CHAOS" },
  signal: { name: "SIGNAL", ink: [64, 180, 188, 255], chip: "SIG" },
  liquid: { name: "LIQUID", ink: [56, 116, 148, 255], chip: "LIQ" },
  viral: { name: "VIRAL", ink: [80, 168, 88, 255], chip: "VIR" },
};

/** 1.5 super, 0.5 resist. Cycle plus three market rivalries. */
const SUPER: ReadonlyArray<readonly [TypeId, TypeId]> = [
  ["cope", "flex"],
  ["flex", "chaos"],
  ["chaos", "signal"],
  ["signal", "liquid"],
  ["liquid", "viral"],
  ["viral", "cope"],
  ["liquid", "cope"],
  ["flex", "viral"],
  ["chaos", "liquid"],
];

const RESIST: ReadonlyArray<readonly [TypeId, TypeId]> = [
  ["cope", "cope"],
  ["flex", "flex"],
  ["signal", "viral"],
  ["liquid", "flex"],
  ["viral", "chaos"],
  ["chaos", "flex"],
];

export function typeMod(atk: TypeId, def: TypeId[]): number {
  let m = 1;
  for (const d of def) {
    if (SUPER.some(([a, b]) => a === atk && b === d)) m *= 1.5;
    else if (RESIST.some(([a, b]) => a === atk && b === d)) m *= 0.5;
  }
  return m;
}

/** Net damage hints include both defensive types; no random rolls or battle mutation. */
export function bestTypesAgainst(def: TypeId[]): { types: TypeId[]; multiplier: number } {
  const multiplier = Math.max(...TYPE_IDS.map(type => typeMod(type, def)));
  return { types: TYPE_IDS.filter(type => typeMod(type, def) === multiplier), multiplier };
}

export function typeLabel(mod: number): string {
  if (mod >= 2.25) return "Super effective! It printed.";
  if (mod > 1) return "Super effective.";
  if (mod > 0 && mod < 1) return "Not very effective.";
  if (mod === 0) return "No bite.";
  return "";
}
