/** Locked 32-color LCD master. Every on-canvas RGB must be one of these. */

export type Rgb = readonly [number, number, number];

export const LCD = {
  ink: [24, 28, 32],
  slate: [56, 60, 64],
  lcd: [18, 28, 26],
  lcdHi: [34, 52, 46],
  paper: [244, 234, 206],
  paperDk: [212, 196, 156],
  cream: [248, 240, 216],
  white: [255, 248, 232],
  dirt0: [48, 40, 28],
  dirt1: [96, 80, 48],
  dirt2: [168, 140, 88],
  path: [220, 196, 140],
  moss0: [20, 36, 20],
  moss1: [40, 80, 40],
  moss2: [72, 124, 68],
  moss3: [140, 184, 92],
  water0: [8, 20, 36],
  water1: [28, 64, 100],
  water2: [56, 116, 148],
  foam: [188, 220, 224],
  roof0: [80, 28, 28],
  roof1: [148, 56, 52],
  wood0: [64, 36, 16],
  wood1: [148, 88, 40],
  gold: [220, 172, 56],
  goldHi: [244, 216, 112],
  rose: [196, 88, 104],
  cyan: [64, 180, 188],
  violet: [120, 84, 156],
  tan: [196, 156, 108],
  skin: [236, 208, 152],
  leaf: [80, 168, 88],
} as const satisfies Record<string, Rgb>;

export type LcdName = keyof typeof LCD;

export const LCD_LIST: readonly Rgb[] = Object.values(LCD);

export function rgbKey(c: readonly number[]): string {
  return `${c[0]},${c[1]},${c[2]}`;
}
