import type { Gfx, Rgba } from "../../engine/gfx.ts";
import { P, rgba } from "./palette.ts";
import { brickTexel, plankTexel } from "./materials.ts";
import { applyHd2dPost } from "./post.ts";
import { hd2dProp } from "./props.ts";
import { hd2dLantern } from "./tiles.ts";

/** Double-border oracle HUD panel family for clinic / stall rows. */
export function hd2dChromePanel(g: Gfx, x: number, y: number, w: number, h: number, selected = false): void {
  const fill: Rgba = rgba(selected ? P.PATH_HI : P.HUD_PANEL);
  g.fill(x - 1, y - 1, w + 2, h + 2, rgba(P.HUD_GRAY));
  g.fill(x, y, w, h, fill);
  g.rect(x, y, w, h, rgba(P.HUD_INK));
  g.rect(x + 1, y + 1, w - 2, h - 2, rgba(P.HUD_INK));
  g.hline(x + 2, y + h - 3, w - 4, rgba(P.HUD_SHADE));
  g.fill(x + w - 3, y + 2, 1, h - 4, rgba(P.HUD_SHADE));
}

export function hd2dChromeWell(g: Gfx, x: number, y: number, w: number, h: number): void {
  g.fill(x, y, w, h, rgba(P.PATH_HI));
  g.rect(x, y, w, h, rgba(P.HUD_INK));
  g.hline(x + 1, y + 1, w - 2, rgba(P.HUD_PANEL));
  g.hline(x + 1, y + h - 2, w - 2, rgba(P.PATH_MORTAR));
}

/** The same global masonry and timber samplers as the overworld, cached at native size. */
function brickBand(g: Gfx, y0: number, y1: number): void {
  for (let y = y0; y < y1; y++) for (let x = 0; x < 240; x++) g.p(x, y, rgba(brickTexel(x, y)));
}

function plankFloor(g: Gfx, y0: number): void {
  for (let y = y0; y < 160; y++) for (let x = 0; x < 240; x++) g.p(x, y, rgba(plankTexel(x, y)));
  g.hline(0, y0, 240, rgba(P.PLANK_SEAM));
  g.hline(0, y0 + 1, 240, rgba(P.PLANK_GRAIN));
}

function kettle(g: Gfx, x: number, y: number): void {
  g.fill(x + 2, y + 4, 10, 8, rgba(P.LANT_FRAME));
  g.fill(x + 3, y + 5, 8, 6, rgba(P.HUD_GRAY));
  g.fill(x + 4, y + 6, 6, 4, rgba(P.HUD_SHADE));
  g.hline(x + 2, y + 8, 10, rgba(P.CRATE_FRAME));
  g.fill(x + 11, y + 6, 4, 2, rgba(P.LANT_FRAME));
  g.fill(x + 13, y + 4, 2, 3, rgba(P.LANT_FRAME));
  g.fill(x + 5, y + 2, 4, 3, rgba(P.LANT_FRAME));
  g.p(x + 6, y, rgba(P.HUD_PANEL));
  g.p(x + 8, y + 1, rgba(P.HUD_PANEL));
  g.p(x + 10, y, rgba(P.HUD_PANEL));
}

function tin(g: Gfx, x: number, y: number): void {
  g.fill(x, y + 2, 8, 8, rgba(P.HUD_SHADE));
  g.rect(x, y + 2, 8, 8, rgba(P.HUD_INK));
  g.hline(x + 1, y + 3, 6, rgba(P.HUD_PANEL));
  g.fill(x + 1, y + 5, 6, 3, rgba(P.COIN));
  g.p(x + 6, y + 2, rgba(P.COIN_RIM));
  g.fill(x + 5, y, 3, 3, rgba(P.HUD_INK));
}

/**
 * 240×160 clinic / stall interiors on oracle brick + plank. Text chrome is drawn by the scene.
 * The raw backdrop stays palette-locked; with post on it inherits the look's grade and bloom
 * (frame off) so the lantern and window glints glow like the street outside.
 */
const interiors = new Map<string, ImageData>();

export function hd2dInterior(g: Gfx, kind: "clinic" | "shop"): void {
  const key = g.postEnabled ? `${kind}:${g.look.name}` : kind;
  const cached = interiors.get(key);
  if (cached) { g.blit(cached, 0, 0); return; }
  plankFloor(g, 24);
  brickBand(g, 0, 24);
  if (kind === "clinic") {
    g.blit(hd2dProp("window", 0, 0), 204, -6);
    kettle(g, 184, 6);
  } else {
    g.blit(hd2dLantern(), 220, 2);
    tin(g, 198, 8);
    tin(g, 208, 10);
  }
  const img = new ImageData(240, 160);
  img.data.set(g.img.data);
  if (g.postEnabled) {
    applyHd2dPost(img.data, 240, 160, { look: g.look, frame: false });
    g.blit(img, 0, 0);
  }
  interiors.set(key, img);
}
