import { applyHd2dPost, DEFAULT_LOOK, lookByName, nnScaleInto, OW_POST_SCALE, POST_SCALE, type Look } from "../art/hd2d/post.ts";
import { LCD } from "../art/lcd.ts";
import { drawText, FONT_H, wrapLines } from "./font.ts";

export const VIEW_W = 240;
export const VIEW_H = 160;
export const OW_W = 480;
export const OW_H = 320;

export type Rgba = readonly [number, number, number, number];
export type Rgb = readonly [number, number, number];

function px(c: readonly [number, number, number], a = 255): Rgba {
  return [c[0], c[1], c[2], a];
}

export const C = {
  ink: px(LCD.ink),
  paper: px(LCD.paper),
  paperDark: px(LCD.paperDk),
  lcd: px(LCD.lcd),
  lcdHi: px(LCD.lcdHi),
  cream: px(LCD.cream),
  rust: px(LCD.rose),
  moss: px(LCD.moss2),
  mossDeep: px(LCD.moss1),
  mossHi: px(LCD.moss3),
  water: px(LCD.water1),
  waterDeep: px(LCD.water0),
  waterHi: px(LCD.water2),
  gold: px(LCD.gold),
  goldHi: px(LCD.goldHi),
  rose: px(LCD.rose),
  cyan: px(LCD.cyan),
  violet: px(LCD.violet),
  hpOk: px(LCD.leaf),
  hpMid: px(LCD.gold),
  hpLow: px(LCD.rose),
  shadow: [24, 28, 32, 90] as Rgba,
  white: px(LCD.white),
  black: px(LCD.ink),
  slate: px(LCD.slate),
  foam: px(LCD.foam),
  dirt: px(LCD.dirt2),
  dirtDeep: px(LCD.dirt1),
};

export class Gfx {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  img: ImageData;
  scale = 3;
  reduced = false;
  postEnabled = true;
  postScene = false;
  /** Active post look (`?look=texture|grok`) and the overworld cloud frame (`?frame=0`, key F). */
  look: Look = DEFAULT_LOOK;
  frameEnabled = true;
  wideOw = false;
  scene: ImageData | null = null;
  /** Set by the scene each frame; the posted frame is reused while it is unchanged. */
  sceneKey = "";
  lastPostMs = 0;
  /** Time of the most recent full post-chain run (present() reuses the cached frame otherwise). */
  lastChainMs = 0;
  private uiImg: ImageData;
  private owImg: ImageData | null = null;
  private hi: ImageData | null = null;
  private posted: ImageData | null = null;
  private postedKey = "";

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) throw new Error("canvas");
    this.ctx = ctx;
    this.uiImg = ctx.createImageData(VIEW_W, VIEW_H);
    this.img = this.uiImg;
    const q = new URLSearchParams(window.location.search);
    if (q.get("post") === "0") this.postEnabled = false;
    if (q.get("frame") === "0") this.frameEnabled = false;
    this.look = lookByName(q.get("look"));
    this.fit();
    window.addEventListener("resize", () => this.fit());
  }

  get vw(): number {
    return this.img.width;
  }

  get vh(): number {
    return this.img.height;
  }

  beginFrame(wide: boolean): void {
    this.wideOw = wide;
    if (wide) {
      if (!this.owImg) this.owImg = new ImageData(OW_W, OW_H);
      this.img = this.owImg;
    } else {
      this.img = this.uiImg;
    }
  }

  fit(): void {
    const pad = 48;
    const nw = this.wideOw ? OW_W : VIEW_W;
    const nh = this.wideOw ? OW_H : VIEW_H;
    const tw = Math.max(nw, window.innerWidth - pad);
    const th = Math.max(nh, window.innerHeight - (window.innerWidth < 820 ? 220 : 80));
    this.scale = Math.max(1, Math.min(4, Math.floor(Math.min(tw / nw, th / nh))));
    this.canvas.style.width = `${nw * this.scale}px`;
    this.canvas.style.height = `${nh * this.scale}px`;
  }

  clear(c: Rgba = C.lcd): void {
    const d = this.img.data;
    for (let i = 0; i < d.length; i += 4) {
      d[i] = c[0];
      d[i + 1] = c[1];
      d[i + 2] = c[2];
      d[i + 3] = 255;
    }
  }

  p(x: number, y: number, c: Rgba): void {
    const xi = x | 0;
    const yi = y | 0;
    if (xi < 0 || yi < 0 || xi >= this.vw || yi >= this.vh) return;
    const o = (yi * this.vw + xi) * 4;
    const d = this.img.data;
    if (c[3] >= 255) {
      d[o] = c[0];
      d[o + 1] = c[1];
      d[o + 2] = c[2];
      d[o + 3] = 255;
      return;
    }
    const a = c[3] / 255;
    d[o] = (c[0] * a + d[o]! * (1 - a)) | 0;
    d[o + 1] = (c[1] * a + d[o + 1]! * (1 - a)) | 0;
    d[o + 2] = (c[2] * a + d[o + 2]! * (1 - a)) | 0;
    d[o + 3] = 255;
  }

  fill(x: number, y: number, w: number, h: number, c: Rgba): void {
    const x0 = Math.max(0, x | 0);
    const y0 = Math.max(0, y | 0);
    const x1 = Math.min(this.vw, (x | 0) + (w | 0));
    const y1 = Math.min(this.vh, (y | 0) + (h | 0));
    for (let yy = y0; yy < y1; yy++) {
      for (let xx = x0; xx < x1; xx++) this.p(xx, yy, c);
    }
  }

  rect(x: number, y: number, w: number, h: number, c: Rgba): void {
    this.fill(x, y, w, 1, c);
    this.fill(x, y + h - 1, w, 1, c);
    this.fill(x, y, 1, h, c);
    this.fill(x + w - 1, y, 1, h, c);
  }

  hline(x: number, y: number, w: number, c: Rgba): void {
    this.fill(x, y, w, 1, c);
  }

  panel(x: number, y: number, w: number, h: number, fill: Rgba = C.paper, ink: Rgba = C.ink): void {
    this.fill(x, y, w, h, fill);
    this.rect(x, y, w, h, ink);
    this.rect(x + 1, y + 1, w - 2, h - 2, ink);
    this.hline(x + 2, y + 2, w - 4, C.cream);
    this.hline(x + 2, y + h - 3, w - 4, C.paperDark);
    this.fill(x + w - 3, y + 3, 1, h - 6, C.paperDark);
  }

  text(x: number, y: number, s: string, c: Rgba = C.ink, wrap = 0): number {
    return drawText(this.img, x | 0, y | 0, s, c, wrap);
  }

  textShadow(x: number, y: number, s: string, c: Rgba = C.cream, sh: Rgba = C.ink): void {
    this.text(x + 1, y + 1, s, sh);
    this.text(x, y, s, c);
  }

  lines(x: number, y: number, s: string, cols: number, c: Rgba = C.ink): number {
    const rows = wrapLines(s, cols);
    let yy = y;
    for (const row of rows) {
      this.text(x, yy, row, c);
      yy += FONT_H;
    }
    return yy;
  }

  blit(
    src: ImageData,
    dx: number,
    dy: number,
    opts?: { flipX?: boolean; alpha?: number; scale?: number },
  ): void {
    const a = opts?.alpha ?? 1;
    const flip = opts?.flipX ?? false;
    const scale = Math.max(1, (opts?.scale ?? 1) | 0);
    for (let y = 0; y < src.height; y++) {
      for (let x = 0; x < src.width; x++) {
        const sx = flip ? src.width - 1 - x : x;
        const o = (y * src.width + sx) * 4;
        const sa = src.data[o + 3]! / 255;
        if (sa <= 0) continue;
        const col: Rgba = [
          src.data[o]!,
          src.data[o + 1]!,
          src.data[o + 2]!,
          Math.round(255 * sa * a),
        ];
        if (scale === 1) this.p(dx + x, dy + y, col);
        else this.fill(dx + x * scale, dy + y * scale, scale, scale, col);
      }
    }
  }

  bar(x: number, y: number, w: number, h: number, t: number, fill: Rgba, back: Rgba = C.ink): void {
    this.fill(x, y, w, h, back);
    const inner = Math.max(0, Math.round((w - 2) * Math.max(0, Math.min(1, t))));
    this.fill(x + 1, y + 1, inner, h - 2, fill);
  }

  hpColor(t: number): Rgba {
    if (t > 0.5) return C.hpOk;
    if (t > 0.2) return C.hpMid;
    return C.hpLow;
  }

  captureScene(): void {
    if (!this.scene || this.scene.width !== this.vw || this.scene.height !== this.vh) {
      this.scene = new ImageData(this.vw, this.vh);
    }
    this.scene.data.set(this.img.data);
  }

  present(): void {
    const sw = this.img.width;
    const sh = this.img.height;
    if (!this.postScene || !this.postEnabled || !this.scene) {
      if (this.canvas.width !== sw) {
        this.canvas.width = sw;
        this.canvas.height = sh;
      }
      this.fit();
      this.ctx.imageSmoothingEnabled = false;
      this.ctx.putImageData(this.img, 0, 0);
      return;
    }
    const t0 = performance.now();
    const scale = sw >= OW_W ? OW_POST_SCALE : POST_SCALE;
    const hw = sw * scale;
    const hh = sh * scale;
    if (this.canvas.width !== hw) {
      this.canvas.width = hw;
      this.canvas.height = hh;
    }
    this.fit();
    if (!this.hi || this.hi.width !== hw) {
      this.hi = new ImageData(hw, hh);
      this.posted = new ImageData(hw, hh);
      this.postedKey = "";
    }
    const hi = this.hi;
    const posted = this.posted!;
    const key = `${this.look.name}:${this.frameEnabled ? 1 : 0}:${this.sceneKey}`;
    if (key !== this.postedKey || !this.sceneKey) {
      const c0 = performance.now();
      nnScaleInto(this.scene, posted, scale);
      applyHd2dPost(posted.data, hw, hh, { look: this.look, frame: this.frameEnabled });
      this.lastChainMs = performance.now() - c0;
      this.postedKey = key;
    }
    hi.data.set(posted.data);
    const hud = this.img;
    const scene = this.scene;
    for (let y = 0; y < sh; y++) {
      for (let x = 0; x < sw; x++) {
        const o = (y * sw + x) * 4;
        if (
          hud.data[o] === scene.data[o] &&
          hud.data[o + 1] === scene.data[o + 1] &&
          hud.data[o + 2] === scene.data[o + 2]
        ) {
          continue;
        }
        for (let oy = 0; oy < scale; oy++) {
          for (let ox = 0; ox < scale; ox++) {
            const d = ((y * scale + oy) * hw + (x * scale + ox)) * 4;
            hi.data[d] = hud.data[o]!;
            hi.data[d + 1] = hud.data[o + 1]!;
            hi.data[d + 2] = hud.data[o + 2]!;
          }
        }
      }
    }
    this.ctx.imageSmoothingEnabled = false;
    this.ctx.putImageData(hi, 0, 0);
    this.lastPostMs = performance.now() - t0;
  }
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function idleBob(now: number, reduced: boolean, period = 420): number {
  if (reduced) return 0;
  return Math.floor(now / period) % 2;
}

export function approach(cur: number, target: number, step: number): number {
  if (cur < target) return Math.min(target, cur + step);
  if (cur > target) return Math.max(target, cur - step);
  return target;
}
