import { moveById, type MoveDef } from "../data/moves.ts";
import { speciesById, type SpeciesId } from "../data/species.ts";
import { uidFromRng, type Rng } from "../engine/rng.ts";

export const LEVEL_CAP = 30;

export interface MoveSlot {
  id: string;
  pp: number;
}

export interface Mon {
  uid: string;
  speciesId: SpeciesId;
  nick: string;
  level: number;
  exp: number;
  hp: number;
  drip: { hp: number; atk: number; def: number; spd: number };
  moves: MoveSlot[];
}

export function statOf(m: Mon, key: "hp" | "atk" | "def" | "spd"): number {
  const sp = speciesById(m.speciesId);
  const base = sp[key];
  const d = m.drip[key];
  if (key === "hp") return Math.floor(((base * 2 + d) * m.level) / 100) + m.level + 10;
  return Math.floor(((base * 2 + d) * m.level) / 100) + 5;
}

export function maxHp(m: Mon): number {
  return statOf(m, "hp");
}

export function mintMon(rng: Rng, speciesId: SpeciesId, level: number): Mon {
  const sp = speciesById(speciesId);
  const mon: Mon = {
    uid: uidFromRng(rng),
    speciesId,
    nick: sp.name,
    level: Math.max(1, Math.min(LEVEL_CAP, Math.floor(level))),
    exp: 0,
    hp: 1,
    drip: {
      hp: rng.int(0, 15),
      atk: rng.int(0, 15),
      def: rng.int(0, 15),
      spd: rng.int(0, 15),
    },
    moves: sp.moves.map((id) => ({ id, pp: moveById(id).pp })),
  };
  mon.hp = maxHp(mon);
  return mon;
}

export function cloneMon(m: Mon): Mon {
  return {
    ...m,
    drip: { ...m.drip },
    moves: m.moves.map((s) => ({ ...s })),
  };
}

export function usableMoves(m: Mon): MoveSlot[] {
  return m.moves.filter((s) => s.pp > 0);
}

export function moveDef(slot: MoveSlot): MoveDef {
  return moveById(slot.id);
}

export function healMon(m: Mon, amount: number): number {
  const before = m.hp;
  m.hp = Math.min(maxHp(m), m.hp + amount);
  return m.hp - before;
}

export function restoreAll(m: Mon): void {
  m.hp = maxHp(m);
  for (const slot of m.moves) slot.pp = moveById(slot.id).pp;
}

export function expToNext(level: number): number {
  return 12 + level * 8;
}

/** Evolution never refills PP, including exhausted inherited moves in old saves. */
export function upgradeMoves(m: Mon): string[] {
  const upgrades = speciesById(m.speciesId).moveUpgrades;
  const learned: string[] = [];
  if (!upgrades) return learned;
  m.moves = m.moves.map((slot) => {
    const id = upgrades[slot.id];
    if (!id) return slot;
    learned.push(id);
    const spent = moveById(slot.id).pp - slot.pp;
    return { id, pp: Math.max(0, Math.min(slot.pp, moveById(id).pp - spent)) };
  });
  return learned;
}

export interface Evolution {
  from: SpeciesId;
  to: SpeciesId;
  level: number;
  upgradedMoves?: string[];
}

export interface GrowthResult {
  leveled: boolean;
  levels: number;
  evolutions: Evolution[];
}

export function grantExp(m: Mon, amount: number): GrowthResult {
  m.exp += Number.isFinite(amount) ? Math.max(0, Math.floor(amount)) : 0;
  let levels = 0;
  const evolutions: Evolution[] = [];
  while (m.level < LEVEL_CAP && m.exp >= expToNext(m.level)) {
    m.exp -= expToNext(m.level);
    const ratio = m.hp / maxHp(m);
    m.level += 1;
    const sp = speciesById(m.speciesId);
    if (sp.evolvesTo && sp.evolveLevel !== undefined && m.level >= sp.evolveLevel) {
      m.speciesId = sp.evolvesTo;
      // Preserve identity and custom moves; inherited slots gain their evolved signatures.
      if (m.nick === sp.name) m.nick = speciesById(sp.evolvesTo).name;
      const upgradedMoves = upgradeMoves(m);
      evolutions.push({ from: sp.id, to: sp.evolvesTo, level: m.level,
        ...(upgradedMoves.length ? { upgradedMoves } : {}) });
    }
    m.hp = ratio === 0 ? 0 : Math.max(1, Math.round(maxHp(m) * ratio));
    levels += 1;
  }
  if (m.level >= LEVEL_CAP) m.exp = 0;
  return { leveled: levels > 0, levels, evolutions };
}

export function isFaint(m: Mon): boolean {
  return m.hp <= 0;
}
