export interface CircuitState {
  seed?: string;
  defeatedTrainers: readonly TrainerId[];
  circuitRematches: number;
  circuitPracticeWins?: Partial<Record<CircuitTrainerId, number>>;
}

export function isCircuitTrainer(id: TrainerId): id is CircuitTrainerId {
  return CIRCUIT_IDS.some(circuitId => circuitId === id);
}

/** Preview and battle resolve the same roster without drawing from combat RNG. Only wins rotate it. */
export function trainerEncounter(trainer: TrainerDef, state: CircuitState): TrainerDef {
  if (!isCircuitTrainer(trainer.id) || !state.defeatedTrainers.includes(trainer.id)) return trainer;
  const practicing = !CIRCUIT_IDS.every(id => state.defeatedTrainers.includes(id));
  const wins = practicing ? state.circuitPracticeWins?.[trainer.id] ?? 0
    : Math.floor(state.circuitRematches / CIRCUIT_IDS.length);
  const variants = CIRCUIT_LINEUPS[trainer.id];
  const offset = hashSeed(`${state.seed ?? "drippond"}:${trainer.id}:lineup`) % variants.length;
  const lineup = variants[(offset + wins) % variants.length]!;
  return { ...trainer, team: lineup.team, intro: lineup.intro, defeat: lineup.defeat,
    lossAdvice: lineup.lossAdvice, lineup: lineup.name };
}

/** A saved rotation gives repeatable training without replaying first-clear gifts. */
export function trainerLock(trainer: TrainerDef, state: CircuitState): string | null {
  const index = CIRCUIT_IDS.findIndex((id) => id === trainer.id);
  const defeated = state.defeatedTrainers;
  if (index < 0) return defeated.includes(trainer.id) ? trainer.after : null;
  if (!defeated.includes("vell")) return "Clear Vell's Lv19-22 trial in Chartwood first. Then meet Rook at Yield Yard's south kettle.";
  if (!defeated.includes(trainer.id)) {
    if (index > 0 && !defeated.includes(CIRCUIT_IDS[index - 1]!)) {
      return `First, earn a stamp from ${TRAINERS[CIRCUIT_IDS[index - 1]!].name} on the south path.`;
    }
    return null;
  }
  if (!CIRCUIT_IDS.every((id) => defeated.includes(id))) return null; // Practice while earning the remaining stamps.
  const next = TRAINERS[CIRCUIT_IDS[state.circuitRematches % CIRCUIT_IDS.length]!];
  return next.id === trainer.id ? null : `Next lap stop: ${next.name}. Follow Rook, Mica, then Nix; rest between duels.`;
}

export function trainerChallenge(trainer: TrainerDef, state: CircuitState): string {
  const encounter = trainerEncounter(trainer, state);
  const next = CIRCUIT_IDS.find(id => !state.defeatedTrainers.includes(id));
  if (state.defeatedTrainers.includes(trainer.id) && trainer.rematchPrize && next) {
    return `${encounter.lineup}. Practice: ${trainer.rematchPrize}. Next: ${TRAINERS[next].name}. Ready?`;
  }
  return state.defeatedTrainers.includes(trainer.id) && trainer.rematchPrize
    ? `Lap ${Math.floor(state.circuitRematches / CIRCUIT_IDS.length) + 2}: ${encounter.lineup}. Win: ${trainer.rematchPrize} plus crew drip. Ready?`
    : trainer.challenge;
}

export function trainerAt(x: number, y: number): TrainerDef | undefined {
  return Object.values(TRAINERS).find((t) => t.x === x && t.y === y);
}
