import { attackPose, attackTiming, drawAttack, hitSprite, type AttackCue } from "../art/battleMotion.ts";
import { B, battleList, battleMessage, battlePanel, battlePlate, battleSelection, battleStage, battleTactics } from "../art/battle.ts";
import { capsuleSprite } from "../art/world.ts";
import { creatureSprite } from "../art/creatures.ts";
import { ITEMS, type ItemId } from "../data/items.ts";
import { GRASS_QUIET, WAKE } from "../data/map.ts";
import { moveById, moveEffectLabel, type MoveDef } from "../data/moves.ts";
import { speciesById } from "../data/species.ts";
import { CIRCUIT_IDS, TRAINERS, isCircuitTrainer, trainerEncounter, trainerLock, type TrainerDef } from "../data/trainers.ts";
import { TYPE_META, typeMod } from "../data/types.ts";
import { C, idleBob } from "../engine/gfx.ts";
import type { Ctx } from "../game/ctx.ts";
import {
  applyWinExp,
  bountyFor,
  catchChance,
  clearLoweredStats,
  effStat,
  guardBreakHint,
  statDropHint,
  attackPpHint,
  pickWildMove,
  throwCapsule,
  tickShown,
  useMove,
  wrapBattle,
  type BattleMon,
} from "../game/combat.ts";
import { isFaint, maxHp, mintMon, moveDef, usableMoves, type Evolution } from "../game/mon.ts";
import { bagAdd, bagCount, clinicHeal, commitRng, living, markCaught, markSeen, persist, stashMon } from "../game/save.ts";
import type { Scene, ScenePayload } from "../game/scenes.ts";
import { wrapIndex } from "../ui/menu.ts";

type Phase =
  | "intro"
  | "text"
  | "command"
  | "tactics"
  | "concede"
  | "moves"
  | "pack"
  | "crew"
  | "catch"
  | "attack"
  | "evolve";

type Next = Phase | (() => void);

const CMD = ["FIGHT", "PACK", "CREW", "RUN"];
const THROW_MS = 260;
const SHAKE_MS = 360;

export function battleScene(ctx: Ctx): Scene {
  let you: BattleMon;
  let foe: BattleMon;
  let trainer: TrainerDef | undefined;
  let partnerIndex = 0;
  let foeOpened = false;
  let phase: Phase = "intro";
  let cmd = 0;
  let moveI = 0;
  let packI = 0;
  let crewI = 0;
  let intro = 0;
  let slide = 0;
  let queue: string[] = [];
  let shown = "";
  let waiting = false;
  let afterText: Next = "command";
  let textT = 0;
  let textHold = 0;
  let catchT = 0;
  let shakes = 0;
  let catchOk = false;
  let catchItem: ItemId = "capsule";
  let captured = false;
  let evolutions: Evolution[] = [];
  let evolutionT = 0;
  let afterEvolutions: () => void = () => leaveBattle();
  let previewFlash = 0;
  let previewAt = -1;
  const previewSeen = new Set<number>();
  let attack: (AttackCue & {
    user: BattleMon;
    target: BattleMon;
    lines: string[];
    done: () => void;
  }) | null = null;

  function resolveAttack(): void {
    if (!attack || attack.result) return;
    const { user, target, move } = attack;
    // One resolution at contact. The visual clock never rolls dice or copies combat state.
    const r = useMove(ctx.rng, user, target, move);
    if (user === foe) foeOpened = true;
    attack.result = r;
    commitRng(ctx.state, ctx.rng);
    if (!r.hit) ctx.audio.back();
    else if (r.crit) ctx.audio.crit();
    else if (r.dmg) ctx.audio.hit();
    else if (move.fx?.kind === "heal") ctx.audio.heal();
    else ctx.audio.confirm();
    attack.lines = r.dmg ? [`${r.crit ? "CRITICAL HIT! " : ""}${target.mon.nick} takes ${r.dmg} HP.`] : [];
    attack.lines.push(...r.notes.filter((note) => note !== "CRITICAL HIT!"));
    tickShown(user, ctx.reduced, 0);
    tickShown(target, ctx.reduced, 0);
  }

  function finishAttack(): void {
    if (!attack) return;
    const { lines, done } = attack;
    attack = null;
    say(lines, done, 120);
    shown = lines[0] ?? "";
    waiting = true;
  }

  function say(lines: string[], next: Next, hold = 0): void {
    queue = lines.filter(Boolean);
    shown = ctx.reduced ? queue[0] ?? "" : "";
    waiting = ctx.reduced;
    textT = 0;
    textHold = hold;
    afterText = next;
    phase = "text";
  }

  function finishText(): void {
    if (typeof afterText === "function") afterText();
    else phase = afterText;
  }

  function typeTick(): void {
    if (queue.length === 0) {
      finishText();
      return;
    }
    const full = queue[0]!;
    textT += ctx.dt;
    shown = full.slice(0, ctx.reduced || waiting ? full.length : Math.floor(textT / 18));
    waiting = shown.length === full.length;
  }

  function settled(): boolean {
    return [you, foe].every((b) => b.shownHp === b.mon.hp && (!isFaint(b.mon) || b.faint === 1));
  }

  function advanceText(): void {
    if (!waiting) {
      shown = queue[0] ?? "";
      waiting = true;
      return;
    }
    if (textT < textHold || (textHold > 0 && !settled())) return;
    queue.shift();
    shown = ctx.reduced ? queue[0] ?? "" : "";
    waiting = ctx.reduced;
    textT = 0;
    textHold = 0;
    if (queue.length === 0) finishText();
  }

  function packItems(): { id: ItemId; n: number }[] {
    const ids: ItemId[] = ["sip", "fullcope", "capsule", "gloss", "myth", "cleartea"];
    return ids.map((id) => ({ id, n: bagCount(ctx.state, id) })).filter((x) => x.n > 0);
  }

  function sendLead(): void {
    const mon = living(ctx.state)[0] ?? ctx.state.party[0]!;
    you = wrapBattle(mon);
  }

  function act(user: BattleMon, target: BattleMon, mv: MoveDef, done: () => void): void {
    if (isFaint(user.mon) || isFaint(target.mon)) {
      done();
      return;
    }
    if (user.flinched) {
      user.flinched = false;
      say([`${user.mon.nick} flinches! Lost the turn.`], done);
      return;
    }
    say([`${user.mon.nick} uses ${mv.name}!`], () => {
      attack = { user, target, move: mv, own: user === you, elapsed: 0, result: null, lines: [], done };
      phase = "attack";
      if (ctx.reduced) {
        resolveAttack();
        finishAttack();
      }
    });
  }

  function wildAct(): void {
    act(foe, you, opponentMove(), afterActions);
  }

  function opponentMove(): MoveDef {
    const opening = trainer?.team[partnerIndex]?.openingMove;
    if (!foeOpened && opening && foe.mon.moves.some((m) => m.id === opening && m.pp > 0)) return moveById(opening);
    return pickWildMove(ctx.rng, foe, you);
  }

  function sendNextPartner(): void {
    const partner = trainer!.team[++partnerIndex]!;
    foe = wrapBattle(mintMon(ctx.rng, partner.species, partner.level));
    markSeen(ctx.state, partner.species);
    commitRng(ctx.state, ctx.rng);
    foeOpened = false;
    cmd = moveI = 0;
    previewSeen.clear();
    const forced = isFaint(you.mon);
    if (forced) crewI = ctx.state.party.findIndex((m) => !isFaint(m));
    say([`${trainer!.name} sends ${foe.mon.nick}!`, partner.arrival ?? "",
      forced ? "Send the next meme." : ""], forced ? "crew" : "command");
  }

  function leaveBattle(blackout = false): void {
    if (blackout) {
      ctx.state.x = WAKE.x;
      ctx.state.y = WAKE.y;
      clinicHeal(ctx.state);
    }
    commitRng(ctx.state, ctx.rng);
    persist(ctx.state);
    ctx.pop();
  }

  function lossPenalty(): number {
    return Math.min(ctx.state.money, Math.max(20, Math.floor(ctx.state.money * 0.1)));
  }

  function nextEvolution(): void {
    if (!evolutions.length) {
      afterEvolutions();
      return;
    }
    evolutionT = 0;
    phase = "evolve";
    ctx.audio.heal();
  }

  function finishVictory(blackout = false): void {
    afterEvolutions = () => leaveBattle(blackout);
    nextEvolution();
  }

  function afterActions(): void {
    commitRng(ctx.state, ctx.rng);
    you.flinched = foe.flinched = false;
    const lines: string[] = [];
    if (isFaint(foe.mon)) {
      const pay = bountyFor(foe.mon, false);
      ctx.state.money += pay;
      const xp = applyWinExp(you.mon, foe.mon, !!trainer);
      evolutions = xp.evolutions;
      lines.push(`${foe.mon.nick} is out.`, `+${pay} $MEME   +${xp.exp} drip.`);
      if (xp.leveled) lines.push(`${you.mon.nick} hits Lv${you.mon.level}.`);
      for (const reserve of living(ctx.state).filter((m) => m.uid !== you.mon.uid)) {
        const shared = applyWinExp(reserve, foe.mon, !!trainer, 0.5);
        evolutions.push(...shared.evolutions);
        lines.push(`${reserve.nick} +${shared.exp} crew drip.${shared.leveled ? ` Lv${reserve.level}!` : ""}`);
      }
      for (const evolution of evolutions) markCaught(ctx.state, evolution.to);
      ctx.audio.catchOk();
    }
    if (isFaint(you.mon)) {
      you.mon.hp = 0;
      lines.push(`${you.mon.nick} is out.`);
      if (living(ctx.state).length === 0) {
        const loss = lossPenalty();
        ctx.state.money -= loss;
        say([...lines, `The crew is cooked. -${loss} $MEME`, trainer?.lossAdvice ?? "",
          "Waking up at Cope Clinic."], () => finishVictory(true));
        ctx.audio.fail();
        return;
      }
      if (!isFaint(foe.mon)) {
        crewI = ctx.state.party.findIndex((m) => !isFaint(m));
        say([...lines, "Send the next meme."], "crew");
        return;
      }
    }
    if (isFaint(foe.mon)) {
      if (trainer && partnerIndex + 1 < trainer.team.length) {
        say(lines, () => {
          afterEvolutions = sendNextPartner;
          nextEvolution();
        });
        return;
      }
      if (trainer) {
        const rematch = ctx.state.defeatedTrainers.includes(trainer.id);
        const prize = rematch ? trainer.rematchPrize ?? 0 : trainer.prize;
        const practicing = rematch && !CIRCUIT_IDS.every(id => ctx.state.defeatedTrainers.includes(id));
        if (rematch && !practicing) ctx.state.circuitRematches += 1;
        if (practicing && isCircuitTrainer(trainer.id)) ctx.state.circuitPracticeWins[trainer.id] += 1;
        if (!rematch) ctx.state.defeatedTrainers.push(trainer.id);
        ctx.state.money += prize;
        lines.push(`${trainer.name}: ${trainer.defeat}`, `Duel won! +${prize} $MEME prize.`);
        if (!rematch && trainer.supplies) {
          bagAdd(ctx.state, trainer.supplies.id, trainer.supplies.count);
          lines.push(`Packed ${trainer.supplies.count} ${ITEMS[trainer.supplies.id].name}.`);
        }
        if (!rematch && trainer.id === "ilex") {
          lines.push("Recipe delivered! Clear Tea now sells at Signal Stall.");
        }
        if (trainer.rematchPrize) {
          const next = CIRCUIT_IDS.find(id => !ctx.state.defeatedTrainers.includes(id))
            ?? CIRCUIT_IDS[(CIRCUIT_IDS.findIndex(id => id === trainer!.id) + 1) % CIRCUIT_IDS.length]!;
          lines.push(practicing ? "Practice won! No extra stamp or supplies." : !rematch && trainer.id === "nix"
            ? "Circuit cleared! Repeat laps are open." : "Circuit stamp earned.",
            `Next: ${TRAINERS[next].name}. Rest at a kettle first.`);
        }
      }
      say(lines, () => finishVictory());
      return;
    }
    phase = "command";
  }

  function fight(moveIndex: number): void {
    const slots = usableMoves(you.mon);
    const slot = slots.length ? slots[Math.min(moveIndex, slots.length - 1)]! : { id: "flailPost", pp: 1 };
    const mv = moveDef(slot);
    const wildMove = opponentMove();
    const yourSpd = effStat(you, "spd");
    const theirSpd = effStat(foe, "spd");
    const youFirst = yourSpd > theirSpd || (yourSpd === theirSpd && ctx.rng.chance(0.5));
    you.flinched = foe.flinched = false;
    if (youFirst) {
      act(you, foe, mv, () => act(foe, you, wildMove, afterActions));
    } else {
      act(foe, you, wildMove, () => act(you, foe, mv, afterActions));
    }
  }

  function runAway(): void {
    if (trainer) {
      phase = "concede";
      return;
    }
    const youSpd = effStat(you, "spd");
    const foeSpd = effStat(foe, "spd");
    const ok = ctx.rng.chance(Math.max(0.1, Math.min(0.95, 0.5 + (youSpd - foeSpd) * 0.05)));
    commitRng(ctx.state, ctx.rng);
    if (ok) {
      say(["Got out of the thread."], () => leaveBattle());
    } else {
      say(["They cut you off."], wildAct);
    }
  }

  function usePack(id: ItemId): void {
    if (bagCount(ctx.state, id) <= 0) return;
    const def = ITEMS[id];
    if (def.kind === "cleanse") {
      if (!clearLoweredStats(you)) {
        say(["No lowered stats. Save the tea."], "pack");
        return;
      }
      bagAdd(ctx.state, id, -1);
      ctx.audio.heal();
      say([`${you.mon.nick} drinks ${def.name}.`, "Lowered stats cleared. Boosts kept."], wildAct, ctx.reduced ? 120 : 280);
      return;
    }
    if (def.kind === "heal") {
      if (you.mon.hp >= maxHp(you.mon)) {
        say(["Already full."], "pack");
        return;
      }
      bagAdd(ctx.state, id, -1);
      you.mon.hp = Math.min(maxHp(you.mon), you.mon.hp + (def.heal ?? 22));
      ctx.audio.heal();
      tickShown(you, ctx.reduced, 0);
      say([`${you.mon.nick} drinks ${def.name}.`], wildAct, ctx.reduced ? 120 : 280);
      return;
    }
    if (def.kind === "capsule") {
      if (trainer) {
        say(["A trainer's partner cannot be caught."], "pack");
        return;
      }
      bagAdd(ctx.state, id, -1);
      const roll = throwCapsule(ctx.rng, foe.mon, id);
      commitRng(ctx.state, ctx.rng);
      catchItem = id;
      shakes = roll.shakes;
      catchOk = roll.caught;
      catchT = 0;
      phase = "catch";
      ctx.audio.confirm();
    }
  }

  function finishCatch(): void {
    if (catchOk) {
      captured = true;
      markCaught(ctx.state, foe.mon.speciesId);
      const where = stashMon(ctx.state, foe.mon);
      const pay = bountyFor(foe.mon, true);
      ctx.state.money += pay;
      persist(ctx.state);
      ctx.audio.catchOk();
      say(
        [
          `Gotcha! ${foe.mon.nick} is yours.`,
          where === "pc" ? "Party full. Stashed in the Meme Box." : "Joined the crew.",
          `+${pay} $MEME`,
        ],
        () => leaveBattle(),
      );
    } else {
      ctx.audio.fail();
      say(["It popped out!"], wildAct);
    }
  }

  function armPreview(index: number): void {
    moveI = index;
    if (previewSeen.has(index)) {
      previewFlash = 0;
      previewAt = -1;
      return;
    }
    previewSeen.add(index);
    previewAt = index;
    previewFlash = ctx.reduced ? 0 : 320;
  }

  return {
    id: "battle",
    enter(payload?: ScenePayload) {
      trainer = payload?.trainer ? TRAINERS[payload.trainer] : undefined;
      if (trainer && trainerLock(trainer, ctx.state)) {
        ctx.pop();
        return;
      }
      if (trainer) trainer = trainerEncounter(trainer, ctx.state);
      partnerIndex = 0;
      foeOpened = false;
      const first = trainer?.team[0];
      const wild = first ? mintMon(ctx.rng, first.species, first.level) : payload?.wild;
      if (!wild) {
        ctx.pop();
        return;
      }
      sendLead();
      foe = wrapBattle(wild);
      markSeen(ctx.state, wild.speciesId);
      commitRng(ctx.state, ctx.rng);
      phase = "intro";
      intro = 0;
      slide = ctx.reduced ? 1 : 0;
      cmd = 0;
      moveI = 0;
      captured = false;
      evolutions = [];
      evolutionT = 0;
      attack = null;
      previewFlash = 0;
      previewAt = -1;
      previewSeen.clear();
      queue = [];
      if (ctx.shot === "catch") {
        slide = 1;
        phase = "catch";
        catchItem = "gloss";
        shakes = 3;
        catchOk = true;
        catchT = THROW_MS + SHAKE_MS;
      }
      if (!trainer && ["battle", "evolve", "batch-a", "evolve-a", "batch-b", "evolve-b", "kits"].includes(ctx.shot ?? "")) {
        slide = 1;
        phase = "command";
      }
      if (ctx.shot === "moves") {
        slide = 1;
        phase = "moves";
        previewSeen.add(0);
        previewAt = 0;
        previewFlash = 2000;
      }
    },
    exit() {
      ctx.grassQuiet = GRASS_QUIET;
    },
    update() {
      if (!you || !foe) return;
      tickShown(you, ctx.reduced, ctx.dt);
      tickShown(foe, ctx.reduced, ctx.dt);

      if (phase === "evolve") {
        evolutionT += ctx.dt;
        if (ctx.reduced || evolutionT >= 1100) {
          const evolution = evolutions.shift()!;
          const evolved = speciesById(evolution.to);
          const upgrades = (evolution.upgradedMoves ?? []).map((id) => moveById(id).name);
          say([`${speciesById(evolution.from).name} evolved into ${evolved.name}!`,
            upgrades.length ? `Kit upgraded: ${upgrades.join(" / ")}.` : ""], nextEvolution);
        }
        ctx.input.consumeAny("Enter", "Escape");
        return;
      }

      if (phase === "attack" && attack) {
        const timing = attackTiming(attack.move);
        attack.elapsed = ctx.reduced ? timing.duration : Math.min(timing.duration, attack.elapsed + ctx.dt);
        if (attack.elapsed >= timing.impact) resolveAttack();
        if (attack.elapsed >= timing.duration) finishAttack();
        // Confirm/back cannot skip contact, replay damage or spend a second PP.
        ctx.input.consumeAny("Enter", "Escape");
        return;
      }

      if (phase === "intro") {
        intro += ctx.dt;
        slide = ctx.reduced ? 1 : 1 - (1 - Math.min(1, intro / 420)) ** 3;
        if (ctx.reduced || intro >= 560) {
          say(trainer
            ? [`${trainer.name}: ${trainer.intro}`, `${trainer.name} sends ${foe.mon.nick}!`,
              trainer.team[0].arrival ?? "", `Go, ${you.mon.nick}!`]
            : [`A wild ${foe.mon.nick} rustles out!`, `Go, ${you.mon.nick}!`], "command");
        }
        return;
      }

      if (phase === "text") {
        typeTick();
        if (ctx.input.consumeAny("Enter", "Escape")) {
          ctx.audio.confirm();
          advanceText();
        }
        return;
      }

      if (phase === "catch") {
        if (ctx.shot === "catch") {
          if (!ctx.input.consumeAny("Enter", "Escape")) return;
          ctx.shot = null;
        }
        const before = catchT;
        catchT += ctx.dt;
        if (ctx.reduced) {
          finishCatch();
          return;
        }
        for (let n = 0; n < shakes; n++) {
          const at = THROW_MS + n * SHAKE_MS;
          if (before < at && catchT >= at) ctx.audio.catchShake();
        }
        if (catchT >= THROW_MS + shakes * SHAKE_MS + 300) finishCatch();
        return;
      }

      if (phase === "concede") {
        if (ctx.input.consume("Escape")) {
          ctx.audio.back();
          phase = "command";
        } else if (ctx.input.consume("Enter")) {
          const loss = lossPenalty();
          ctx.state.money -= loss;
          ctx.audio.fail();
          say([`Duel conceded. -${loss} $MEME`, trainer?.lossAdvice ?? "",
            "Returning to Cope Clinic."], () => leaveBattle(true));
        }
        return;
      }

      if (phase === "tactics") {
        if (ctx.input.consumeAny("Enter", "Escape")) {
          ctx.audio.back();
          phase = "command";
        }
        return;
      }

      if (phase === "command") {
        const d = ctx.input.dirPressed();
        if (d) {
          cmd = wrapIndex(cmd, 4, d.x, d.y, 2);
          ctx.audio.cursor();
        }
        if (ctx.input.consume("Escape")) {
          ctx.audio.confirm();
          phase = "tactics";
          return;
        }
        if (ctx.input.consume("Enter")) {
          ctx.audio.confirm();
          if (cmd === 0) {
            const n = usableMoves(you.mon).length;
            moveI = Math.min(moveI, Math.max(0, n - 1));
            previewSeen.clear();
            armPreview(moveI);
            phase = "moves";
          } else if (cmd === 1) {
            packI = 0;
            phase = "pack";
          } else if (cmd === 2) {
            crewI = 0;
            phase = "crew";
          } else runAway();
        }
        return;
      }

      if (phase === "moves") {
        if (previewFlash > 0) previewFlash = Math.max(0, previewFlash - ctx.dt);
        const slots = usableMoves(you.mon);
        const n = Math.max(1, slots.length);
        const d = ctx.input.dirPressed();
        if (d) {
          const next = wrapIndex(moveI, n, 0, d.y, 1);
          ctx.audio.cursor();
          armPreview(next);
        }
        if (ctx.input.consume("Escape")) {
          ctx.audio.back();
          phase = "command";
          return;
        }
        if (ctx.input.consume("Enter")) {
          ctx.audio.confirm();
          fight(moveI);
        }
        return;
      }

      if (phase === "pack") {
        const items = packItems();
        packI = Math.min(packI, Math.max(0, items.length - 1));
        if (items.length === 0) {
          if (ctx.input.consumeAny("Enter", "Escape")) {
            ctx.audio.back();
            phase = "command";
          }
          return;
        }
        const d = ctx.input.dirPressed();
        if (d) {
          packI = wrapIndex(packI, items.length, 0, d.y, 1);
          ctx.audio.cursor();
        }
        if (ctx.input.consume("Escape")) {
          ctx.audio.back();
          phase = "command";
          return;
        }
        if (ctx.input.consume("Enter")) {
          ctx.audio.confirm();
          usePack(items[packI]!.id);
        }
        return;
      }

      if (phase === "crew") {
        const d = ctx.input.dirPressed();
        if (d) {
          crewI = wrapIndex(crewI, ctx.state.party.length, 0, d.y, 1);
          ctx.audio.cursor();
        }
        if (ctx.input.consume("Escape")) {
          if (isFaint(you.mon)) {
            say(["Pick a living meme to keep fighting."], "crew");
          } else {
            ctx.audio.back();
            phase = "command";
          }
          return;
        }
        if (ctx.input.consume("Enter")) {
          const pick = ctx.state.party[crewI]!;
          if (isFaint(pick)) {
            ctx.audio.fail();
            say([`${pick.nick} is out. Pick a living meme.`], "crew");
            return;
          }
          if (pick.uid === you.mon.uid) {
            phase = "command";
            return;
          }
          ctx.audio.confirm();
          const forced = isFaint(you.mon);
          you = wrapBattle(pick);
          moveI = 0;
          say([`Go, ${pick.nick}!`], forced ? "command" : wildAct);
        }
      }
    },
    draw() {
      const g = ctx.g;
      battleStage(g);

      if (phase === "evolve" && evolutions[0]) {
        const evolution = evolutions[0];
        battlePanel(g, 48, 4, 144, 98);
        g.text(90, 10, "EVOLUTION", C.gold);
        const id = evolutionT < 440 ? evolution.from : evolution.to;
        const src = creatureSprite(id, "front");
        const flash = !ctx.reduced && evolutionT >= 340 && evolutionT < 500;
        g.blit(flash ? hitSprite(src) : src, 88, 28, { scale: 2 });
        if (!ctx.reduced) {
          for (let i = 0; i < 8; i++) {
            const angle = i * Math.PI / 4 + evolutionT / 1300;
            const x = Math.round(120 + Math.cos(angle) * 58);
            const y = Math.round(61 + Math.sin(angle) * 32);
            g.fill(x - 2, y, 5, 1, C.goldHi);
            g.fill(x, y - 2, 1, 5, C.goldHi);
          }
        }
        battleMessage(g, `${speciesById(evolution.from).name} is evolving!`, false);
        return;
      }

      const drawFighter = (b: BattleMon, own: boolean) => {
        const faint = ctx.reduced && isFaint(b.mon) ? 1 : b.faint;
        if (faint >= 1 || (!own && (captured || phase === "catch"))) return;
        const pose = attack?.user === b && !ctx.reduced ? attackPose(attack) : { x: 0, y: 0 };
        const shake = b.shake > 0 && !ctx.reduced ? (Math.floor(b.shake / 35) % 2 ? 2 : -2) : 0;
        const bob = shake === 0 && (phase === "command" || phase === "moves") ? idleBob(ctx.now, ctx.reduced) : 0;
        const x = Math.round(own ? 16 - (1 - slide) * 64 : 148 + (1 - slide) * 96);
        const y = own ? 58 : 8;
        g.fill(x + 8 + pose.x, y + 29 + pose.y, 23, 3, C.shadow);
        const src = creatureSprite(b.mon.speciesId, own ? "back" : "front");
        g.blit(b.flash > 0 && !ctx.reduced ? hitSprite(src) : src,
          x + shake + pose.x, y + pose.y + Math.round(faint * 10) - bob, { alpha: 1 - faint });
      };
      // The attacker passes in front at contact, in either direction.
      if (attack?.user === foe) {
        if (you) drawFighter(you, true);
        if (foe) drawFighter(foe, false);
      } else {
        if (foe) drawFighter(foe, false);
        if (you) drawFighter(you, true);
      }
      if (attack && !ctx.reduced) drawAttack(g, attack);

      if (foe) battlePlate(g, foe, false, trainer?.boss ? "BOSS" : !!trainer);
      if (you) battlePlate(g, you, true);
      if (trainer) {
        battlePanel(g, 4, 39, 74, 12);
        g.text(9, 42, `${trainer.boss ? "TRIAL" : "TEAM"} ${partnerIndex + 1}/${trainer.team.length}`, B.ink);
      } else if (phase === "pack") {
        const item = packItems()[packI]?.id;
        if (item && ITEMS[item].kind === "capsule") {
          battlePanel(g, 4, 39, 74, 12);
          g.text(9, 42, `CATCH ${Math.round(catchChance(foe.mon, item) * 100)}%`, B.ink);
        }
      }

      if (phase === "tactics") {
        battleTactics(g, you, foe, guardBreakHint(you, foe, ctx.state.party) ?? attackPpHint(you, ctx.state.party) ?? statDropHint(you, foe));
      } else if (phase === "concede") {
        battlePanel(g, 4, 110, 232, 46);
        g.text(10, 114, "CONCEDE THIS DUEL?", B.ink);
        g.text(10, 124, "Return to Cope Clinic.", B.ink);
        g.text(10, 134, `Lose ${lossPenalty()} $MEME. No duel prize.`, B.muted);
        g.text(10, 146, "B keep fighting   A concede", B.ink);
      } else if (phase === "intro") {
        battleMessage(g, trainer ? `${trainer.name} steps forward!` : "The grass twitches...", false);
      } else if (phase === "attack" && attack) {
        battleMessage(g, attack.lines[0] ?? `${attack.user.mon.nick} uses ${attack.move.name}!`, false, attack.move.name.toUpperCase());
      } else if (phase === "text") {
        battleMessage(g, shown, waiting && textT >= textHold && (textHold === 0 || settled()));
      } else if (phase === "command") {
        battlePanel(g, 4, 110, 232, 46);
        g.fill(110, 111, 1, 43, B.shade);
        g.text(10, 116, trainer ? trainer.name : "What now?", B.ink);
        g.text(10, 130, attackPpHint(you, ctx.state.party) ? "No attack PP" : `${ctx.state.money} $MEME`, B.muted);
        g.text(10, 145, "A pick B tactics", B.muted);
        CMD.forEach((label, n) => {
          const x = 115 + (n % 2) * 59;
          const y = 116 + Math.floor(n / 2) * 19;
          if (n === cmd) battleSelection(g, x - 1, y - 2, 57, 15);
          g.text(x + 3, y + 2, `${n === cmd ? ">" : " "}${label}`, B.ink);
        });
      } else if (phase === "moves") {
        const slots = usableMoves(you.mon);
        const rows = slots.length ? slots : [{ id: "flailPost", pp: 1 }];
        battlePanel(g, 4, 110, 140, 46);
        rows.forEach((slot, n) => {
          const def = moveDef(slot);
          const live = you.mon.moves.find((m) => m.id === def.id);
          const y = 114 + n * 10;
          const chip = TYPE_META[def.type];
          if (n === moveI) battleSelection(g, 6, y - 1, 136, 9, chip.ink);
          g.fill(8, y, 6, 6, chip.ink);
          g.rect(8, y, 6, 6, C.ink);
          g.text(16, y, `${n === moveI ? ">" : " "}${def.name}`, C.ink);
          g.text(124, y, `${live?.pp ?? 0}`.padStart(2, " "), C.ink);
        });
        const slot = rows[moveI] ?? rows[0]!;
        const mv = moveDef(slot);
        const live = you.mon.moves.find((m) => m.id === mv.id);
        battlePanel(g, 148, 110, 88, 46);
        const chip = TYPE_META[mv.type];
        g.fill(152, 114, 32, 8, chip.ink);
        g.rect(152, 114, 32, 8, C.ink);
        g.text(153, 115, chip.chip, C.cream);
        g.text(187, 115, mv.power ? `POW ${mv.power}` : "STATUS", C.ink);
        if (mv.power > 0 && previewFlash > 0 && previewAt === moveI && foe) {
          const mod = typeMod(mv.type, speciesById(foe.mon.speciesId).types);
          if (mod > 1) {
            g.fill(186, 114, 46, 8, C.goldHi);
            g.rect(186, 114, 46, 8, C.ink);
            g.text(188, 115, "SUPER", C.ink);
          } else if (mod > 0 && mod < 1) {
            g.fill(186, 114, 46, 8, C.paperDark);
            g.rect(186, 114, 46, 8, C.ink);
            g.text(187, 115, "RESIST", C.ink);
          }
        }
        g.text(152, 126, `PP ${(live?.pp ?? 0)}/${mv.pp}`, C.ink);
        g.text(152, 134, `ACC ${you.sureHit ? 100 : mv.acc}%`, C.ink);
        g.text(152, 144, moveEffectLabel(mv), C.ink);
      } else if (phase === "pack") {
        const items = packItems();
        if (!items.length) battleMessage(g, "Pack is empty.", true);
        else {
          battleList(
            g,
            items.map((it) => `${ITEMS[it.id].name} x${it.n}`),
            packI,
          );
        }
      } else if (phase === "crew") {
        battleList(
          g,
          ctx.state.party.map((m) => `${m.nick}  ${m.hp}/${maxHp(m)}`),
          crewI,
        );
      } else if (phase === "catch") {
        const elapsed = Math.max(0, catchT - THROW_MS);
        const n = Math.min(shakes, Math.floor(elapsed / SHAKE_MS) + 1);
        const beatT = elapsed % SHAKE_MS;
        const wobble = !ctx.reduced && catchT >= THROW_MS && elapsed < shakes * SHAKE_MS && beatT < 180
          ? Math.round(Math.sin(beatT / 180 * Math.PI * 2) * 3) : 0;
        const tint =
          catchItem === "myth" ? ([220, 172, 56] as const) : catchItem === "gloss" ? ([56, 116, 148] as const) : ([196, 88, 104] as const);
        const cap = capsuleSprite(tint);
        const flight = ctx.reduced ? 1 : Math.min(1, catchT / THROW_MS);
        const cx = Math.round(28 + flight * 108) + wobble;
        const cy = Math.round(44 - flight * 16 - Math.sin(flight * Math.PI) * 18);
        g.fill(cx + 6, cy + 30, 20, 3, [16, 20, 18, 90]);
        g.blit(cap, cx, cy, { scale: 2 });
        battleMessage(g, catchT < THROW_MS ? "Tin out!" : n ? `Latch ${n}/3...` : "Hold...", false);
      }
    },
  };
}
