export function moveById(id: string): MoveDef {
  const m = peekMove(id);
  if (!m) throw new Error(`move ${id}`);
  return m;
}

export function peekMove(id: string): MoveDef | null {
  return Object.prototype.hasOwnProperty.call(MOVES, id) ? MOVES[id]! : null;
}

/** Thirteen bitmap cells fit the move-detail well without hiding PP or accuracy. */
export function moveEffectLabel(move: MoveDef): string {
  const fx = move.fx;
  if (!fx) return move.crit > 0 ? `CRIT ${Math.round(6 + move.crit * 8)}%` : "DIRECT HIT";
  if (fx.kind === "stat") return `${fx.target === "self" ? "SELF" : "FOE"} ${fx.stat.toUpperCase()} ${fx.stages > 0 ? "+" : ""}${fx.stages}`;
  if (fx.kind === "heal") return `HEAL ${Math.round(fx.pct * 100)}%`;
  if (fx.kind === "drain") return `DRAIN ${Math.round(fx.pct * 100)}%`;
  if (fx.kind === "recoil") return `RECOIL ${Math.round(fx.pct * 100)}%`;
  if (fx.kind === "flinch") return `FLINCH ${Math.round(fx.chance * 100)}%`;
  return "NEXT HIT 100%";
}
