import { ORACLE } from "./palette.ts";

/**
 * Native-resolution scene passes from render_styles.py: prop drop shadow + contact AO.
 * Grok look: the key light sits beyond the upper-left corner, so contact shadows are soft-edged
 * and stretch toward the lower-right instead of the oracle's hard 0.28 ellipse.
 */
export const SCENE = {
  shadowAlpha: 0.3,
  shadowDy: 2,
  /** Tail length toward +x as a fraction of the base half-width. */
  shadowStretch: 0.6,
  aoAlpha: 0.22,
  aoPx: 4,
} as const;

/**
 * Soft contact shadow at a prop's ground line: the left edge stays under the base, the tail
 * feathers toward the lower-right, and alpha plateaus under the core before fading at the rim.
 */
export function shadeEllipse(img: ImageData, cx: number, cy: number, rx: number, ry: number): void {
  const [fr, fg, fb] = ORACLE.SHADOW_FILL;
  const a0 = SCENE.shadowAlpha;
  const tail = Math.round(rx * SCENE.shadowStretch);
  const half = tail >> 1;
  const ccx = cx + half;
  const ccy = cy + (ry > 3 ? 1 : 0);
  const rrx = rx + half + 1;
  const rry = ry + 1;
  const w = img.width;
  const h = img.height;
  const d = img.data;
  for (let y = Math.max(0, ccy - rry); y <= Math.min(h - 1, ccy + rry); y++) {
    const ny = (y - ccy) / rry;
    for (let x = Math.max(0, ccx - rrx); x <= Math.min(w - 1, ccx + rrx); x++) {
      const nx = (x - ccx) / rrx;
      const d2 = nx * nx + ny * ny;
      if (d2 > 1) continue;
      // Slightly denser under the base (left) than along the tail.
      const core = Math.min(1, (1 - d2) * 2.2);
      const a = a0 * core * core * (3 - 2 * core) * (nx > 0 ? 1 - 0.25 * nx : 1);
      const o = (y * w + x) * 4;
      d[o] = d[o]! * (1 - a) + fr * a;
      d[o + 1] = d[o + 1]! * (1 - a) + fg * a;
      d[o + 2] = d[o + 2]! * (1 - a) + fb * a;
    }
  }
}

/** Multiplicative contact band under a base edge; strength eases out to 0 over `px` rows. */
export function aoBand(img: ImageData, x0: number, x1: number, y: number, px: number, alpha = SCENE.aoAlpha): void {
  const w = img.width;
  const h = img.height;
  const d = img.data;
  const xa = Math.max(0, x0);
  const xb = Math.min(w, x1);
  for (let i = 0; i < px; i++) {
    const yy = y + i;
    if (yy < 0 || yy >= h) continue;
    const t = 1 - i / px;
    const f = 1 - alpha * t * t * (3 - 2 * t);
    for (let x = xa; x < xb; x++) {
      const o = (yy * w + x) * 4;
      d[o] = d[o]! * f;
      d[o + 1] = d[o + 1]! * f;
      d[o + 2] = d[o + 2]! * f;
    }
  }
}
