import { P, type Rgb } from "./palette.ts";
import { thash } from "./seed.ts";

/**
 * Global-coordinate material samplers. Every masonry / lawn / water pattern is keyed on the
 * GLOBAL pixel (gx, gy) so joints, tufts and caustics run continuous across 16px tile seams.
 * Key light sits beyond the upper-left corner: lit edges face up/left, shade and contact
 * shadows fall down/right. Every returned colour is a locked palette entry.
 */

/** Surface-only noise: never consumes game RNG. Avalanche avoids stripes in low hash bits. */
export function grain(x: number, y: number, salt = 0): number {
  let h = thash(x, y, salt);
  h = Math.imul(h ^ (h >>> 16), 0x7feb352d);
  h = Math.imul(h ^ (h >>> 15), 0x846ca68b);
  return (h ^ (h >>> 16)) >>> 0;
}

const mod = (n: number, d: number): number => ((n % d) + d) % d;

// ---------------------------------------------------------------------------
// stone / sand
// ---------------------------------------------------------------------------

/**
 * One limestone sett, also used by perspective battle cobbles. Recessed dark joint on the
 * right/bottom, shaded bevel inside it, lit bevel on the top/left, and a face that turns away
 * from the light toward its lower-right with rubbed crown, pits, grit and a rare crack.
 */
export function stoneTexel(x: number, y: number, w: number, h: number, seed: number): Rgb {
  const n = grain(x, y, seed);
  if (x === w - 1 || y === h - 1) {
    if (y === h - 1 && n % 61 === 0) return P.BED_STEM;
    if (n % 29 === 0) return P.SAND_DK;
    if (n % 5 === 0) return P.PATH_MORTAR;
    return P.PATH_DOT;
  }
  if (y === h - 2 || x === w - 2) return n % 7 === 0 ? P.PATH_DOT : P.PATH_MORTAR;
  if (y === 0 || x === 0) return n % 9 === 0 ? P.PATH_MID : P.PATH_HI;
  const pale = seed % 4 === 0;
  let col: Rgb = pale ? P.PATH_HI : P.PATH_MID;
  const shade = x / w + y / h;
  if (shade > 1.2 && n % 3 !== 0) col = pale ? P.PATH_MID : P.PATH_MORTAR;
  else if (shade < 0.75 && grain(x >> 1, y >> 1, seed + 1) % 3 === 0) col = P.PATH_HI;
  if (n % 37 === 0) col = P.PATH_MORTAR;
  if (n % 53 === 0) col = P.SAND;
  if (n % 89 === 0) col = P.SAND_DK;
  const crackX = 3 + (seed >>> 8) % Math.max(1, w - 7);
  if (seed % 7 === 0 && y < Math.min(4, h - 2) && x === crackX + (y >> 1)) col = P.PATH_DOT;
  return col;
}

export function cobbleTexel(gx: number, gy: number): Rgb {
  const row = Math.floor(gy / 8), off = mod(row, 2) * 8;
  const stone = Math.floor((gx + off) / 16);
  return stoneTexel(mod(gx + off, 16), mod(gy, 8), 16, 8, grain(stone, row, 5));
}

export function brickTexel(gx: number, gy: number): Rgb {
  const row = Math.floor(gy / 4), off = mod(row, 2) * 4;
  const x = mod(gx + off, 8), y = mod(gy, 4);
  const brick = grain(Math.floor((gx + off) / 8), row, 7);
  if (y === 3) return x === 7 ? P.BRICK_DK : P.BRICK_SEAM;
  if (x === 7) return P.BRICK_DK;
  if (y === 2 && brick % 3 === 0) return P.BRICK_SEAM;
  if (y === 0 && x > 0 && x < 6 && (brick + x) % 5 === 0) return P.PLANK_HI;
  if (brick % 11 === 0 || grain(gx, gy, 17) % 31 === 0) return P.BRICK_SEAM;
  return P.BRICK_FACE;
}

/** Barrel tiles: alternating clay channels, chipped lips, recessed overlapping courses. */
export function roofTexel(gx: number, gy: number): Rgb {
  const row = Math.floor(gy / 8), off = mod(row, 2) * 4;
  const x = mod(gx + off, 8), y = mod(gy, 8);
  const tile = grain(Math.floor((gx + off) / 8), row, 13);
  if (y === 7) return x > 5 ? P.BRICK_DK : P.BRICK_SEAM;
  if (x === 7 || (x === 6 && tile % 3 === 0)) return P.BRICK_DK;
  if (x >= 5 || (x === 0 && y > 0)) return P.BRICK_SEAM;
  if (y === 6 && x >= 1 && x <= 4) return (tile + x) % 4 === 0 ? P.PLANK_HI : P.BRICK_FACE;
  if (x === 1 && y < 5 && (tile + y) % 4 !== 0) return P.PLANK_HI;
  if (tile % 5 === 0 && x === 4) return P.BRICK_SEAM;
  if (grain(gx, gy, 23) % 41 === 0) return P.BRICK_SEAM;
  return P.BRICK_FACE;
}

/** Board lengths and grain are global, including knots that cross 16px tile boundaries. */
export function plankTexel(gx: number, gy: number): Rgb {
  const row = Math.floor(gy / 8), off = mod(row, 3) * 11;
  const board = Math.floor((gx + off) / 40), x = mod(gx + off, 40), y = mod(gy, 8);
  const seed = grain(board, row, 8);
  if (y === 7) return P.PLANK_SEAM;
  if (x === 39) return P.PLANK_GRAIN;
  if (y === 0) return (x + seed) % 13 === 0 ? P.PLANK : P.PLANK_HI;
  if ((x === 2 || x === 36) && y === 2 && seed % 3 === 0) return P.PLANK_SEAM;
  const dx = x - (10 + seed % 20), dy = y - 4;
  const ring = dx * dx + dy * dy * 5;
  if (seed % 3 !== 0 && ring <= 17) {
    if (ring <= 1) return P.PLANK_SEAM;
    if (ring >= 9) return dy < 0 ? P.PLANK_HI : P.PLANK_GRAIN;
  }
  const bend = Math.abs(dx) < 7 ? 1 : 0;
  if ((y === 2 + bend || y === 5 + bend) && grain(Math.floor((gx + off) / 7), row, y) % 4 !== 0) return P.PLANK_GRAIN;
  if (y === 1 && grain(Math.floor(gx / 6), row, 31) % 3 === 0) return P.PLANK_HI;
  return seed % 7 === 0 && y > 4 ? P.PLANK_GRAIN : P.PLANK;
}

/** Trodden plaza sand: paired grains, compacted silt patches and small lit pebbles. */
export function sandTexel(gx: number, gy: number): Rgb {
  const n = grain(gx, gy, 4);
  const cx = Math.floor(gx / 9), cy = Math.floor(gy / 7);
  const cell = grain(cx, cy, 12);
  if (cell % 4 === 0) {
    const px = cx * 9 + 1 + cell % 7, py = cy * 7 + 1 + (cell >>> 4) % 5;
    if (gx === px && gy === py) return P.SAND_DK;
    if (gx === px + 1 && gy === py) return P.PATH_DOT;
    if (gx === px && gy === py - 1) return P.SAND_LT;
    if (gx === px + 1 && gy === py + 1) return P.SAND_DK;
  }
  if (n % 29 === 0) return P.SAND_DK;
  if (n % 43 === 0) return P.SAND_LT;
  if (n % 137 === 0) return P.SAND_RARE;
  const patch = grain(Math.floor(gx / 7), Math.floor(gy / 5), 14);
  const dx = mod(gx, 7) - 3, dy = mod(gy, 5) - 2;
  if (patch % 5 === 0 && dx * dx + dy * dy * 2 < 7 && n % 4 !== 0) return P.PATH_MID;
  if (grain(gx - 1, gy - 1, 4) % 29 === 0) return P.PATH_MID;
  return P.SAND;
}

// ---------------------------------------------------------------------------
// lawn
// ---------------------------------------------------------------------------

interface LawnTone {
  ground: Rgb;
  blade: Rgb;
  tip: Rgb;
  dark: Rgb;
  deep: Rgb;
}

// Stalks read darker than the ground with a lit tip, so a 1px tuft still separates at 2× blit.
const LAWN_NORMAL: LawnTone = { ground: P.GRASS, blade: P.GRASS_DK, tip: P.ROWG_HI, dark: P.BED_GREEN, deep: P.BED_STEM };
const LAWN_SUNLIT: LawnTone = { ground: P.GRASS_LT, blade: P.GRASS, tip: P.ROWG_HI, dark: P.GRASS_DK, deep: P.BED_GREEN };
const LAWN_SHADE: LawnTone = { ground: P.GRASS_DK, blade: P.BED_GREEN, tip: P.GRASS_LT, dark: P.BED_STEM, deep: P.BED_STEM };

/** Flock tone: two offset, jittered patch grids give sunlit sweeps and shaded hollows with soft borders. */
function lawnTone(gx: number, gy: number, n: number): LawnTone {
  const jx = n % 3 - 1, jy = (n >>> 3) % 3 - 1;
  const flock = grain(Math.floor((gx + jx) / 12), Math.floor((gy + jy) / 10), 21) % 7;
  const flock2 = grain(Math.floor((gx + 6 + jy) / 9), Math.floor((gy + 4 + jx) / 7), 22) % 5;
  if (flock <= 1 && flock2 < 3) return LAWN_SUNLIT;
  if (flock === 6 || (flock === 5 && flock2 === 4)) return LAWN_SHADE;
  return LAWN_NORMAL;
}

const FLOWER_OFFSETS = [[0, 0], [3, 1], [-2, 2]] as const;
const FLOWER_PETALS: readonly Rgb[] = [P.FLOWER_PET, P.SC_HAIR, P.SAND_LT, P.FLOWER_PET];

/** Wildflower clusters: one 24×24 region in five carries 2–3 four-petal flowers with stems and a leaf. */
function lawnFlower(gx: number, gy: number): Rgb | null {
  const rx = Math.floor(gx / 24), ry = Math.floor(gy / 24);
  const rh = grain(rx, ry, 47);
  if (rh % 5 !== 0) return null;
  const cx = rx * 24 + 5 + rh % 14, cy = ry * 24 + 5 + (rh >>> 4) % 14;
  const count = 2 + (rh >>> 8) % 2;
  for (let i = 0; i < count; i++) {
    const [ox, oy] = FLOWER_OFFSETS[i]!;
    const dx = gx - cx - ox, dy = gy - cy - oy;
    if (dx === 0 && dy === 0) return P.FLOWER_CORE;
    if (Math.abs(dx) + Math.abs(dy) === 1) return FLOWER_PETALS[(rh >>> (12 + i * 2)) % 4]!;
    if (dx === 0 && (dy === 2 || dy === 3)) return P.BED_STEM;
    if (dx === 1 && dy === 3) return P.GRASS_LT;
  }
  return null;
}

/**
 * Flocked lawn readable at 2× blit: a lattice of 2–5px tufts with lit tips, leaning tops and a
 * rooted shadow pixel, an offset lattice of 1–2px short blades between them, dithered ground
 * and wildflower clusters — all over the sunlit / shaded flock patches.
 */
export function grassTexel(gx: number, gy: number): Rgb {
  const flower = lawnFlower(gx, gy);
  if (flower) return flower;
  const n = grain(gx, gy, 19);
  const t = lawnTone(gx, gy, n);
  // Tall tufts on a 4×6 lattice; tip, lean and root shadow all stay inside the cell.
  const c1x = Math.floor(gx / 4), c1y = Math.floor(gy / 6);
  const s1 = grain(c1x, c1y, 41);
  const bxi = s1 % 4;
  const bx = c1x * 4 + bxi;
  const hgt = 2 + (s1 >>> 4) % 4;
  const base = c1y * 6 + 5;
  const top = base - hgt + 1;
  let lean = hgt >= 4 && (s1 >>> 8) % 3 === 0 ? ((s1 >>> 10) % 2 ? 1 : -1) : 0;
  if (bxi === 3 && lean === 1) lean = -1;
  else if (bxi === 0 && lean === -1) lean = 1;
  const tuft = (s1 >>> 14) % 5 !== 0;
  if (tuft) {
    if (gy === top && gx === bx + lean) return (s1 >>> 12) % 3 ? t.tip : P.GRASS_LT;
    if (gx === bx && gy > top && gy < base) return t.blade;
    if (gx === bx && gy === base) return t.dark;
    if (bxi < 3 && gx === bx + 1 && gy === base) return t.dark;
  }
  // Short blades on the offset lattice: lit tip over a dark foot.
  const c2x = Math.floor((gx + 2) / 4), c2y = Math.floor((gy + 3) / 6);
  const s2 = grain(c2x, c2y, 43);
  const bx2 = c2x * 4 - 2 + s2 % 4;
  const base2 = c2y * 6 + 2;
  const hgt2 = 1 + (s2 >>> 4) % 2;
  if (gx === bx2 && gy <= base2 && gy > base2 - hgt2) return gy === base2 && hgt2 === 2 ? t.blade : P.GRASS_LT;
  // Ground: sparse darker holes, rare deep pits and lit specks.
  if (n % 17 === 0) return t.blade;
  if (n % 43 === 0) return t.deep;
  if (t === LAWN_SUNLIT && n % 97 === 0) return P.SAND_LT;
  return t.ground;
}

/**
 * Tall encounter grass: furrow bands every 8 rows with 3–5px blades rising from the dark row
 * into the lit row, lit seed tips and a sparse second layer of short blades.
 */
export function tallGrassTexel(gx: number, gy: number): Rgb {
  const p = mod(gy, 8);
  const band = Math.floor(gy / 8);
  const n = grain(gx, gy, 32);
  const c = Math.floor(gx / 3);
  const s = grain(c, band, 45);
  const bxi = s % 3;
  const bx = c * 3 + bxi;
  const hgt = 3 + (s >>> 4) % 3;
  if (gx === bx && p >= 8 - hgt) {
    if (p === 8 - hgt) return P.ROWG_HI;
    if (p === 7) return P.ROWG_DEEP;
    return p >= 5 ? P.ROWG_BASE : P.ROWG_DARK;
  }
  // Second stalk of the clump: one column over, a row shorter, so each tuft reads two pixels wide.
  const bx2 = bxi === 2 ? bx - 1 : bx + 1;
  if (gx === bx2 && p >= 9 - hgt && hgt >= 4) {
    if (p === 9 - hgt) return P.ROWG_HI;
    if (p === 7) return P.ROWG_DEEP;
    return p >= 5 ? P.ROWG_BASE : P.ROWG_DARK;
  }
  if (gx === bx2 && p === 7) return P.ROWG_DEEP;
  if (p >= 5) return p === 7 && n % 4 === 0 ? P.ROWG_DEEP : n % 13 === 0 ? P.ROWG_DEEP : P.ROWG_DARK;
  if (n % 11 === 0) return P.ROWG_DARK;
  if (n % 47 === 0) return P.ROWG_HI;
  return P.ROWG_BASE;
}

// ---------------------------------------------------------------------------
// water
// ---------------------------------------------------------------------------

const CAUSTIC_DRIFT = [0, 1, 2, 1] as const;

/** Sorted distances to the three nearest jittered cell centres (Worley), for the caustic web. */
function causticF(gx: number, gy: number, salt: number): [number, number, number] {
  const cw = 17, ch = 11;
  const cx = Math.floor(gx / cw), cy = Math.floor(gy / ch);
  let f1 = 1e9, f2 = 1e9, f3 = 1e9;
  for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) {
    const h = grain(cx + ox, cy + oy, salt);
    const px = (cx + ox) * cw + 1 + h % (cw - 2);
    const py = (cy + oy) * ch + 1 + (h >>> 8) % (ch - 2);
    const dx = gx - px, dy = (gy - py) * 1.3;
    const d = dx * dx + dy * dy;
    if (d < f1) { f3 = f2; f2 = f1; f1 = d; } else if (d < f2) { f3 = f2; f2 = d; } else if (d < f3) f3 = d;
  }
  return [Math.sqrt(f1), Math.sqrt(f2), Math.sqrt(f3)];
}

interface Crest {
  on: boolean;
  seed: number;
  x: number;
  start: number;
  y: number;
  crest: number;
}

function crestAt(gx: number, gy: number, phase: number): Crest {
  const band = Math.floor(gy / 9), segment = Math.floor((gx + band * 7) / 24);
  const seed = grain(segment, band, 6), x = mod(gx + band * 7, 24);
  const crest = 2 + seed % 4 + (phase === 1 || phase === 2 ? 1 : 0);
  const y = mod(gy, 9), start = 3 + (seed >>> 8) % 7;
  return { on: x >= start && x < start + 7 && y === crest, seed, x, start, y, crest };
}

/** Key-light glint centre riding a ripple crest; the drawn sparkle is a 2px dash with a cross. */
function glintAt(gx: number, gy: number, phase: number): boolean {
  return crestAt(gx, gy, phase).on && grain(gx, gy, 29 + phase) % 13 === 0;
}

/**
 * Pond body as drawn structure: a slow caustic web with pale nodes, two-tone depth patches,
 * gently looping ripple crests and cross-shaped glints that twinkle with the phase. Only the
 * crests, glints and a one-pixel web drift move, so the body stays calm.
 */
export function waterTexel(gx: number, gy: number, phase = 0): Rgb {
  if (glintAt(gx, gy, phase) || glintAt(gx - 1, gy, phase)) return P.SC_HAIR_HI;
  if (glintAt(gx, gy - 1, phase) || glintAt(gx, gy + 1, phase)) return P.WIN_GLINT;
  const c = crestAt(gx, gy, phase);
  if (c.on) return P.WATER_DASH;
  if (c.x >= c.start + 2 && c.x < c.start + 5 && c.y === c.crest - 1 && (c.seed + phase) % 4 === 0) return P.WATER_EDGE;
  if (c.x >= c.start + 4 && c.x < c.start + 12 && c.y === c.crest + 2) return P.WATER_DEEP;
  const [f1, f2, f3] = causticF(gx - CAUSTIC_DRIFT[phase]!, gy, 27);
  if (f3 - f1 < 1.05) return P.WIN_GLINT;
  const breaks = grain(gx, gy, 28);
  if (f2 - f1 < 0.65) return breaks % 6 === 0 ? P.WATER_DASH : P.WATER_EDGE;
  if (f2 - f1 < 1.3 && breaks % 2 === 0) return P.WATER_DASH;
  const n = grain(gx, gy, 33);
  const deep = grain(Math.floor((gx + (n % 3)) / 14), Math.floor((gy + (n % 2)) / 9), 34) % 4 === 0;
  if (deep && n % 5 !== 0) return P.WATER_DEEP;
  return P.WATER;
}
