import { typeMod, typeLabel } from "../data/types.ts";
import { speciesById } from "../data/species.ts";
import { ITEMS, type ItemId } from "../data/items.ts";
import { MOVES, type MoveDef } from "../data/moves.ts";
import type { Rng } from "../engine/rng.ts";
import { grantExp, isFaint, maxHp, moveDef, statOf, usableMoves, type GrowthResult, type Mon } from "./mon.ts";

export interface BattleMon {
  mon: Mon;
  atk: number;
  def: number;
  spd: number;
  flash: number;
  shake: number;
  shownHp: number;
  faint: number;
  flinched: boolean;
  sureHit: boolean;
}

export function wrapBattle(mon: Mon): BattleMon {
  return {
    mon,
    atk: 0,
    def: 0,
    spd: 0,
    flash: 0,
    shake: 0,
    shownHp: mon.hp,
    faint: 0,
    flinched: false,
    sureHit: false,
  };
}

function stageMul(s: number): number {
  const c = Math.max(-6, Math.min(6, s));
  return c >= 0 ? (2 + c) / 2 : 2 / (2 - c);
}

export function effStat(b: BattleMon, key: "atk" | "def" | "spd"): number {
  return Math.max(1, Math.floor(statOf(b.mon, key) * stageMul(b[key])));
}

export function clearLoweredStats(b: BattleMon): boolean {
  let changed = false;
  for (const stat of ["atk", "def", "spd"] as const) {
    if (b[stat] < 0) {
      b[stat] = 0;
      changed = true;
    }
  }
  return changed;
}

/** Offer a guard break that the living crew can actually perform with remaining PP. */
export function guardBreakHint(you: BattleMon, foe: BattleMon, party: Mon[]): string | null {
  if (foe.def <= 0) return null;
  const candidates = [you.mon, ...party.filter(mon => mon.uid !== you.mon.uid)];
  for (const mon of candidates) {
    if (isFaint(mon)) continue;
    const slot = usableMoves(mon).find(slot => {
      const fx = moveDef(slot).fx;
      return fx?.kind === "stat" && fx.target === "foe" && fx.stat === "def" && fx.stages < 0;
    });
    if (slot) return mon === you.mon ? `Guard: try ${moveDef(slot).name}.` : `${mon.nick.slice(0, 12)} can lower foe DEF.`;
  }
  return null;
}

/** Existing drops can help from neutral stages too; name only the active partner's ready moves. */
export function statDropHint(you: BattleMon, foe: BattleMon): string | null {
  if (isFaint(you.mon) || isFaint(foe.mon)) return null;
  for (const stat of ["def", "atk"] as const) {
    if (foe[stat] <= -2) continue;
    const slot = usableMoves(you.mon).find(slot => {
      const fx = moveDef(slot).fx;
      return fx?.kind === "stat" && fx.target === "foe" && fx.stat === stat && fx.stages < 0;
    });
    if (slot) return `Lower ${stat.toUpperCase()}: ${moveDef(slot).name}.`;
  }
  return null;
}

/** Remaining support PP must not hide an attack-ready reserve during a long duel. */
export function attackPpHint(you: BattleMon, party: Mon[]): string | null {
  if (isFaint(you.mon)) return null;
  const slots = usableMoves(you.mon);
  if (slots.some(slot => moveDef(slot).power > 0)) return null;
  const reserve = party.find(mon => mon.uid !== you.mon.uid && !isFaint(mon)
    && usableMoves(mon).some(slot => moveDef(slot).power > 0));
  if (reserve) return `No attack PP: ${reserve.nick.slice(0, 12)}.`;
  return slots.length ? "No attack PP. Status moves remain." : "No PP: Flail Post costs HP.";
}

export interface StrikeResult {
  hit: boolean;
  dmg: number;
  crit: boolean;
  mod: number;
  notes: string[];
  faint: boolean;
}

export function pickWildMove(rng: Rng, me: BattleMon, foe: BattleMon): MoveDef {
  const slots = usableMoves(me.mon);
  const defs = (slots.length ? slots : [{ id: "flailPost", pp: 1 }]).map((s) => moveDef(s));
  const foeTypes = speciesById(foe.mon.speciesId).types;
  const myTypes = speciesById(me.mon.speciesId).types;
  const hpRatio = me.mon.hp / maxHp(me.mon);
  const scored = defs.map((mv) => {
    const accuracy = me.sureHit ? 1 : mv.acc / 100;
    let s = mv.power * accuracy * typeMod(mv.type, foeTypes) * (myTypes.includes(mv.type) ? 1.25 : 1);
    const fx = mv.fx;
    if (fx?.kind === "heal") s += Math.min(fx.pct, 1 - hpRatio) * (hpRatio < 0.35 ? 300 : 100);
    if (fx?.kind === "drain") s += (1 - hpRatio) * 30;
    if (fx?.kind === "recoil" && hpRatio < 0.3) s *= 0.65;
    if (fx?.kind === "stat") {
      const target = fx.target === "self" ? me : foe;
      const useful = fx.stages > 0 ? target[fx.stat] < 2 : target[fx.stat] > -2;
      const speedUseful = fx.stat !== "spd" || effStat(me, "spd") <= effStat(foe, "spd");
      if (useful && speedUseful) s += hpRatio > 0.5 ? 40 : 8;
    }
    if (fx?.kind === "surehit" && !me.sureHit && defs.some((m) => m.power > 0 && m.acc < 100)) s += 30;
    return { mv, s };
  });
  // Keep some variety, but never roll a full-HP heal or spent setup if a useful move exists.
  const useful = scored.filter(({ s }) => s > 0);
  const choices = useful.length ? useful : scored;
  const best = Math.max(...choices.map(({ s }) => s));
  return rng.pick(rng.chance(0.75) ? choices.filter(({ s }) => s === best) : choices).mv;
}

export function useMove(rng: Rng, user: BattleMon, foe: BattleMon, mv: MoveDef): StrikeResult {
  const notes: string[] = [];
  const slot = user.mon.moves.find((s) => s.id === mv.id);
  if (slot && slot.pp > 0) slot.pp -= 1;

  const acc = user.sureHit ? 100 : mv.acc;
  if (user.sureHit) user.sureHit = false;
  const hit = rng.int(1, 100) <= acc;
  if (!hit) {
    notes.push("MISS! It sails wide.");
    return { hit: false, dmg: 0, crit: false, mod: 1, notes, faint: false };
  }

  let dmg = 0;
  let crit = false;
  let mod = 1;
  if (mv.power > 0) {
    const atk = effStat(user, "atk");
    const def = effStat(foe, "def");
    const lv = user.mon.level;
    const base = Math.floor(((2 * lv) / 5 + 2) * mv.power * (atk / Math.max(1, def))) / 50 + 2;
    const userTypes = speciesById(user.mon.speciesId).types;
    const stab = userTypes.includes(mv.type) ? 1.25 : 1;
    mod = typeMod(mv.type, speciesById(foe.mon.speciesId).types);
    const critChance = 0.06 + mv.crit * 0.08;
    crit = rng.chance(critChance);
    const spread = rng.float(0.85, 1);
    dmg = Math.min(foe.mon.hp, Math.max(1, Math.floor(base * stab * mod * (crit ? 1.5 : 1) * spread)));
    foe.mon.hp = Math.max(0, foe.mon.hp - dmg);
    foe.flash = 90;
    foe.shake = crit ? 240 : 160;
    if (crit) notes.push("CRITICAL HIT!");
    const lab = typeLabel(mod);
    if (lab) notes.push(lab);
  }

  const fx = mv.fx;
  if (fx) {
    if (fx.kind === "stat") {
      const t = fx.target === "self" ? user : foe;
      const before = t[fx.stat];
      t[fx.stat] = Math.max(-6, Math.min(6, before + fx.stages));
      const who = fx.target === "self" ? user.mon.nick : foe.mon.nick;
      const dir = fx.stages > 0 ? "up" : "down";
      notes.push(`${who} ${fx.stat.toUpperCase()} ${before === t[fx.stat] ? "at limit" : dir}.`);
    } else if (fx.kind === "heal") {
      const add = Math.max(1, Math.floor(maxHp(user.mon) * fx.pct));
      user.mon.hp = Math.min(maxHp(user.mon), user.mon.hp + add);
      notes.push(`${user.mon.nick} sips the bit.`);
    } else if (fx.kind === "drain") {
      const drain = Math.max(1, Math.floor(dmg * fx.pct));
      user.mon.hp = Math.min(maxHp(user.mon), user.mon.hp + drain);
      notes.push("It siphons the joke.");
    } else if (fx.kind === "recoil") {
      const rec = Math.max(1, Math.floor(Math.max(dmg, 1) * fx.pct));
      user.mon.hp = Math.max(0, user.mon.hp - rec);
      notes.push(`${user.mon.nick} feels the bounce.`);
    } else if (fx.kind === "flinch" && rng.chance(fx.chance)) {
      foe.flinched = true;
    } else if (fx.kind === "surehit") {
      user.sureHit = true;
      notes.push("The next swing is locked.");
    }
  }

  return { hit: true, dmg, crit, mod, notes, faint: isFaint(foe.mon) };
}

export interface CatchRoll {
  shakes: number;
  caught: boolean;
}

function catchThreshold(wild: Mon, item: ItemId): number {
  if (isFaint(wild) || ITEMS[item].kind !== "capsule") return -1;
  const health = Math.max(0, Math.min(1, wild.hp / maxHp(wild)));
  const base = speciesById(wild.speciesId).catch / 100;
  const target = Math.max(0.02, Math.min(0.95, base * (1 - 0.7 * health) * (ITEMS[item].catchMul ?? 1)));
  // Three independent latches should produce the intended overall probability,
  // rather than cubing an already-low catch chance. Round down to match the 8-bit roll.
  return Math.floor(Math.cbrt(target) * 256) - 1;
}

/** Exact chance after latch quantization, shared by the preview and actual throw. */
export function catchChance(wild: Mon, item: ItemId): number {
  return ((catchThreshold(wild, item) + 1) / 256) ** 3;
}

export function throwCapsule(rng: Rng, wild: Mon, item: ItemId): CatchRoll {
  const threshold = catchThreshold(wild, item);
  if (threshold < 0) return { shakes: 0, caught: false };
  let shakes = 0;
  let caught = true;
  for (let i = 0; i < 3; i++) {
    if (rng.int(0, 255) > threshold) {
      caught = false;
      break;
    }
    shakes += 1;
  }
  if (caught) shakes = 3;
  return { shakes, caught };
}

export function bountyFor(wild: Mon, caught: boolean): number {
  const b = speciesById(wild.speciesId).bounty;
  return (caught ? 30 : 20) + wild.level * 4 + b;
}

export function expFor(wild: Mon, recipientLevel = wild.level, trainer = false): number {
  // Same-level wins take about two fights per level. Deep/evolved foes pay more;
  // returning to beginner grass yields less, while a trailing crew catches up.
  const base = 10 + wild.level * 4 + Math.floor(speciesById(wild.speciesId).bounty / 2);
  const gap = Math.max(0.25, Math.min(1.5, 1 + (wild.level - recipientLevel) * 0.08));
  return Math.max(1, Math.floor(base * gap * (trainer ? 1.25 : 1)));
}

export function applyWinExp(lead: Mon, wild: Mon, trainer = false, share = 1): GrowthResult & { exp: number } {
  const exp = Math.max(1, Math.floor(expFor(wild, lead.level, trainer) * share));
  const r = grantExp(lead, exp);
  return { ...r, exp };
}

export function tickShown(b: BattleMon, reduced: boolean, dt = 1000 / 60): void {
  if (reduced) {
    b.shownHp = b.mon.hp;
    b.flash = b.shake = 0;
    b.faint = isFaint(b.mon) ? 1 : 0;
    return;
  }
  const step = maxHp(b.mon) * Math.max(0, dt) / 560;
  if (b.shownHp > b.mon.hp) b.shownHp = Math.max(b.mon.hp, b.shownHp - step);
  else if (b.shownHp < b.mon.hp) b.shownHp = Math.min(b.mon.hp, b.shownHp + step);
  b.flash = Math.max(0, b.flash - dt);
  b.shake = Math.max(0, b.shake - dt);
  b.faint = isFaint(b.mon) && b.shownHp === 0 ? Math.min(1, b.faint + dt / 200) : 0;
}

export { MOVES };
