import { hd2dMoneyHud, hd2dSignBand } from "../art/hd2d/hud.ts";
import { hd2dNpc, hd2dPlayer, hd2dTrainer } from "../art/hd2d/player.ts";
import { TRAINERS, trainerAt, trainerChallenge, trainerEncounter, trainerLock, type TrainerDef } from "../data/trainers.ts";
import { moveById } from "../data/moves.ts";
import { hd2dProp, propCastsAo, propCastsShadow, type PropKind } from "../art/hd2d/props.ts";
import { aoBand, SCENE, shadeEllipse } from "../art/hd2d/scene.ts";
import { castsAo, hd2dLantern, hd2dTile, isArtSolid, isGroundId, mapId } from "../art/hd2d/tiles.ts";
import { P, rgba } from "../art/hd2d/palette.ts";
import {
  MAP,
  MAP_H,
  MAP_W,
  encountersAt,
  GRASS_QUIET,
  zoneAt,
  ZONES,
  TILE,
  grassEncounterChance,
  spotFacing,
  tileAt,
} from "../data/map.ts";
import { C, idleBob, OW_H, OW_W, VIEW_H, VIEW_W } from "../engine/gfx.ts";
import type { Ctx } from "../game/ctx.ts";
import { maxHp, mintMon, type Mon } from "../game/mon.ts";
import { clinicHeal, commitRng, living } from "../game/save.ts";
import type { Scene, ScenePayload } from "../game/scenes.ts";

const RUSTLE_MS = 360;

/** 2×2 props on existing Stubtown anchors (presentation only; collision untouched). */
const PROPS: readonly { kind: PropKind; tx: number; ty: number }[] = [
  { kind: "rock", tx: 15, ty: 9 },
  { kind: "lamp", tx: 9, ty: 9 },
  { kind: "lamp", tx: 2, ty: 10 },
  { kind: "tree", tx: 22, ty: 3 },
  { kind: "tree", tx: 20, ty: 12 },
  { kind: "window", tx: 22, ty: 1 },
  { kind: "window", tx: 16, ty: 12 },
  { kind: "rock", tx: 30, ty: 3 },
  { kind: "rock", tx: 40, ty: 11 },
  { kind: "tree", tx: 6, ty: 15 },
  { kind: "tree", tx: 8, ty: 26 },
  { kind: "rock", tx: 21, ty: 27 },
  { kind: "tree", tx: 40, ty: 26 },
];

/** Lantern emblems on the plank walls flanking each counter. */
const LANTERNS: readonly { tx: number; ty: number }[] = [
  { tx: 2, ty: 3 },
  { tx: 6, ty: 3 },
  { tx: 12, ty: 3 },
  { tx: 14, ty: 3 },
];

/** Sign bands hang beside each door on row 5 (the door tile stays visible). */
const SIGNS: readonly { tx: number; ty: number; tiles: number; label: string; doors: readonly number[] }[] = [
  { tx: 1, ty: 5, tiles: 3, label: "CLINIC", doors: [] },
  { tx: 11, ty: 5, tiles: 2, label: "STALL", doors: [] },
];

/** Ground-standing tiles that cast the oracle drop-shadow ellipse. */
function tileCastsShadow(id: string): boolean {
  return id === "crate" || id === "barrel" || id === "post" || id === "fence" || id === "tree";
}

const DIRS: Record<number, { x: number; y: number }> = {
  0: { x: 0, y: -1 },
  1: { x: 0, y: 1 },
  2: { x: 1, y: 0 },
  3: { x: -1, y: 0 },
};

export function overworldScene(ctx: Ctx): Scene {
  let moving = 0;
  let fromX = 0;
  let fromY = 0;
  let notice: string | null = null;
  let challenge: TrainerDef | null = null;
  let step = 0 as 0 | 1;
  let anim = 0;
  let grassStreak = 0;
  let rustle = 0;
  let rustleWild: Mon | null = null;

  const face = () => DIRS[ctx.state.dir] ?? DIRS[1]!;

  function tryStep(dx: number, dy: number): void {
    if (moving > 0) return;
    if (dx === 1) ctx.state.dir = 2;
    if (dx === -1) ctx.state.dir = 3;
    if (dy === 1) ctx.state.dir = 1;
    if (dy === -1) ctx.state.dir = 0;
    const nx = ctx.state.x + dx;
    const ny = ctx.state.y + dy;
    const tile = tileAt(nx, ny);
    if (tile.solid || trainerAt(nx, ny)) {
      ctx.audio.back();
      return;
    }
    fromX = ctx.state.x;
    fromY = ctx.state.y;
    ctx.state.x = nx;
    ctx.state.y = ny;
    moving = ctx.reduced ? 1 : 180;
    step = step === 0 ? 1 : 0;
    ctx.audio.step();
  }

  function finishStep(): void {
    moving = 0;
    const tile = tileAt(ctx.state.x, ctx.state.y);
    if (!tile.tall) return;
    if (living(ctx.state).length === 0) return;
    if (ctx.grassQuiet > 0) {
      ctx.grassQuiet -= 1;
      commitRng(ctx.state, ctx.rng);
      return;
    }
    grassStreak += 1;
    const p = grassEncounterChance(grassStreak);
    if (!ctx.rng.chance(p)) {
      commitRng(ctx.state, ctx.rng);
      return;
    }
    grassStreak = 0;
    const pool = encountersAt(ctx.state.x, ctx.state.y, ctx.state.defeatedTrainers.includes("vell"))
      .flatMap((row) => Array<typeof row>(row.w).fill(row));
    if (!pool.length) return;
    const row = ctx.rng.pick(pool);
    const lv = ctx.rng.int(row.lo, row.hi);
    const wild = mintMon(ctx.rng, row.id, lv);
    commitRng(ctx.state, ctx.rng);
    ctx.audio.encounter();
    if (ctx.reduced) {
      ctx.push("battle", { wild });
      return;
    }
    rustle = RUSTLE_MS;
    rustleWild = wild;
  }

  function interact(): void {
    const f = face();
    const trainer = trainerAt(ctx.state.x + f.x, ctx.state.y + f.y) ?? trainerAt(ctx.state.x, ctx.state.y);
    if (trainer) {
      ctx.audio.confirm();
      const locked = trainerLock(trainer, ctx.state);
      if (locked) notice = `${trainer.name}: ${locked}`;
      else if (!living(ctx.state).length) notice = "The crew needs Cope Clinic before a duel.";
      else {
        challenge = trainerEncounter(trainer, ctx.state);
        notice = `${trainer.name}: ${trainerChallenge(trainer, ctx.state)}`;
      }
      return;
    }
    const spot = spotFacing(ctx.state.x, ctx.state.y, f.x, f.y);
    if (!spot) {
      notice = "Just mud and opinions.";
      return;
    }
    ctx.audio.confirm();
    if (spot.kind === "rest") {
      clinicHeal(ctx.state);
      ctx.grassQuiet = GRASS_QUIET;
      grassStreak = 0;
      ctx.audio.heal();
      ctx.save();
      notice = `${spot.title}: ${spot.body} Crew HP and PP restored. Safe travels.`;
    } else if (spot.kind === "heal") ctx.push("clinic");
    else if (spot.kind === "shop") ctx.push("shop");
    else if (spot.kind === "pc") ctx.push("pc");
    else notice = `${spot.title}: ${ctx.state.defeatedTrainers.includes("vell") ? spot.veteranBody ?? spot.body : spot.body}`;
  }

  return {
    id: "overworld",
    enter(payload?: ScenePayload) {
      moving = 0;
      notice = payload?.notice ?? null;
      challenge = null;
      rustle = 0;
      rustleWild = null;
    },
    exit() {},
    update() {
      anim += ctx.dt;
      if (rustle > 0) {
        rustle -= ctx.dt;
        if (ctx.input.consumeAny("Enter", "Escape") || rustle <= 0) {
          const wild = rustleWild;
          rustle = 0;
          rustleWild = null;
          if (wild) ctx.push("battle", { wild });
        }
        return;
      }
      if (notice) {
        if (ctx.input.consume("Escape")) {
          notice = null;
          challenge = null;
        } else if (ctx.input.consume("Enter")) {
          const trainer = challenge;
          notice = null;
          challenge = null;
          if (trainer) ctx.push("battle", { trainer: trainer.id });
        }
        return;
      }
      if (moving > 0) {
        moving = ctx.reduced ? 0 : moving - ctx.dt;
        if (moving <= 0) finishStep();
        return;
      }
      if (ctx.input.consume("Enter")) {
        interact();
        return;
      }
      if (ctx.input.consume("Escape") || ctx.input.consume("Shift") || ctx.input.consume("Tab")) {
        ctx.audio.confirm();
        ctx.push("pause");
        return;
      }
      const tap = ctx.input.dirPressed();
      if (tap) tryStep(tap.x, tap.y);
      else {
        const hold = ctx.input.heldDir(ctx.now);
        if (hold) tryStep(hold.x, hold.y);
      }
    },
    draw() {
      const g = ctx.g;
      const wide = g.wideOw;
      const vw = wide ? OW_W : VIEW_W;
      const vh = wide ? OW_H : VIEW_H;
      const S = wide ? 2 : 1;
      const tilePx = TILE * S;
      g.clear(rgba(P.SAND));
      const t = moving > 0 && !ctx.reduced ? 1 - moving / 180 : 1;
      const px = (fromX + (ctx.state.x - fromX) * (moving > 0 ? t : 1)) * tilePx;
      const py = (fromY + (ctx.state.y - fromY) * (moving > 0 ? t : 1)) * tilePx;
      const mapW = MAP_W * tilePx;
      const mapH = MAP_H * tilePx;
      let camX = Math.round(px - vw / 2 + tilePx / 2);
      let camY = Math.round(py - vh / 2 + tilePx / 2);
      if (mapW > vw) camX = Math.max(0, Math.min(mapW - vw, camX));
      else camX = -Math.round((vw - mapW) / 2);
      if (mapH > vh) camY = Math.max(0, Math.min(mapH - vh, camY));
      else camY = -Math.round((vh - mapH) / 2);
      if (rustle > 0 && !ctx.reduced) {
        const jig = Math.floor(anim / 50) % 2 ? 1 : -1;
        camX += jig;
        camY += jig;
      }
      const x0 = Math.floor(camX / tilePx);
      const y0 = Math.floor(camY / tilePx);
      const x1 = x0 + Math.ceil(vw / tilePx) + 1;
      const y1 = y0 + Math.ceil(vh / tilePx) + 1;
      const blitOpts = S > 1 ? { scale: S } : undefined;
      const waterPhase = ctx.reduced ? 0 : Math.floor(anim / 700) % 4;
      let waterVisible = false;
      const onMap = (tx: number, ty: number): boolean => ty >= 0 && tx >= 0 && ty < MAP_H && tx < MAP_W;
      const visibleProps = PROPS.filter((p) => p.tx >= x0 - 1 && p.ty >= y0 - 1 && p.tx <= x1 && p.ty <= y1);
      const rivals = Object.values(TRAINERS).filter((p) => p.x >= x0 - 1 && p.y >= y0 - 1 && p.x <= x1 && p.y <= y1);

      // sprites: anchor feet flush with the tile bottom (sprite top = tile_y·16 − 8)
      const scout = hd2dPlayer(ctx.state.dir, ctx.reduced ? 0 : step);
      const sx = Math.round(px - camX);
      const bob = moving > 0 || ctx.reduced ? 0 : idleBob(ctx.now, ctx.reduced) * S;
      const sy = Math.round(py - camY) - 8 * S - bob;
      const nurse = hd2dNpc("nurse");
      const vendor = hd2dNpc("vendor");
      const npcY = 4 * tilePx - camY - 8 * S;
      const nx = 5 * tilePx - camX;
      const vx = 13 * tilePx - camX;

      // 1. ground
      for (let ty = y0; ty <= y1; ty++) {
        for (let tx = x0; tx <= x1; tx++) {
          if (!onMap(tx, ty)) continue;
          const id = MAP[ty]![tx]!;
          if (isArtSolid(id)) continue;
          if (id === "water" || id === "foam" || id === "reed") waterVisible = true;
          g.blit(hd2dTile(id, tx, ty, waterPhase), tx * tilePx - camX, ty * tilePx - camY, blitOpts);
        }
      }

      // 2. drop shadows at ground contact (free-standing props only)
      for (let ty = y0; ty <= y1; ty++) {
        for (let tx = x0; tx <= x1; tx++) {
          if (!onMap(tx, ty) || !tileCastsShadow(MAP[ty]![tx]!)) continue;
          const id = MAP[ty]![tx]!;
          const cx = tx * tilePx - camX + 8 * S;
          const cy = (ty + 1) * tilePx - camY - 1 + SCENE.shadowDy * S;
          shadeEllipse(g.img, cx, cy, (id === "fence" ? 12 : 9) * S, 3 * S);
        }
      }
      for (const { kind, tx, ty } of visibleProps) {
        if (!propCastsShadow(kind)) continue;
        shadeEllipse(g.img, tx * tilePx - camX + 16 * S, (ty + 2) * tilePx - camY - 2 * S, 13 * S, 4 * S);
      }
      shadeEllipse(g.img, sx + 8 * S, sy + 24 * S - 1, 7 * S, 3 * S);
      shadeEllipse(g.img, nx + 8 * S, npcY + 24 * S - 1, 7 * S, 3 * S);
      shadeEllipse(g.img, vx + 8 * S, npcY + 24 * S - 1, 7 * S, 3 * S);
      for (const rival of rivals) {
        shadeEllipse(g.img, rival.x * tilePx - camX + 8 * S, (rival.y + 1) * tilePx - camY - 1, 7 * S, 3 * S);
      }

      // 3. built mass
      for (let ty = y0; ty <= y1; ty++) {
        for (let tx = x0; tx <= x1; tx++) {
          if (!onMap(tx, ty)) continue;
          const id = MAP[ty]![tx]!;
          if (!isArtSolid(id)) continue;
          g.blit(hd2dTile(id, tx, ty), tx * tilePx - camX, ty * tilePx - camY, blitOpts);
        }
      }
      for (const { tx, ty } of LANTERNS) {
        g.blit(hd2dLantern(), tx * tilePx - camX, ty * tilePx - camY, blitOpts);
      }

      // 4. 2×2 props at their tile origin
      for (const { kind, tx, ty } of visibleProps) {
        g.blit(hd2dProp(kind, tx, ty), tx * tilePx - camX, ty * tilePx - camY, blitOpts);
      }

      // 5. contact AO under bases that meet ground
      for (let ty = y0; ty <= y1; ty++) {
        for (let tx = x0; tx <= x1; tx++) {
          if (!onMap(tx, ty) || !castsAo(MAP[ty]![tx]!)) continue;
          if (!isGroundId(mapId(tx, ty + 1))) continue;
          aoBand(g.img, tx * tilePx - camX, (tx + 1) * tilePx - camX, (ty + 1) * tilePx - camY, SCENE.aoPx * S);
        }
      }
      for (const { kind, tx, ty } of visibleProps) {
        if (!propCastsAo(kind)) continue;
        aoBand(g.img, tx * tilePx - camX, (tx + 2) * tilePx - camX, (ty + 2) * tilePx - camY, SCENE.aoPx * S);
      }

      // 6. sign bands, sprites
      for (const s of SIGNS) {
        g.blit(hd2dSignBand(s.tiles, s.label, s.doors), s.tx * tilePx - camX, s.ty * tilePx - camY, blitOpts);
      }
      g.blit(nurse, nx, npcY, blitOpts);
      g.blit(vendor, vx, npcY, blitOpts);
      const actors = rivals.map((rival) => ({
        image: hd2dTrainer(rival.id), x: rival.x * tilePx - camX, y: rival.y * tilePx - camY - 8 * S,
      }));
      actors.push({ image: scout, x: sx, y: sy });
      actors.sort((a, b) => a.y - b.y);
      for (const actor of actors) g.blit(actor.image, actor.x, actor.y, blitOpts);

      // 7. HUD panels live in the scene so HUD_PANEL blooms like the oracle; glyphs are
      //    redrawn after capture so the bloom never washes the text.
      hd2dMoneyHud(g, ctx.state.money, wide, "panel");
      const zoneName = ZONES[zoneAt(ctx.state.x, ctx.state.y)].name.toUpperCase();
      const zoneW = zoneName.length * 6 + 12;
      const zx = vw - zoneW - 6;
      // The compact viewport puts the zone below the money bar, even at six digits.
      const zoneY = wide ? 6 : 24;
      g.fill(zx, zoneY, zoneW, 16, rgba(P.HUD_PANEL));
      g.rect(zx, zoneY, zoneW, 16, rgba(P.HUD_INK));
      g.sceneKey = `${wide ? "w" : "n"}:${camX}:${camY}:${sx}:${sy}:${ctx.state.dir}:${step}:${ctx.state.money}:${ctx.state.defeatedTrainers.join(",")}:${ctx.state.circuitRematches}:${waterVisible ? waterPhase : 0}`;
      g.captureScene();

      hd2dMoneyHud(g, ctx.state.money, wide, "text");
      g.text(zx + 6, zoneY + 4, zoneName, rgba(P.HUD_INK));
      for (const rival of rivals) {
        if (trainerLock(rival, ctx.state)) continue;
        const rx = rival.x * tilePx - camX + 6 * S;
        const ry = rival.y * tilePx - camY - 15 * S;
        g.fill(rx - 2, ry - 2, 9, 11, rgba(P.HUD_PANEL));
        g.text(rx, ry, "!", rgba(P.HUD_INK));
      }

      if (!notice && !rustle && !moving) {
        const f = face();
        const rival = trainerAt(ctx.state.x + f.x, ctx.state.y + f.y);
        const spot = spotFacing(ctx.state.x, ctx.state.y, f.x, f.y);
        const hint = rival ? `A  ${rival.name}` : spot ? `A  ${spot.kind === "rest" ? "Rest - HP / PP" : spot.title}` : "";
        if (hint) {
          g.panel(6, vh - 22, hint.length * 6 + 12, 18);
          g.text(12, vh - 17, hint, C.ink);
        }
      }

      if (rustle > 0) {
        g.panel(wide ? 16 : 8, wide ? 276 : 108, wide ? 448 : 224, 40);
        g.lines(wide ? 22 : 14, wide ? 282 : 114, "The reeds shiver.", 34);
      } else if (notice) {
        if (challenge) {
          const nx = wide ? 16 : 8, ny = vh - 108, width = wide ? 448 : 224;
          const rested = ctx.state.party.filter(m => m.hp === maxHp(m) && m.moves.length > 0
            && m.moves.every(slot => slot.pp >= moveById(slot.id).pp)).length;
          const lead = ctx.state.party.find(m => m.hp > 0)!;
          const stock = (n: number) => n > 999 ? "999+" : String(n);
          g.panel(nx, ny, width, 104);
          g.fill(nx + 4, ny + 4, width - 8, 14, C.goldHi);
          g.text(nx + 8, ny + 7, `DUEL / ${challenge.name}`, C.ink);
          g.lines(nx + 6, ny + 25, trainerChallenge(TRAINERS[challenge.id], ctx.state), wide ? 68 : 34);
          g.text(nx + 6, ny + 64, `Rested ${rested}/${ctx.state.party.length} HP+PP / Lead Lv${lead.level}`, C.ink);
          g.text(nx + 6, ny + 76, `Full Cope ${stock(ctx.state.bag.fullcope)}  Sip ${stock(ctx.state.bag.sip)}  Tea ${stock(ctx.state.bag.cleartea)}`, C.ink);
          const levels = challenge.team.map((m) => m.level);
          g.text(nx + 6, ny + 90, `${challenge.team.length} crew Lv${Math.min(...levels)}-${Math.max(...levels)}  A duel / B leave`, C.ink);
        } else {
          const ny = wide ? 256 : 92;
          g.panel(wide ? 16 : 8, ny, wide ? 448 : 224, 64);
          g.lines(wide ? 22 : 14, ny + 6, notice, wide ? 68 : 34);
        }
      }

      if (ctx.state.cosmetics.frame) {
        g.rect(0, 0, vw, vh, C.gold);
        g.rect(1, 1, vw - 2, vh - 2, C.goldHi);
      }
    },
  };
}
