import { VETERAN_ENCOUNTERS, ZONES, type ZoneId } from "./map.ts";
import { SPECIES, SPECIES_IDS, type SpeciesId } from "./species.ts";

export interface HabitatRecord {
  zone: ZoneId;
  region: "all" | "north" | "south";
  lo: number;
  hi: number;
}

/** Read the encounter source of truth; do not advertise still-locked southern beds. */
export function guideHabitats(id: SpeciesId, canopyCleared: boolean): HabitatRecord[] {
  const rows: HabitatRecord[] = [];
  for (const zone of Object.keys(ZONES) as ZoneId[]) {
    const veteran = canopyCleared ? VETERAN_ENCOUNTERS[zone] : undefined;
    for (const row of ZONES[zone].encounters) {
      if (row.id === id) rows.push({ zone, region: veteran ? "north" : "all", lo: row.lo, hi: row.hi });
    }
    for (const row of veteran ?? []) {
      if (row.id === id) rows.push({ zone, region: "south", lo: row.lo, hi: row.hi });
    }
  }
  return rows;
}

export function guideEvolution(id: SpeciesId): string {
  const sp = SPECIES[id];
  if (sp.evolvesTo) return `Lv${sp.evolveLevel}: becomes ${SPECIES[sp.evolvesTo].name}.`;
  const from = SPECIES_IDS.find(base => SPECIES[base].evolvesTo === id);
  return from ? `From ${SPECIES[from].name} at Lv${SPECIES[from].evolveLevel}.` : "No evolution recorded.";
}
