/** Tiny square blips. No assets. Muted when the tab is hidden. */
export class AudioBus {
  private ctx: AudioContext | null = null;
  muted = false;

  private ac(): AudioContext | null {
    if (this.muted) return null;
    if (!this.ctx) {
      const Ctx = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctx) return null;
      this.ctx = new Ctx();
    }
    if (this.ctx.state === "suspended") void this.ctx.resume();
    return this.ctx;
  }

  private tone(freq: number, dur: number, type: OscillatorType, gain = 0.04): void {
    const ctx = this.ac();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    g.gain.value = gain;
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur);
    osc.connect(g);
    g.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + dur);
  }

  confirm(): void {
    this.tone(520, 0.06, "square", 0.035);
  }

  back(): void {
    this.tone(280, 0.05, "square", 0.03);
  }

  cursor(): void {
    this.tone(660, 0.03, "square", 0.02);
  }

  hit(): void {
    this.tone(180, 0.08, "square", 0.05);
    this.tone(90, 0.1, "triangle", 0.03);
  }

  crit(): void {
    this.tone(720, 0.05, "square", 0.04);
    this.tone(960, 0.08, "square", 0.03);
  }

  heal(): void {
    this.tone(440, 0.06, "triangle", 0.03);
    this.tone(660, 0.08, "triangle", 0.03);
  }

  catchShake(): void {
    this.tone(200, 0.04, "square", 0.035);
    this.tone(140, 0.06, "triangle", 0.02);
  }

  catchOk(): void {
    this.tone(392, 0.08, "square", 0.04);
    this.tone(523, 0.1, "square", 0.04);
    this.tone(659, 0.16, "square", 0.04);
  }

  fail(): void {
    this.tone(140, 0.16, "sawtooth", 0.03);
  }

  step(): void {
    this.tone(110, 0.02, "square", 0.012);
  }

  encounter(): void {
    this.tone(200, 0.05, "square", 0.04);
    this.tone(300, 0.08, "square", 0.03);
  }

  buy(): void {
    this.tone(880, 0.05, "square", 0.03);
  }
}
