import { Brush } from "./brush.ts";
import { LCD, type Rgb } from "./lcd.ts";
import { PALS } from "./palettes.ts";
import type { TileId } from "../data/map.ts";

const cache = new Map<string, ImageData>();

function tileBrush(id: TileId, frame = 0): Brush {
  const b = new Brush(16, 16);
  if (id === "void") {
    b.fill(0, 0, 16, 16, 0);
  } else if (id === "floor") {
    b.fill(0, 0, 16, 16, 2);
    b.p(3, 8, 3);
    b.p(11, 4, 1);
    b.p(7, 13, 3);
    b.p(14, 10, 1);
    b.p(1, 2, 1);
  } else if (id === "path") {
    b.fill(0, 0, 16, 16, 3);
    b.fill(0, 6, 16, 1, 2);
    b.fill(0, 10, 16, 1, 2);
    b.p(2, 3, 2);
    b.p(9, 12, 2);
    b.p(14, 5, 1);
    b.p(5, 14, 1);
    b.p(11, 1, 2);
    b.p(6, 8, 1);
    b.p(13, 8, 2);
  } else if (id === "grass") {
    b.fill(0, 0, 16, 16, 2);
    b.p(2, 10, 1);
    b.p(9, 14, 1);
    for (let x = 1; x < 16; x += 2) {
      b.p(x, 12, 1);
      b.p(x, 11, 3);
      b.p(x + 1, 13, 3);
      b.p(x, 9, 3);
    }
    b.p(3, 7, 3);
    b.p(8, 5, 3);
    b.p(12, 8, 3);
    b.p(5, 3, 1);
    b.p(14, 4, 3);
    b.p(1, 6, 3);
    b.p(10, 2, 3);
  } else if (id === "tall") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(0, 13, 16, 3, 1);
    const sway = frame % 2;
    const tufts = [
      { x: 0 + sway, top: 1, h: 13 },
      { x: 5, top: 3, h: 11 },
      { x: 9 - sway, top: 0, h: 14 },
      { x: 13, top: 2, h: 12 },
    ];
    for (const t of tufts) {
      const x = t.x;
      b.fill(x + 1, t.top, 2, t.h, 1);
      b.fill(x, t.top + 3, 1, t.h - 4, 1);
      b.fill(x + 3, t.top + 4, 1, t.h - 5, 1);
      b.p(x + 1, Math.max(0, t.top - 1), 3);
      b.p(x + 2, t.top, 3);
      b.p(x, t.top + 2, 3);
      b.p(x + 3, t.top + 3, 3);
      b.p(x + 1, t.top + 3, 3);
      b.p(x + 2, t.top + 5, 3);
      b.p(x, t.top + 6, 3);
      b.p(x + 3, t.top + 8, 3);
      b.p(x + 1, t.top + 9, 3);
    }
    b.fill(0, 14, 16, 2, 2);
  } else if (id === "water" || id === "foam") {
    b.fill(0, 0, 16, 16, 1);
    const o = frame % 4;
    for (let x = 0; x < 16; x++) {
      const y = 3 + ((x + o * 2) % 5);
      b.p(x, y, 2);
      b.p(x, y + 5, 2);
      if ((x + o) % 4 === 0) b.p(x, y + 2, 3);
      if ((x + o * 2) % 5 === 0) b.p(x, y + 6, 3);
    }
    b.fill(0, 13, 16, 3, 0);
    if (id === "foam") {
      b.fill(0, 0, 16, 3, 3);
      b.p(2, 3, 3);
      b.p(8, 2, 3);
      b.p(13, 3, 3);
      b.p(5, 1, 2);
    }
  } else if (id === "wood") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(0, 5, 16, 1, 1);
    b.fill(0, 11, 16, 1, 1);
    b.fill(7, 0, 1, 16, 1);
    b.p(3, 2, 3);
    b.p(12, 8, 3);
    b.p(8, 14, 0);
  } else if (id === "roof") {
    b.fill(0, 0, 16, 16, 1);
    for (let y = 0; y < 16; y += 4) {
      b.fill(0, y, 16, 1, 0);
      const sx = (y * 3) % 8;
      b.fill(sx, y + 1, 6, 1, 3);
      b.fill(sx, y + 2, 6, 1, 2);
      b.p((y * 5) % 16, y + 2, 0);
    }
  } else if (id === "wall") {
    b.fill(0, 0, 16, 16, 1);
    b.fill(0, 0, 16, 2, 0);
    b.fill(2, 4, 5, 6, 3);
    b.fill(3, 5, 3, 4, 2);
    b.fill(2, 9, 5, 1, 0);
    b.fill(9, 4, 5, 6, 3);
    b.fill(10, 5, 3, 4, 2);
    b.fill(9, 9, 5, 1, 0);
    b.fill(2, 12, 12, 3, 0);
    b.p(4, 13, 2);
    b.p(11, 13, 2);
  } else if (id === "door") {
    b.fill(0, 0, 16, 16, 1);
    b.fill(2, 1, 12, 13, 2);
    b.fill(3, 2, 10, 11, 0);
    b.fill(4, 3, 8, 10, 2);
    b.fill(4, 3, 8, 1, 3);
    b.p(10, 9, 3);
    b.p(10, 10, 3);
    b.fill(3, 14, 10, 2, 1);
  } else if (id === "counter") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(0, 6, 16, 10, 1);
    b.fill(0, 6, 16, 2, 3);
    b.p(4, 10, 3);
    b.p(11, 12, 0);
  } else if (id === "flower") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(7, 9, 1, 4, 1);
    b.p(7, 8, 3);
    b.p(6, 7, 3);
    b.p(8, 7, 3);
    b.p(7, 6, 3);
    b.p(7, 7, 0);
  } else if (id === "reed") {
    b.fill(0, 0, 16, 16, 1);
    b.fill(3, 2, 1, 12, 2);
    b.fill(7, 3, 1, 11, 2);
    b.fill(11, 2, 1, 12, 2);
    b.fill(14, 4, 1, 9, 2);
    b.p(3, 2, 3);
    b.p(7, 3, 3);
    b.p(11, 2, 3);
    b.p(14, 4, 3);
    b.p(2, 4, 3);
    b.p(6, 5, 3);
    b.p(10, 3, 3);
    b.p(13, 6, 3);
    b.fill(0, 12, 16, 4, 0);
    b.p(2, 13, 3);
  } else if (id === "crate") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(3, 3, 10, 11, 1);
    b.fill(4, 4, 8, 9, 2);
    b.fill(3, 8, 10, 1, 1);
    b.fill(7, 3, 2, 11, 1);
    b.p(5, 6, 3);
    b.p(10, 11, 0);
  } else if (id === "barrel") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(4, 2, 8, 13, 1);
    b.fill(5, 3, 6, 11, 2);
    b.fill(4, 6, 8, 1, 1);
    b.fill(4, 10, 8, 1, 1);
    b.p(7, 5, 3);
    b.p(8, 12, 0);
  } else if (id === "lamp") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(7, 8, 2, 8, 1);
    b.fill(5, 2, 6, 6, 3);
    b.fill(6, 3, 4, 4, 2);
    b.fill(6, 14, 4, 2, 1);
    b.p(7, 4, 3);
  } else if (id === "rock") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(3, 8, 10, 6, 1);
    b.fill(5, 6, 7, 4, 2);
    b.p(6, 7, 3);
    b.p(10, 10, 0);
  } else if (id === "fence") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(2, 6, 12, 2, 2);
    b.fill(2, 11, 12, 2, 2);
    b.fill(3, 4, 2, 10, 1);
    b.fill(11, 4, 2, 10, 1);
  } else if (id === "post") {
    b.fill(0, 0, 16, 16, 2);
    b.fill(7, 8, 2, 8, 1);
    b.fill(3, 3, 10, 6, 2);
    b.fill(4, 4, 8, 4, 3);
    b.p(6, 5, 1);
    b.p(9, 5, 1);
  }
  return b;
}

const TILE_PAL: Record<string, readonly Rgb[]> = {
  floor: [LCD.dirt0, LCD.dirt1, LCD.dirt2, LCD.path],
  path: [LCD.dirt0, LCD.dirt1, LCD.dirt2, LCD.path],
  grass: [LCD.moss0, LCD.moss1, LCD.moss2, LCD.moss3],
  tall: [LCD.moss0, LCD.moss1, LCD.moss2, LCD.moss3],
  water: [LCD.water0, LCD.water1, LCD.water2, LCD.foam],
  foam: [LCD.water0, LCD.water1, LCD.water2, LCD.foam],
  wood: [LCD.ink, LCD.wood0, LCD.wood1, LCD.tan],
  roof: [LCD.ink, LCD.roof0, LCD.roof1, LCD.tan],
  wall: [LCD.ink, LCD.wood0, LCD.dirt2, LCD.path],
  door: [LCD.ink, LCD.wood0, LCD.wood1, LCD.gold],
  counter: [LCD.ink, LCD.wood0, LCD.wood1, LCD.gold],
  flower: [LCD.moss0, LCD.moss1, LCD.moss2, LCD.rose],
  reed: [LCD.water0, LCD.water1, LCD.moss2, LCD.moss3],
  crate: [LCD.dirt2, LCD.wood0, LCD.wood1, LCD.gold],
  barrel: [LCD.dirt2, LCD.wood0, LCD.wood1, LCD.tan],
  lamp: [LCD.dirt2, LCD.wood0, LCD.gold, LCD.goldHi],
  rock: [LCD.dirt2, LCD.slate, LCD.paperDk, LCD.cream],
  fence: [LCD.dirt2, LCD.wood0, LCD.wood1, LCD.tan],
  post: [LCD.dirt2, LCD.wood0, LCD.wood1, LCD.goldHi],
  void: [LCD.ink, LCD.ink, LCD.ink, LCD.ink],
};

export function tileSprite(id: TileId, frame = 0): ImageData {
  const f = id === "water" || id === "foam" || id === "tall" ? frame % 4 : 0;
  const key = `${id}:${f}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const pal = TILE_PAL[id] ?? TILE_PAL.floor!;
  const img = tileBrush(id, f).toImage(pal);
  cache.set(key, img);
  return img;
}

export function scoutSprite(dir: 0 | 1 | 2 | 3, step: 0 | 1): ImageData {
  const key = `scout:${dir}:${step}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Brush(16, 16);
  const foot = step ? 12 : 13;
  const other = step ? 13 : 12;
  b.fill(5, 8, 6, 5, 1);
  b.fill(6, 9, 4, 3, 5);
  b.fill(10, 8, 4, 5, 4);
  b.fill(11, 9, 2, 3, 2);
  if (dir === 0) {
    b.fill(4, 1, 8, 3, 2);
    b.fill(3, 3, 10, 2, 2);
    b.fill(5, 4, 6, 4, 1);
    b.fill(4, 8, 2, 3, 1);
    b.fill(10, 8, 2, 3, 1);
  } else if (dir === 2) {
    b.fill(4, 1, 8, 3, 2);
    b.fill(3, 3, 10, 2, 2);
    b.fill(6, 4, 5, 4, 3);
    b.p(9, 6, 0);
    b.fill(10, 8, 4, 5, 4);
    b.fill(11, 9, 3, 3, 2);
  } else if (dir === 3) {
    b.fill(4, 1, 8, 3, 2);
    b.fill(3, 3, 10, 2, 2);
    b.fill(5, 4, 5, 4, 3);
    b.p(6, 6, 0);
    b.fill(2, 8, 4, 5, 4);
    b.fill(2, 9, 3, 3, 2);
  } else {
    b.fill(4, 1, 8, 3, 2);
    b.fill(3, 3, 10, 2, 2);
    b.p(5, 1, 5);
    b.fill(5, 4, 6, 4, 3);
    b.p(6, 6, 0);
    b.p(9, 6, 0);
  }
  b.fill(5, foot, 2, 3, 0);
  b.fill(9, other, 2, 3, 0);
  b.outline(0);
  const img = b.toImage(PALS.scout);
  cache.set(key, img);
  return img;
}

export function npcSprite(who: "nurse" | "vendor"): ImageData {
  const key = `npc:${who}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Brush(16, 16);
  b.fill(5, 8, 6, 5, 2);
  b.fill(5, 4, 6, 4, 3);
  b.p(6, 6, 0);
  b.p(9, 6, 0);
  b.fill(5, 13, 2, 3, 0);
  b.fill(9, 13, 2, 3, 0);
  if (who === "nurse") {
    b.fill(4, 0, 8, 4, 3);
    b.fill(5, 0, 6, 2, 5);
    b.fill(7, 0, 2, 4, 4);
    b.fill(6, 1, 4, 1, 4);
    b.fill(4, 8, 8, 5, 5);
    b.fill(5, 9, 6, 3, 2);
    b.fill(7, 10, 2, 2, 4);
  } else {
    b.fill(4, 1, 8, 3, 2);
    b.fill(3, 3, 10, 2, 2);
    b.fill(4, 8, 8, 5, 2);
    b.fill(6, 10, 4, 2, 5);
    b.p(7, 11, 3);
  }
  b.outline(0);
  const img = b.toImage(PALS[who]);
  cache.set(key, img);
  return img;
}

export function capsuleSprite(tint: readonly [number, number, number]): ImageData {
  const key = `tin:${tint.join(",")}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Brush(16, 16);
  b.fill(4, 5, 8, 9, 3);
  b.fill(4, 5, 2, 9, 2);
  b.fill(10, 6, 2, 7, 5);
  b.fill(4, 2, 8, 4, 3);
  b.p(4, 2, -1);
  b.p(11, 2, -1);
  b.fill(5, 2, 6, 2, 5);
  b.fill(5, 5, 6, 1, 0);
  b.fill(4, 8, 8, 4, 1);
  b.fill(5, 9, 6, 2, 3);
  b.p(6, 9, 4);
  b.p(8, 10, 4);
  b.p(10, 9, 4);
  b.fill(10, 0, 6, 4, 0);
  b.fill(11, 0, 5, 3, 3);
  b.fill(12, 1, 2, 2, 0);
  b.p(14, 0, 4);
  b.fill(5, 13, 6, 1, 0);
  b.fill(6, 14, 4, 1, 2);
  b.p(6, 4, 3);
  b.outline(0);
  const img = b.toImage([
    LCD.ink,
    tint,
    LCD.slate,
    LCD.cream,
    LCD.gold,
    LCD.white,
  ]);
  cache.set(key, img);
  return img;
}
