import { LCD, type Rgb } from "./lcd.ts";

/**
 * Vinyl-toy sprite rig for the 32×32 creature frames. Every volume is a shaded primitive lit by
 * the same key light as the HD-2D street (upper-left, toward the viewer) with a backlight rim on
 * the far edge, one specular pixel, and contact occlusion where a front volume meets the one
 * behind it. Pixels store a palette RAMP + TONE index so later volumes can darken what they sit
 * on; `toImage` resolves them to the locked 32-colour LCD master and adds the 1px ink outline.
 */
export type Ramp = readonly Rgb[];

/** Material ramps, light → dark, all from the LCD master. */
export const R = {
  cream: [LCD.white, LCD.cream, LCD.paper, LCD.paperDk, LCD.tan],
  orange: [LCD.skin, LCD.tan, LCD.wood1, LCD.dirt1, LCD.wood0],
  brown: [LCD.tan, LCD.dirt2, LCD.wood1, LCD.dirt1, LCD.wood0],
  bark: [LCD.dirt2, LCD.wood1, LCD.wood0, LCD.dirt0],
  red: [LCD.tan, LCD.roof1, LCD.roof0, LCD.dirt0],
  rose: [LCD.white, LCD.rose, LCD.roof1, LCD.roof0],
  green: [LCD.moss3, LCD.leaf, LCD.moss2, LCD.moss1, LCD.moss0],
  moss: [LCD.leaf, LCD.moss2, LCD.moss1, LCD.moss0],
  blue: [LCD.foam, LCD.cyan, LCD.water2, LCD.water1, LCD.water0],
  navy: [LCD.water2, LCD.water1, LCD.water0, LCD.ink],
  ice: [LCD.white, LCD.foam, LCD.cyan, LCD.water2],
  gold: [LCD.goldHi, LCD.gold, LCD.wood1, LCD.wood0],
  stone: [LCD.paper, LCD.paperDk, LCD.dirt2, LCD.dirt1, LCD.dirt0],
  slate: [LCD.paperDk, LCD.slate, LCD.ink],
  violet: [LCD.foam, LCD.violet, LCD.water1, LCD.water0],
  paper: [LCD.white, LCD.paper, LCD.paperDk, LCD.tan],
  ink: [LCD.slate, LCD.ink],
  white: [LCD.white],
} as const satisfies Record<string, Ramp>;

// Key light direction (unit): from the upper-left, toward the viewer.
const LX = -0.55;
const LY = -0.62;
const LZ = 0.56;

export interface ShadeOpts {
  /** Fixed tone index (skips lighting). */
  flat?: number;
  /** Tone offset after lighting (+ darker, − lighter). */
  shade?: number;
  /** Backlight rim along the far silhouette edge (default on for volumes ≥ 3px). */
  rim?: boolean;
  /** Specular pixel toward the key light (default on for volumes ≥ 4px). */
  spec?: boolean;
  /** Darken what this volume overlaps along its lower/right edge (default on). */
  occ?: boolean;
  /** 0 = flat disc lighting, 1 = full sphere. */
  dome?: number;
}

function toneFor(lam: number, n: number): number {
  const t = Math.floor(((0.95 - lam) / 1.55) * n);
  return t < 0 ? 0 : t >= n ? n - 1 : t;
}

export class Toy {
  readonly w = 32;
  readonly h = 32;
  private ramps: (Ramp | null)[] = new Array<Ramp | null>(32 * 32).fill(null);
  private tones = new Int8Array(32 * 32);
  private specs = new Uint8Array(32 * 32);

  has(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < 32 && y < 32 && this.ramps[y * 32 + x] !== null;
  }

  /** Paint one pixel of `ramp` at `tone` (clamped to the ramp). */
  px(x: number, y: number, ramp: Ramp, tone = 0): void {
    const xi = x | 0;
    const yi = y | 0;
    if (xi < 0 || yi < 0 || xi >= 32 || yi >= 32) return;
    const i = yi * 32 + xi;
    this.ramps[i] = ramp;
    this.tones[i] = tone < 0 ? 0 : tone >= ramp.length ? ramp.length - 1 : tone;
    this.specs[i] = 0;
  }

  erase(x: number, y: number): void {
    if (x < 0 || y < 0 || x >= 32 || y >= 32) return;
    this.ramps[y * 32 + x] = null;
  }

  darken(x: number, y: number, by = 1): void {
    if (!this.has(x, y)) return;
    const i = y * 32 + x;
    const n = this.ramps[i]!.length;
    this.tones[i] = Math.min(n - 1, this.tones[i]! + by);
    this.specs[i] = 0;
  }

  lighten(x: number, y: number, by = 1): void {
    if (!this.has(x, y)) return;
    const i = y * 32 + x;
    this.tones[i] = Math.max(0, this.tones[i]! - by);
  }

  rect(x: number, y: number, w: number, h: number, ramp: Ramp, tone = 0): void {
    for (let yy = 0; yy < h; yy++) for (let xx = 0; xx < w; xx++) this.px(x + xx, y + yy, ramp, tone);
  }

  hline(x: number, y: number, w: number, ramp: Ramp, tone = 0): void {
    this.rect(x, y, w, 1, ramp, tone);
  }

  vline(x: number, y: number, h: number, ramp: Ramp, tone = 0): void {
    this.rect(x, y, 1, h, ramp, tone);
  }

  line(x0: number, y0: number, x1: number, y1: number, ramp: Ramp, tone = 0): void {
    let x = x0 | 0, y = y0 | 0;
    const ex = x1 | 0, ey = y1 | 0;
    const dx = Math.abs(ex - x), dy = -Math.abs(ey - y);
    const sx = x < ex ? 1 : -1, sy = y < ey ? 1 : -1;
    let err = dx + dy;
    for (;;) {
      this.px(x, y, ramp, tone);
      if (x === ex && y === ey) break;
      const e2 = 2 * err;
      if (e2 >= dy) { err += dy; x += sx; }
      if (e2 <= dx) { err += dx; y += sy; }
    }
  }

  /** Darken already-painted pixels in a 1px band just outside a volume's lower/right edge. */
  private occlude(cx: number, cy: number, rx: number, ry: number): void {
    for (let y = Math.floor(cy - ry - 2); y <= Math.ceil(cy + ry + 2); y++) {
      for (let x = Math.floor(cx - rx - 2); x <= Math.ceil(cx + rx + 2); x++) {
        const nx = (x - cx) / rx, ny = (y - cy) / ry;
        if (nx * nx + ny * ny <= 1) continue;
        const ox = (Math.abs(x - cx) - 1.1) / rx, oy = (Math.abs(y - cy) - 1.1) / ry;
        if (Math.max(0, ox) ** 2 + Math.max(0, oy) ** 2 > 1) continue;
        if (ny > 0.15 || nx > 0.6) this.darken(x, y);
      }
    }
  }

  /** Shaded ellipsoid volume. */
  ell(cx: number, cy: number, rx: number, ry: number, ramp: Ramp, o: ShadeOpts = {}): void {
    if (o.occ !== false) this.occlude(cx, cy, rx, ry);
    const n = ramp.length;
    const dome = o.dome ?? 1;
    const rim = o.rim !== false && rx >= 3 && ry >= 3 && o.flat === undefined;
    const rimTone = n >= 4 ? 1 : 0;
    for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
      for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
        const nx = (x - cx) / rx, ny = (y - cy) / ry;
        const d2 = nx * nx + ny * ny;
        if (d2 > 1) continue;
        let t: number;
        if (o.flat !== undefined) t = o.flat;
        else {
          const z = Math.sqrt(Math.max(0, 1 - d2 * dome));
          t = toneFor(nx * LX + ny * LY + z * LZ, n) + (o.shade ?? 0);
          if (rim && d2 > 0.74 && nx * LX + ny * LY < -0.3) t = Math.min(t, rimTone);
        }
        this.px(x, y, ramp, t);
      }
    }
    if (o.spec !== false && o.flat === undefined && rx >= 4 && ry >= 4) {
      const sx = Math.round(cx + LX * 0.45 * rx), sy = Math.round(cy + LY * 0.45 * ry);
      if (this.has(sx, sy) && this.ramps[sy * 32 + sx] === ramp) this.specs[sy * 32 + sx] = 1;
    }
  }

  /** Shaded capsule (limb / neck / tail segment) of radius r between two points. */
  cap(x0: number, y0: number, x1: number, y1: number, r: number, ramp: Ramp, o: ShadeOpts = {}): void {
    const n = ramp.length;
    const dx = x1 - x0, dy = y1 - y0;
    const len2 = dx * dx + dy * dy || 1;
    const minX = Math.floor(Math.min(x0, x1) - r), maxX = Math.ceil(Math.max(x0, x1) + r);
    const minY = Math.floor(Math.min(y0, y1) - r), maxY = Math.ceil(Math.max(y0, y1) + r);
    const rim = o.rim !== false && r >= 2.5 && o.flat === undefined;
    // Contact band: darken what the capsule sits on along its lower/right side.
    if (o.occ !== false) {
      for (let y = minY - 1; y <= maxY + 1; y++) for (let x = minX - 1; x <= maxX + 1; x++) {
        const u = Math.max(0, Math.min(1, ((x - x0) * dx + (y - y0) * dy) / len2));
        const px = x - (x0 + dx * u), py = y - (y0 + dy * u);
        const d = Math.hypot(px, py);
        if (d > r && d <= r + 1.1 && (py > 0.3 || px > 0.6)) this.darken(x, y);
      }
    }
    for (let y = minY; y <= maxY; y++) {
      for (let x = minX; x <= maxX; x++) {
        const u = Math.max(0, Math.min(1, ((x - x0) * dx + (y - y0) * dy) / len2));
        const px = x - (x0 + dx * u), py = y - (y0 + dy * u);
        const d2 = (px * px + py * py) / (r * r);
        if (d2 > 1) continue;
        let t: number;
        if (o.flat !== undefined) t = o.flat;
        else {
          const nx = px / r, ny = py / r;
          const z = Math.sqrt(Math.max(0, 1 - d2));
          t = toneFor(nx * LX + ny * LY + z * LZ, n) + (o.shade ?? 0);
          if (rim && d2 > 0.7 && nx * LX + ny * LY < -0.3) t = Math.min(t, n >= 4 ? 1 : 0);
        }
        this.px(x, y, ramp, t);
      }
    }
  }

  /** Flat or planar-shaded polygon (ears, wings, fins, flames). */
  poly(pts: readonly (readonly [number, number])[], ramp: Ramp, o: { tone?: number; grad?: boolean } = {}): void {
    let minX = 32, maxX = -1, minY = 32, maxY = -1;
    for (const [x, y] of pts) { minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y); }
    const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
    const hw = Math.max(1, (maxX - minX) / 2), hh = Math.max(1, (maxY - minY) / 2);
    const base = o.tone ?? 1;
    for (let y = Math.floor(minY); y <= Math.ceil(maxY); y++) {
      const yc = y + 0.5;
      const xs: number[] = [];
      for (let i = 0; i < pts.length; i++) {
        const [ax, ay] = pts[i]!;
        const [bx, by] = pts[(i + 1) % pts.length]!;
        if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) xs.push(ax + ((yc - ay) * (bx - ax)) / (by - ay));
      }
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        for (let x = Math.round(xs[k]!); x < Math.round(xs[k + 1]!); x++) {
          const t = o.grad ? base + Math.round(((x - cx) / hw) * 0.55 + ((y - cy) / hh) * 0.62) : base;
          this.px(x, y, ramp, t);
        }
      }
    }
  }

  /** 1px ellipse ring (rings, crowns, orbits). */
  ring(cx: number, cy: number, rx: number, ry: number, ramp: Ramp, tone = 0): void {
    const steps = Math.max(24, Math.round((rx + ry) * 4));
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      this.px(Math.round(cx + Math.cos(a) * rx), Math.round(cy + Math.sin(a) * ry), ramp, tone);
    }
  }

  /** Mirror the painted left half onto the right (symmetric fronts / backs). */
  mirror(axis = 15.5): void {
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 32; x++) {
        if (x > axis) continue;
        const mx = Math.round(axis * 2 - x);
        if (mx < 0 || mx >= 32) continue;
        const i = y * 32 + x, j = y * 32 + mx;
        this.ramps[j] = this.ramps[i];
        this.tones[j] = this.tones[i]!;
        this.specs[j] = 0;
      }
    }
  }

  /** Resolve to RGBA with the 1px ink outline around the silhouette. */
  toImage(): ImageData {
    const img = new ImageData(32, 32);
    const d = img.data;
    for (let i = 0; i < 1024; i++) {
      const ramp = this.ramps[i];
      if (!ramp) continue;
      const c = this.specs[i] ? LCD.white : ramp[this.tones[i]!]!;
      const o = i * 4;
      d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2]; d[o + 3] = 255;
    }
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 32; x++) {
        const i = y * 32 + x;
        if (this.ramps[i]) continue;
        const edge = this.has(x - 1, y) || this.has(x + 1, y) || this.has(x, y - 1) || this.has(x, y + 1);
        if (!edge) continue;
        const o = i * 4;
        d[o] = LCD.ink[0]; d[o + 1] = LCD.ink[1]; d[o + 2] = LCD.ink[2]; d[o + 3] = 255;
      }
    }
    return img;
  }
}
