/**
 * HD-2D+ LOCKED palette — mirror of art/hd2d/palette.md (Fable 5.1 design package).
 * Every native pixel the painters emit must be one of these. Do not add colors.
 */

export type Rgb = readonly [number, number, number];

function hx(hex: string): Rgb {
  const n = Number.parseInt(hex, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

