import { P } from "./palette.ts";
import { Pix } from "./pix.ts";
import { hs, thash } from "./seed.ts";
import { grain } from "./materials.ts";

/** 2×2 (32×32) prop painters — port of render_styles.py. Drawn over ground at a tile origin. */

const cache = new Map<string, ImageData>();

export type PropKind = "tree" | "window" | "lamp" | "rock";

/** Free-standing props cast a ground ellipse; wall-mounted panels do not. */
export function propCastsShadow(kind: PropKind): boolean {
  return kind === "tree";
}

/** Wall/slab props darken the ground below their base (AO band). */
export function propCastsAo(kind: PropKind): boolean {
  return kind === "window" || kind === "lamp" || kind === "rock";
}

/** Canopy lobes: (cx, cy, r). The union gives a broken, leafy silhouette instead of a disc. */
const TREE_LOBES: readonly [number, number, number][] = [[16, 13, 11], [9, 15, 7], [23, 15, 7], [15, 7, 7], [21, 9, 6]];

function canopyDepth(x: number, y: number): number {
  // Largest inset (in px) at which the point is still inside some lobe: 0 = silhouette edge.
  let best = -1;
  for (const [cx, cy, r] of TREE_LOBES) {
    const d = r - Math.hypot(x - cx, y - cy);
    if (d > best) best = d;
  }
  return best;
}

function paintTree(b: Pix): void {
  // Trunk: lit grain edge on the left, dark far side, bark rings and a root flare.
  for (let y = 21; y < 32; y++) {
    for (let x = 13; x < 19; x++) b.p(x, y, x < 15 ? P.TRUNK : x < 17 ? P.TRUNK : P.TRUNK_DK);
  }
  b.vline(13, 21, 10, P.PLANK); b.p(13, 24, P.PLANK_HI); b.p(13, 28, P.PLANK_HI);
  b.p(15, 25, P.TRUNK_DK); b.p(16, 23, P.TRUNK_DK); b.p(15, 29, P.TRUNK_DK);
  b.hline(11, 31, 10, P.TRUNK_DK); b.hline(12, 30, 2, P.TRUNK); b.p(19, 30, P.TRUNK_DK);
  for (let y = 0; y < 32; y++) {
    for (let x = 0; x < 32; x++) {
      const depth = canopyDepth(x, y);
      if (depth < 0) continue;
      const toward = (x - 16) + (y - 13);
      let col = P.TREE_BODY;
      if (depth < 1.5) col = toward < -7 ? P.TREE_HI : P.TREE_DARK;
      else if (depth < 3 && toward > 4) col = P.TREE_DARK;
      else if ((x - 12) * (x - 12) + (y - 9) * (y - 9) <= 20) col = P.TREE_HI;
      // Leaf clusters in 2×2 blocks: lit flecks on the key-light side, shade on the far side.
      const cluster = thash(x >> 1, y >> 1, 9);
      if (depth >= 1.5) {
        if (cluster % 9 === 0) col = toward < 0 ? P.TREE_LT : P.TREE_HI;
        else if (cluster % 7 === 0 && toward > 2) col = P.TREE_DARK;
        else if (cluster % 11 === 0 && toward < -4) col = P.TREE_LT;
      }
      if (depth >= 2 && thash(x, y, 12) % 23 === 0) col = toward > 0 ? P.TREE_DARK : P.TREE_LT;
      b.p(x, y, col);
    }
  }
  // Highlight rim where the crown meets the light.
  b.p(9, 4, P.TREE_LT); b.p(10, 3, P.TREE_LT); b.p(12, 1, P.TREE_LT); b.p(7, 8, P.TREE_LT);
}

function paintWindow(b: Pix): void {
  b.fill(0, 0, 32, 32, P.WIN_DK);
  b.fill(2, 2, 28, 28, P.WIN_FRAME);
  for (const py of [5, 17]) {
    for (const px of [5, 17]) b.fill(px, py, 10, 10, P.WIN_PANE);
  }
  b.fill(6, 6, 5, 3, P.WIN_GLINT);
  b.hline(3, 2, 26, P.PLANK_HI);
  b.vline(2, 3, 25, P.PLANK);
  b.hline(3, 28, 26, P.PLANK_GRAIN);
  for (const py of [5, 17]) for (const px of [5, 17]) {
    b.hline(px, py + 9, 10, P.ROCK_SPECK);
    b.vline(px, py, 8, P.ROCK_MID);
    b.hline(px + 2, py + 1, 4, P.WIN_GLINT);
    b.hline(px + 5, py + 2, 2, P.WIN_GLINT);
  }
  b.p(3, 4, P.CRATE_FACE); b.p(28, 27, P.CRATE_FACE);
}

function paintLamp(b: Pix): void {
  b.fill(0, 0, 32, 32, P.LAMP_PANEL);
  // Brushed brass with a raised rim and four inset rivets.
  for (let y = 2; y < 30; y++) for (let x = 2; x < 30; x++) {
    const n = grain(x, y, 61);
    if (n % 47 === 0) b.hline(x, y, 2, P.LAMP_HEAD);
    if (n % 73 === 0) b.p(x, y, P.COIN_RIM);
  }
  b.hline(2, 1, 28, P.LAMP_HEAD); b.vline(1, 2, 28, P.LAMP_HEAD);
  b.hline(2, 30, 28, P.COIN_RIM); b.vline(30, 2, 28, P.COIN_RIM);
  b.hline(0, 0, 32, P.LANT_FRAME);
  b.hline(0, 31, 32, P.LANT_FRAME);
  b.vline(0, 0, 32, P.LANT_FRAME);
  b.vline(31, 0, 32, P.LANT_FRAME);
  b.fill(14, 12, 4, 16, P.LANT_FRAME);
  b.fill(10, 28, 12, 2, P.LANT_FRAME);
  b.fill(9, 3, 14, 11, P.LANT_FRAME);
  b.fill(10, 4, 12, 9, P.LAMP_HEAD);
  b.fill(12, 6, 8, 5, P.LAMP_CORE);
  b.fill(13, 6, 5, 4, P.LANT_GLOW);
  b.fill(14, 7, 3, 2, P.HUD_PANEL);
  b.vline(20, 5, 7, P.COIN_RIM);
  b.hline(11, 4, 10, P.LANT_GLOW);
  b.hline(11, 12, 10, P.COIN_RIM);
  b.vline(14, 15, 12, P.WIN_FRAME); b.vline(15, 16, 10, P.PLANK_HI);
  b.hline(11, 28, 10, P.PLANK_HI);
  for (const y of [3, 28]) for (const x of [3, 28]) {
    b.p(x, y, P.LANT_FRAME); b.p(x, y - 1, P.LAMP_CORE);
  }
}

function paintRock(b: Pix, tx: number, ty: number): void {
  // Worn slab: bordered, lit top/left edge, shaded bottom/right, a few chips and pebbles.
  b.fill(0, 0, 32, 32, P.ROCK_SLAB);
  b.fill(0, 0, 32, 2, P.ROCK_BORDER);
  b.fill(0, 30, 32, 2, P.ROCK_BORDER);
  b.fill(0, 0, 2, 32, P.ROCK_BORDER);
  b.fill(30, 0, 2, 32, P.ROCK_BORDER);
  b.hline(2, 2, 28, P.PATH_HI); b.vline(2, 3, 26, P.ROCK_HI);
  b.hline(3, 29, 27, P.ROCK_MID); b.vline(29, 3, 26, P.ROCK_HI);
  const h = thash(tx, ty, 10);
  for (let i = 0; i < 6; i++) b.p(3 + hs(h, i * 4, 26), 3 + hs(h, i * 4 + 3, 26), P.ROCK_SPECK);
  for (let i = 0; i < 3; i++) {
    const px = 4 + hs(h, i * 5 + 1, 24), py = 25 + hs(h, i * 5 + 3, 4);
    b.p(px, py, P.ROCK_MID); b.p(px + 1, py, P.ROCK_DK); b.p(px, py - 1, P.PATH_HI);
  }
  // Boulder: contact shadow cast toward the lower-right first, then facets from lit crown to dark base.
  for (let y = 3; y < 29; y++) for (let x = 3; x < 29; x++) {
    const sx = (x - 18) / 13, sy = (y - 19.5) / 8.5;
    if (sx * sx + sy * sy <= 1) b.p(x, y, P.ROCK_MID);
  }
  const cx = 16;
  const cy = 17;
  const rx = 12;
  const ry = 9;
  for (let y = 0; y < 32; y++) {
    for (let x = 0; x < 32; x++) {
      const nx = (x - cx) / rx;
      const ny = (y - cy) / ry;
      const d2 = nx * nx + ny * ny;
      if (d2 > 1) continue;
      let col = P.ROCK_MID;
      if (y > cy + 2) col = P.ROCK_DK;
      const hx = (x - cx + 4) / rx;
      const hy = (y - cy + 3) / ry;
      if (hx * hx + hy * hy <= 0.35) col = P.ROCK_HI;
      const facet = x + 2 * y;
      if (facet > 51 && x > 16 && y < 20) col = P.ROCK_DK;
      if (y >= 19 && y < 22 && x < 18) col = P.ROCK_SPECK;
      // Rim light on the upper-left silhouette, dark occluded rim on the lower-right.
      if (d2 > 0.8 && nx + ny < -0.7) col = P.ROCK_SLAB;
      else if (d2 > 0.85 && nx + ny > 0.6) col = P.ROCK_BORDER;
      const n = grain(x + tx * 16, y + ty * 16, 10);
      if (n % 23 === 0 && col === P.ROCK_HI) col = P.ROCK_SLAB;
      if (n % 29 === 0 && col === P.ROCK_MID) col = P.ROCK_SPECK;
      // Lichen creeps over the shaded lower flank.
      if (col === P.ROCK_DK && n % 17 === 0 && y > cy + 4) col = P.BED_GREEN;
      b.p(x, y, col);
    }
  }
  b.hline(10, 10, 8, P.ROCK_SLAB); b.hline(9, 11, 4, P.ROCK_HI);
  b.p(17, 14, P.ROCK_DK); b.p(18, 15, P.ROCK_DK); b.hline(19, 16, 3, P.ROCK_DK);
  b.p(18, 14, P.ROCK_HI); b.hline(11, 24, 12, P.ROCK_MID);
  // Crease running down the facet and a chipped notch on the crown.
  b.p(21, 12, P.ROCK_DK); b.p(22, 13, P.ROCK_DK); b.p(23, 15, P.ROCK_DK); b.p(24, 17, P.ROCK_DK);
  b.p(13, 9, P.ROCK_MID); b.p(14, 9, P.ROCK_SLAB);
}

export function hd2dProp(kind: PropKind, tx: number, ty: number): ImageData {
  const key = `grok-look:${kind}:${tx}:${ty}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Pix(32, 32);
  if (kind === "tree") paintTree(b);
  else if (kind === "window") paintWindow(b);
  else if (kind === "lamp") paintLamp(b);
  else paintRock(b, tx, ty);
  const img = b.toImage();
  cache.set(key, img);
  return img;
}
