import type { Gfx, Rgba } from "../../engine/gfx.ts";
import { ORACLE, P, rgba, type Rgb } from "./palette.ts";
import { Pix } from "./pix.ts";

/**
 * Oracle 5×7 font (render_styles.py FONT) plus the glyphs Stubtown needs for
 * live money and the CLINIC sign. Cell advance is 6·scale.
 */
const FONT: Record<string, readonly string[]> = {
  "0": ["01110", "10001", "10011", "10101", "11001", "10001", "01110"],
  "1": ["00100", "01100", "00100", "00100", "00100", "00100", "01110"],
  "2": ["01110", "10001", "00001", "00010", "00100", "01000", "11111"],
  "3": ["11110", "00001", "00001", "01110", "00001", "00001", "11110"],
  "4": ["00010", "00110", "01010", "10010", "11111", "00010", "00010"],
  "5": ["11111", "10000", "11110", "00001", "00001", "10001", "01110"],
  "6": ["01110", "10000", "10000", "11110", "10001", "10001", "01110"],
  "7": ["11111", "00001", "00010", "00100", "01000", "01000", "01000"],
  "8": ["01110", "10001", "10001", "01110", "10001", "10001", "01110"],
  "9": ["01110", "10001", "10001", "01111", "00001", "00001", "01110"],
  $: ["00100", "01111", "10100", "01110", "00101", "11110", "00100"],
  M: ["10001", "11011", "10101", "10101", "10001", "10001", "10001"],
  E: ["11111", "10000", "10000", "11110", "10000", "10000", "11111"],
  S: ["01111", "10000", "10000", "01110", "00001", "00001", "11110"],
  T: ["11111", "00100", "00100", "00100", "00100", "00100", "00100"],
  A: ["01110", "10001", "10001", "11111", "10001", "10001", "10001"],
  L: ["10000", "10000", "10000", "10000", "10000", "10000", "11111"],
  C: ["01110", "10001", "10000", "10000", "10000", "10001", "01110"],
  I: ["01110", "00100", "00100", "00100", "00100", "00100", "01110"],
  N: ["10001", "11001", "10101", "10011", "10001", "10001", "10001"],
  " ": ["00000", "00000", "00000", "00000", "00000", "00000", "00000"],
};

type Put = (x: number, y: number, c: Rgb) => void;

function drawText5x7(put: Put, x: number, y: number, s: string, color: Rgb, scale: number, shadow?: Rgb): number {
  let cx = x;
  for (const ch of s) {
    const g = FONT[ch] ?? FONT[" "]!;
    for (let gy = 0; gy < 7; gy++) {
      for (let gx = 0; gx < 5; gx++) {
        if (g[gy]![gx] !== "1") continue;
        for (let sy = 0; sy < scale; sy++) {
          for (let sx = 0; sx < scale; sx++) {
            const X = cx + gx * scale + sx;
            const Y = y + gy * scale + sy;
            if (shadow) put(X + 1, Y + 1, shadow);
          }
        }
      }
    }
    cx += 6 * scale;
  }
  cx = x;
  for (const ch of s) {
    const g = FONT[ch] ?? FONT[" "]!;
    for (let gy = 0; gy < 7; gy++) {
      for (let gx = 0; gx < 5; gx++) {
        if (g[gy]![gx] !== "1") continue;
        for (let sy = 0; sy < scale; sy++) {
          for (let sx = 0; sx < scale; sx++) put(cx + gx * scale + sx, y + gy * scale + sy, color);
        }
      }
    }
    cx += 6 * scale;
  }
  return cx - x;
}

export function textWidth5x7(s: string, scale = 1): number {
  return s.length * 6 * scale - scale;
}

function gfxPut(g: Gfx): Put {
  return (x, y, c) => g.p(x, y, rgba(c));
}

/** PIL-style inclusive rectangle outline. */
function rectOutline(g: Gfx, x0: number, y0: number, x1: number, y1: number, c: Rgba): void {
  g.fill(x0, y0, x1 - x0 + 1, 1, c);
  g.fill(x0, y1, x1 - x0 + 1, 1, c);
  g.fill(x0, y0, 1, y1 - y0 + 1, c);
  g.fill(x1, y0, 1, y1 - y0 + 1, c);
}

/** PIL-style ellipse: fill inside, 1px outline on the boundary ring. */
function ellipse(g: Gfx, cx: number, cy: number, r: number, fill: Rgba | null, outline: Rgba | null): void {
  const inside = (x: number, y: number): boolean => {
    const dx = x - cx;
    const dy = y - cy;
    return dx * dx + dy * dy <= r * r + r;
  };
  for (let y = cy - r; y <= cy + r; y++) {
    for (let x = cx - r; x <= cx + r; x++) {
      if (!inside(x, y)) continue;
      const edge = !inside(x - 1, y) || !inside(x + 1, y) || !inside(x, y - 1) || !inside(x, y + 1);
      if (edge && outline) g.p(x, y, outline);
      else if (fill) g.p(x, y, fill);
    }
  }
}

/**
 * Oracle `paint_hud`: double-border panel at (6,6) 148×26, coin, "N $MEME" 5×7 ×2.
 * The panel is drawn INTO the scene so HUD_PANEL blooms like the oracle; the scene draws the
 * `text` part again after capturing so the glyphs stay crisp above the bloom. Compact 1× on 240.
 */
export function hd2dMoneyHud(g: Gfx, money: number, wide = false, part: "all" | "panel" | "text" = "all"): void {
  const label = `${money} $MEME`;
  const scale = wide ? 2 : 1;
  const x0 = wide ? 6 : 4;
  const y0 = wide ? 6 : 4;
  const w = Math.max(wide ? 148 : 74, (wide ? 24 : 14) + textWidth5x7(label, scale) + (wide ? 8 : 4));
  const h = wide ? 26 : 14;
  if (part !== "text") {
    rectOutline(g, x0 - 1, y0 - 1, x0 + w + 1, y0 + h + 1, rgba(P.HUD_GRAY));
    g.fill(x0, y0, w + 1, h + 1, rgba(P.HUD_PANEL));
    rectOutline(g, x0, y0, x0 + w, y0 + h, rgba(P.HUD_INK));
    rectOutline(g, x0 + 1, y0 + 1, x0 + w - 1, y0 + h - 1, rgba(P.HUD_INK));
    g.fill(x0 + 2, y0 + h - 2, w - 3, 1, rgba(P.HUD_SHADE));
    g.fill(x0 + w - 2, y0 + 2, 1, h - 3, rgba(P.HUD_SHADE));
    const cx = x0 + (wide ? 12 : 7);
    const cy = y0 + (h >> 1);
    const r = wide ? 6 : 3;
    ellipse(g, cx, cy, r, rgba(P.COIN), rgba(P.COIN_RIM));
    if (wide) ellipse(g, cx, cy, r - 2, null, rgba(P.COIN_DK));
  }
  if (part === "panel") return;
  drawText5x7(gfxPut(g), x0 + (wide ? 24 : 14), y0 + ((h - 7 * scale) >> 1), label, P.HUD_INK, scale);
  // Harness hook: the combat tests read money text through g.text; keep it offscreen.
  g.text(x0, -20, label, rgba(P.HUD_INK));
}

const signCache = new Map<string, ImageData>();

/**
 * Oracle `paint_sign_band` + 5×7 SIGN_GOLD text with (10,5,0) drop shadow across
 * `tiles` sign tiles. Door columns stay transparent so the entrance reads; text is
 * centered in the widest non-door run.
 */
export function hd2dSignBand(tiles: number, label: string, doorCols: readonly number[]): ImageData {
  const key = `sign:${tiles}:${label}:${doorCols.join(",")}`;
  const hit = signCache.get(key);
  if (hit) return hit;
  const b = new Pix(tiles * 16, 16);
  for (let t = 0; t < tiles; t++) {
    if (doorCols.includes(t)) continue;
    b.fill(t * 16, 0, 16, 16, P.SIGN_BG);
    b.hline(t * 16, 0, 16, ORACLE.SIGN_EDGE);
    b.hline(t * 16, 15, 16, ORACLE.SIGN_EDGE);
  }
  let bestStart = 0;
  let bestLen = 0;
  let runStart = 0;
  for (let t = 0; t <= tiles; t++) {
    const door = t === tiles || doorCols.includes(t);
    if (door) {
      if (t - runStart > bestLen) {
        bestLen = t - runStart;
        bestStart = runStart;
      }
      runStart = t + 1;
    }
  }
  const tw = textWidth5x7(label, 1);
  const sx = bestStart * 16 + Math.max(1, ((bestLen * 16 - tw) >> 1));
  drawText5x7((x, y, c) => b.p(x, y, c), sx, 4, label, P.SIGN_GOLD, 1, ORACLE.SIGN_SHADOW);
  const img = b.toImage();
  signCache.set(key, img);
  return img;
}
