import { P, type Rgb } from "./palette.ts";
import { Pix } from "./pix.ts";
import type { TrainerId } from "../../data/trainers.ts";

/**
 * Scout 16×24 — SCOUT_MAP copied verbatim from render_styles.py.
 * The SC_OUT outline is CLOSED under the feet (row 23 `....OO....OO....`).
 * Walk / back / side frames are derived from the same map so the outline rule holds.
 */
export const SCOUT_MAP: readonly string[] = [
  "................",
  ".....OOOOOO.....",
  "....OHHHHHHO....",
  "...OHHHHHHHHO...",
  "...OHhHHHHHHO...",
  "...OHHHHHHHHO...",
  "...OFFFFFFFFO...",
  "...OFeFFFFeFO...",
  "...OFFFFFFFFO...",
  "....OFFFFFFO....",
  "...OWWWWWWWWO...",
  "..OWWWWWWWWWWO..",
  "..OWWWWWWWRROO..",
  "..OWWWWWWWRROO..",
  "..OWWWWWWWWWWO..",
  "...OWWWWWWWWO...",
  "...OBBBBBBBBO...",
  "...OBBBOOBBBO...",
  "...OBBO..OBBO...",
  "...OFFO..OFFO...",
  "...OFFO..OFFO...",
  "...ODDO..ODDO...",
  "...ODDO..ODDO...",
  "....OO....OO....",
];

const INK: Record<string, Rgb> = {
  O: P.SC_OUT,
  H: P.SC_HAIR,
  h: P.SC_HAIR_HI,
  F: P.SC_SKIN,
  e: P.SC_OUT,
  W: P.SC_SHIRT,
  R: P.SC_BAG,
  B: P.SC_SHORT,
  D: P.SC_SHOE,
  k: P.SC_SKIN_DK,
  d: P.SC_HAIR_DK,
  G: P.SIGN_GOLD,
  L: P.PLANK,
};

const cache = new Map<string, ImageData>();

function rows(): string[] {
  return SCOUT_MAP.map((r) => r);
}

function setCell(r: string[], x: number, y: number, ch: string): void {
  const row = r[y]!;
  r[y] = row.slice(0, x) + ch + row.slice(x + 1);
}

/** Lift one leg by a row (cols x0..x1, rows 16..23). Closed outline moves with the leg. */
function liftLeg(r: string[], x0: number, x1: number): void {
  for (let y = 17; y <= 23; y++) {
    for (let x = x0; x <= x1; x++) setCell(r, x, y, y + 1 <= 23 ? r[y + 1]![x]! : ".");
  }
  // keep the short hem attached where the leg met the body
  for (let x = x0; x <= x1; x++) if (r[16]![x] === "B" && r[17]![x] === ".") setCell(r, x, 17, "O");
}

function frontRows(step: 0 | 1): string[] {
  const r = rows();
  if (step) liftLeg(r, 9, 12);
  return r;
}

function backRows(step: 0 | 1): string[] {
  const r = rows();
  for (let y = 6; y <= 9; y++) {
    for (let x = 0; x < 16; x++) if (r[y]![x] === "F" || r[y]![x] === "e") setCell(r, x, y, "H");
  }
  setCell(r, 5, 4, "H");
  for (let y = 12; y <= 13; y++) {
    setCell(r, 10, y, "W");
    setCell(r, 11, y, "W");
    setCell(r, 12, y, "O");
    setCell(r, 13, y, ".");
    setCell(r, 6, y, "R");
    setCell(r, 7, y, "R");
    setCell(r, 8, y, "R");
  }
  if (step) liftLeg(r, 3, 6);
  return r;
}

function sideRows(step: 0 | 1): string[] {
  const r = rows();
  setCell(r, 5, 7, "F");
  if (step) liftLeg(r, 3, 6);
  return r;
}

function paintRows(b: Pix, r: readonly string[]): void {
  for (let y = 0; y < r.length; y++) {
    const row = r[y]!;
    for (let x = 0; x < row.length; x++) {
      const ch = row[x]!;
      if (ch === ".") continue;
      b.p(x, y, INK[ch] ?? P.SC_OUT);
    }
  }
}

export function hd2dPlayer(dir: 0 | 1 | 2 | 3, step: 0 | 1): ImageData {
  const key = `scout:${dir}:${step}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Pix(16, 24);
  let r: string[];
  if (dir === 0) r = backRows(step);
  else if (dir === 2 || dir === 3) r = sideRows(step);
  else r = frontRows(step);
  if (dir === 3) r = r.map((row) => [...row].reverse().join(""));
  paintRows(b, r);
  const img = b.toImage();
  cache.set(key, img);
  return img;
}

/** Stubtown NPCs on the scout chassis, locked palette only. */
export function hd2dNpc(who: "nurse" | "vendor"): ImageData {
  const hit = cache.get(who);
  if (hit) return hit;
  const r = rows();
  for (let y = 2; y <= 5; y++) {
    for (let x = 0; x < 16; x++) if (r[y]![x] === "H" || r[y]![x] === "h") setCell(r, x, y, who === "nurse" ? "W" : "d");
  }
  if (who === "nurse") {
    setCell(r, 7, 3, "R");
    setCell(r, 8, 3, "R");
    setCell(r, 7, 2, "R");
    setCell(r, 7, 4, "R");
    for (let y = 12; y <= 13; y++) {
      setCell(r, 10, y, "W");
      setCell(r, 11, y, "W");
    }
  } else {
    for (let y = 10; y <= 15; y++) {
      for (let x = 0; x < 16; x++) if (r[y]![x] === "W") setCell(r, x, y, "L");
    }
    setCell(r, 7, 12, "G");
    setCell(r, 8, 12, "G");
    setCell(r, 7, 13, "G");
    setCell(r, 8, 13, "G");
  }
  const b = new Pix(16, 24);
  paintRows(b, r);
  const img = b.toImage();
  cache.set(who, img);
  return img;
}

/** Route rivals share the world's native pixel scale with distinct hats and uniforms. */
export function hd2dTrainer(who: TrainerId): ImageData {
  const key = `trainer:${who}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const r = rows();
  for (let y = 10; y < 16; y++) {
    for (let x = 0; x < 16; x++) {
      if (r[y]![x] === "W") setCell(r, x, y, who === "tavi" || who === "nix" ? "B" : who === "brin" || who === "mica" ? "L" : "d");
    }
  }
  if (who === "tavi") {
    for (let x = 4; x <= 12; x++) setCell(r, x, 4, "G");
    setCell(r, 12, 5, "G"); setCell(r, 13, 5, "G");
    setCell(r, 6, 12, "W"); setCell(r, 6, 13, "W");
  } else if (who === "pella") {
    // Cream patchwork apron, blue folded cap, gold stitches and a small thread spool.
    for (let x = 4; x <= 11; x++) setCell(r, x, 3, "B");
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "B");
    setCell(r, 5, 3, "W"); setCell(r, 6, 3, "W");
    for (let y = 10; y <= 15; y++) for (let x = 5; x <= 10; x++) setCell(r, x, y, "W");
    for (const [x, y] of [[6, 11], [8, 11], [6, 13], [8, 13]]) setCell(r, x!, y!, "G");
    setCell(r, 9, 14, "B"); setCell(r, 10, 14, "B"); setCell(r, 9, 15, "B");
    for (let y = 12; y <= 15; y++) { setCell(r, 12, y, "L"); setCell(r, 13, y, "G"); }
    setCell(r, 12, 11, "W"); setCell(r, 13, 11, "W");
    setCell(r, 12, 16, "W"); setCell(r, 13, 16, "W");
  } else if (who === "brin") {
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "D");
    for (let y = 1; y <= 3; y++) for (let x = 5; x <= 10; x++) setCell(r, x, y, "L");
    setCell(r, 7, 12, "G"); setCell(r, 8, 12, "G");
  } else if (who === "vell") {
    // A reed crown, wax mantle and hand-held wick in the existing world inks.
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "G");
    for (const x of [4, 7, 10]) { setCell(r, x, 2, "G"); setCell(r, x, 3, "G"); }
    for (let y = 10; y <= 15; y++) { setCell(r, 5, y, "W"); setCell(r, 10, y, "W"); }
    for (let y = 9; y <= 15; y++) setCell(r, 13, y, "G");
    setCell(r, 13, 8, "R"); setCell(r, 13, 7, "W");
  } else if (who === "ilex") {
    // A wind-folded cream cap, blue coat, diagonal mail strap and rolled letter.
    for (let x = 4; x <= 11; x++) setCell(r, x, 3, "W");
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "W");
    setCell(r, 10, 2, "W"); setCell(r, 11, 2, "G");
    for (let y = 10; y <= 15; y++) {
      for (let x = 4; x <= 11; x++) if(r[y]![x] === "d") setCell(r, x, y, "B");
      setCell(r, 4 + y - 10, y, "L");
    }
    for (let y = 12; y <= 16; y++) { setCell(r, 12, y, "W"); setCell(r, 13, y, "G"); }
    setCell(r, 12, 14, "R"); setCell(r, 13, 14, "R");
  } else if (who === "rook") {
    // Oversized ear warmers and a reply-scroll scarf.
    for (let y = 4; y <= 7; y++) { setCell(r, 3, y, "W"); setCell(r, 12, y, "W"); }
    for (let x = 4; x <= 11; x++) setCell(r, x, 10, "R");
    for (let y = 11; y <= 16; y++) setCell(r, 5, y, "W");
    setCell(r, 5, 12, "G"); setCell(r, 5, 14, "G");
  } else if (who === "mica") {
    // Archive visor, tiny spectacles and a strapped paper folio.
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "B");
    for (const x of [5, 6, 8, 9]) setCell(r, x, 7, "G");
    setCell(r, 7, 7, "O");
    for (let y = 11; y <= 15; y++) for (let x = 9; x <= 12; x++) setCell(r, x, y, "W");
    for (let y = 11; y <= 15; y++) setCell(r, 10, y, "R");
  } else if (who === "nix") {
    // Night watch cap and lantern, with the native gold/wood material ramps.
    for (let x = 4; x <= 11; x++) setCell(r, x, 3, "B");
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "B");
    setCell(r, 7, 3, "G"); setCell(r, 8, 3, "G");
    for (let y = 10; y <= 14; y++) setCell(r, 13, y, "L");
    for (let y = 14; y <= 17; y++) for (let x = 12; x <= 14; x++) setCell(r, x, y, "O");
    setCell(r, 13, 15, "G"); setCell(r, 13, 16, "W");
  } else {
    for (let x = 3; x <= 12; x++) setCell(r, x, 4, "W");
    for (let x = 6; x <= 9; x++) setCell(r, x, 3, "R");
    for (let y = 11; y <= 15; y++) setCell(r, 7, y, "G");
  }
  const b = new Pix(16, 24);
  paintRows(b, r);
  const img = b.toImage();
  cache.set(key, img);
  return img;
}
