export type KeyName =
  | "ArrowUp"
  | "ArrowDown"
  | "ArrowLeft"
  | "ArrowRight"
  | "Enter"
  | "Escape"
  | "Shift"
  | "Tab";

const MAP: Record<string, KeyName> = {
  ArrowUp: "ArrowUp",
  ArrowDown: "ArrowDown",
  ArrowLeft: "ArrowLeft",
  ArrowRight: "ArrowRight",
  w: "ArrowUp",
  W: "ArrowUp",
  s: "ArrowDown",
  S: "ArrowDown",
  a: "ArrowLeft",
  A: "ArrowLeft",
  d: "ArrowRight",
  D: "ArrowRight",
  Enter: "Enter",
  z: "Enter",
  Z: "Enter",
  " ": "Enter",
  Escape: "Escape",
  x: "Escape",
  X: "Escape",
  Backspace: "Escape",
  Shift: "Shift",
  Tab: "Tab",
};

export class Input {
  down = new Set<KeyName>();
  pressed = new Set<KeyName>();
  private hold = new Map<KeyName, number>();

  attach(root: HTMLElement): void {
    window.addEventListener("keydown", this.onKeyDown);
    window.addEventListener("keyup", this.onKeyUp);
    root.querySelectorAll<HTMLButtonElement>("[data-key]").forEach((btn) => {
      const key = btn.dataset.key as KeyName | undefined;
      if (!key) return;
      const start = (e: Event) => {
        e.preventDefault();
        this.feed(key, true);
      };
      const end = (e: Event) => {
        e.preventDefault();
        this.feed(key, false);
      };
      btn.addEventListener("pointerdown", start);
      btn.addEventListener("pointerup", end);
      btn.addEventListener("pointerleave", end);
      btn.addEventListener("pointercancel", end);
    });
    window.addEventListener("blur", () => this.reset());
    document.addEventListener("visibilitychange", () => {
      if (document.hidden) this.reset();
    });
  }

  private onKeyDown = (e: KeyboardEvent): void => {
    const key = MAP[e.key];
    if (!key) return;
    e.preventDefault();
    if (e.repeat) return;
    this.feed(key, true);
  };

  private onKeyUp = (e: KeyboardEvent): void => {
    const key = MAP[e.key];
    if (!key) return;
    e.preventDefault();
    this.feed(key, false);
  };

  feed(key: KeyName, isDown: boolean): void {
    if (isDown) {
      if (!this.down.has(key)) this.pressed.add(key);
      this.down.add(key);
    } else {
      this.down.delete(key);
      this.hold.delete(key);
    }
  }

  consume(key: KeyName): boolean {
    if (this.pressed.has(key)) {
      this.pressed.delete(key);
      return true;
    }
    return false;
  }

  consumeAny(...keys: KeyName[]): boolean {
    let consumed = false;
    for (const key of keys) if (this.consume(key)) consumed = true;
    return consumed;
  }

  dirPressed(): { x: number; y: number } | null {
    if (this.consume("ArrowUp")) return { x: 0, y: -1 };
    if (this.consume("ArrowDown")) return { x: 0, y: 1 };
    if (this.consume("ArrowLeft")) return { x: -1, y: 0 };
    if (this.consume("ArrowRight")) return { x: 1, y: 0 };
    return null;
  }

  heldDir(now: number, initial = 180, repeat = 90): { x: number; y: number } | null {
    const order: [KeyName, number, number][] = [
      ["ArrowUp", 0, -1],
      ["ArrowDown", 0, 1],
      ["ArrowLeft", -1, 0],
      ["ArrowRight", 1, 0],
    ];
    for (const [key, x, y] of order) {
      if (!this.down.has(key)) {
        this.hold.delete(key);
        continue;
      }
      const t = this.hold.get(key);
      if (t === undefined) {
        this.hold.set(key, now);
        return { x, y };
      }
      if (now - t >= initial) {
        this.hold.set(key, now - initial + repeat);
        return { x, y };
      }
    }
    return null;
  }

  endFrame(): void {
    this.pressed.clear();
  }

  reset(): void {
    this.down.clear();
    this.pressed.clear();
    this.hold.clear();
  }
}
