import { MAP_H, MAP_W, tileAt } from "../data/map.ts";
import { MAP_PINS, routeToPin, type MapRoute } from "../data/routeMap.ts";
import { routePlan } from "../data/routePlan.ts";
import { TRAINERS, trainerLock } from "../data/trainers.ts";
import { C } from "../engine/gfx.ts";
import type { Ctx } from "../game/ctx.ts";
import type { Scene } from "../game/scenes.ts";

const SCALE = 3, X = 54, Y = 29;

export function routeMapScene(ctx: Ctx): Scene {
  let selected = 0, route: MapRoute | null = null;
  const refresh = () => { route = routeToPin(ctx.state, MAP_PINS[selected]!); };
  return {
    id: "map",
    enter() {
      selected = Math.max(0, MAP_PINS.findIndex(p => p.trainer === routePlan(ctx.state).next.id));
      refresh();
    },
    exit() {},
    update() {
      if (ctx.input.consume("Escape")) { ctx.audio.back(); ctx.pop(); return; }
      const d = ctx.input.dirPressed();
      if (ctx.input.consume("Enter") || d?.x || d?.y) {
        selected = (selected + (d && (d.x < 0 || d.y < 0) ? -1 : 1) + MAP_PINS.length) % MAP_PINS.length;
        refresh(); ctx.audio.cursor();
      }
    },
    draw() {
      const g = ctx.g, pin = MAP_PINS[selected]!;
      g.clear([36, 32, 28, 255]); g.panel(4, 4, 232, 152);
      g.fill(8, 8, 224, 14, C.goldHi); g.text(12, 11, "ROUTE MAP", C.ink);
      g.text(174, 11, `${selected + 1}/${MAP_PINS.length}`, C.ink);
      g.text(12, 34, "+ YOU", C.ink);
      g.text(12, 47, "o PIN", C.ink);
      g.text(12, 64, "GOLD", C.ink); g.fill(40, 64, 8, 6, C.goldHi); g.text(12, 74, "ROUTE", C.ink);
      g.text(12, 91, "BLUE", C.ink); g.fill(40, 91, 8, 6, C.cyan); g.text(12, 101, "STOP", C.ink);
      g.rect(X - 2, Y - 2, MAP_W * SCALE + 4, MAP_H * SCALE + 4, C.ink);
      for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) {
        const t = tileAt(x, y);
        const color = t.water ? C.waterDeep : t.solid ? C.slate : t.tall ? C.mossDeep
          : t.id === "path" || t.id === "door" || t.id === "rest" ? C.dirt : C.paperDark;
        g.fill(X + x * SCALE, Y + y * SCALE, SCALE, SCALE, color);
        if (t.tall) g.p(X + x * SCALE + 1, Y + y * SCALE + 1, C.mossHi);
      }
      for (const t of route?.tiles ?? []) g.fill(X + t.x * SCALE + 1, Y + t.y * SCALE + 1, 2, 2, C.goldHi);
      for (const p of MAP_PINS) g.fill(X + p.x * SCALE, Y + p.y * SCALE, 3, 3, p.kind === "trainer" ? C.violet : C.cyan);
      const px = X + ctx.state.x * SCALE + 1, py = Y + ctx.state.y * SCALE + 1;
      g.hline(px - 2, py, 5, C.white); g.fill(px, py - 2, 1, 5, C.white);
      const tx = X + pin.x * SCALE, ty = Y + pin.y * SCALE;
      g.rect(tx - 2, ty - 2, 7, 7, C.ink); g.rect(tx - 1, ty - 1, 5, 5, C.goldHi);
      const locked = pin.trainer && trainerLock(TRAINERS[pin.trainer], ctx.state);
      const label = locked ? (ctx.state.defeatedTrainers.includes(pin.trainer!)
        ? TRAINERS[pin.trainer!].rematchPrize ? " / WAIT" : " / DONE" : " / LOCK") : "";
      g.text(12, 123, pin.name + label, C.ink);
      const status = route ? `${route.tiles.length - 1} steps / ${route.grassSteps} grass steps` : "No walkable route from here.";
      g.text(12, 134, status, C.ink);
      g.text(12, 145, "A / arrows: pin   B back", C.ink);
    },
  };
}
