import type { MoveDef } from "../data/moves.ts";
import { TYPE_META } from "../data/types.ts";
import { C, type Gfx, type Rgba } from "../engine/gfx.ts";
import type { StrikeResult } from "../game/combat.ts";

export type AttackFamily = "melee" | "projectile" | "beam" | "status";
export interface AttackCue {
  move: MoveDef;
  own: boolean;
  elapsed: number;
  result: StrikeResult | null;
}

const PROJECTILES = new Set([
  "pondPump", "copeSplash", "feelsBad", "panicSell", "diamondBark",
  "airdropFetch", "marketCapsize", "liquidityWave", "cashRain", "hoverTax",
  "confettiBurst", "greenWick", "bagBrine",
  "queueCry", "sootSpit", "slipstream", "ticketToss", "thawDrip",
  "reedDecree", "bottleStorm", "echoFetch", "falseBeacon", "rainFreight",
]);
const BEAMS = new Set(["laserGlare", "moonHowl", "ringFlash", "chartFlare", "candleBreath", "ventBeam", "brineSiphon", "mintRay",
  "nightSignal", "marshDue", "prismFang", "orbitLance", "canopyFlare"]);
const FRAME = 1000 / 60;

export function attackFamily(move: MoveDef): AttackFamily {
  if (move.power === 0) return "status";
  if (BEAMS.has(move.id)) return "beam";
  if (PROJECTILES.has(move.id)) return "projectile";
  return "melee";
}

/** All timings are milliseconds: 14–18 authored frames at 60 Hz, independent of render rate. */
export function attackTiming(move: MoveDef): { impact: number; duration: number } {
  switch (attackFamily(move)) {
    case "melee": return { impact: 6 * FRAME, duration: 16 * FRAME };
    case "beam": return { impact: 6 * FRAME, duration: 14 * FRAME };
    case "projectile": return { impact: 8 * FRAME, duration: 18 * FRAME };
    case "status": return { impact: 6 * FRAME, duration: 18 * FRAME };
  }
}

export function statusOnSelf(move: MoveDef): boolean {
  return move.fx?.kind === "heal" || move.fx?.kind === "surehit" ||
    (move.fx?.kind === "stat" && move.fx.target === "self");
}

export function attackPose(cue: AttackCue): { x: number; y: number } {
  const { impact, duration } = attackTiming(cue.move);
  const t = cue.elapsed;
  if (t >= duration) return { x: 0, y: 0 };
  const dir = cue.own ? 1 : -1;
  if (attackFamily(cue.move) !== "melee") {
    return { x: t < impact ? -dir * 2 : 0, y: 0 };
  }
  let reach: number;
  if (t < 2 * FRAME) reach = -0.035 * t / (2 * FRAME);
  else if (t < impact) reach = -0.035 + 1.035 * ((t - 2 * FRAME) / (impact - 2 * FRAME)) ** 2;
  else if (t < impact + 2 * FRAME) reach = 1;
  else reach = (1 - (t - impact - 2 * FRAME) / (duration - impact - 2 * FRAME)) ** 2;
  return { x: Math.round(dir * 110 * reach), y: Math.round(-dir * 44 * reach) };
}

function line(g: Gfx, x0: number, y0: number, x1: number, y1: number, c: Rgba, width = 1): void {
  const n = Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0))));
  for (let i = 0; i <= n; i++) {
    g.fill(Math.round(x0 + (x1 - x0) * i / n), Math.round(y0 + (y1 - y0) * i / n), width, width, c);
  }
}

function diamond(g: Gfx, x: number, y: number, r: number, c: Rgba): void {
  for (let yy = -r; yy <= r; yy++) g.hline(x - r + Math.abs(yy), y + yy, (r - Math.abs(yy)) * 2 + 1, c);
}

function sparkle(g: Gfx, x: number, y: number, r: number, c: Rgba): void {
  g.hline(x - r, y, r * 2 + 1, c);
  g.fill(x, y - r, 1, r * 2 + 1, c);
  g.p(x, y, C.white);
}

const flashCache = new WeakMap<ImageData, ImageData>();
export function hitSprite(src: ImageData): ImageData {
  const hit = flashCache.get(src);
  if (hit) return hit;
  const img = new ImageData(src.width, src.height);
  for (let i = 0; i < src.data.length; i += 4) {
    img.data[i] = C.white[0]; img.data[i + 1] = C.white[1]; img.data[i + 2] = C.white[2];
    img.data[i + 3] = src.data[i + 3]!;
  }
  flashCache.set(src, img);
  return img;
}

/** Procedural, local effects only. Never draws over the UI or consumes gameplay RNG. */
export function drawAttack(g: Gfx, cue: AttackCue): void {
  const family = attackFamily(cue.move);
  const { impact, duration } = attackTiming(cue.move);
  const t = cue.elapsed;
  const after = Math.max(0, (t - impact) / (duration - impact));
  const color = TYPE_META[cue.move.type].ink;
  const from = cue.own ? { x: 43, y: 73 } : { x: 159, y: 26 };
  const to = cue.own ? { x: 164, y: 25 } : { x: 34, y: 74 };
  const dir = cue.own ? 1 : -1;
  const missed = cue.result?.hit === false;
  const tx = to.x + (missed ? dir * 15 : 0);
  const ty = to.y + (missed ? -13 : 0);

  if (family === "melee") {
    const pose = attackPose(cue);
    if (t > 2 * FRAME && t < impact + 3 * FRAME) {
      for (let i = 0; i < 3; i++) {
        const x = from.x + pose.x - dir * (11 + i * 4);
        const y = from.y + pose.y + i * 4;
        line(g, x - dir * 14, y + dir * 4, x, y, i === 1 ? C.white : color);
      }
    }
  } else if (family === "beam") {
    if (t < impact) {
      sparkle(g, from.x, from.y, 2 + Math.floor(t / impact * 4), color);
    } else if (after < 0.62) {
      line(g, from.x, from.y, tx, ty, color, 3);
      line(g, from.x, from.y + 1, tx, ty + 1, C.white);
      line(g, from.x, from.y - 3, tx, ty - 3, color);
      line(g, from.x, from.y + 5, tx, ty + 5, color);
    }
  } else if (family === "projectile") {
    const progress = Math.min(1, Math.max(0, (t - FRAME) / (impact - FRAME)));
    if (t <= impact || (missed && after < 0.55)) {
      const travel = missed ? 1 + after * 0.2 : progress;
      for (let i = 3; i >= 0; i--) {
        const p = Math.max(0, travel - i * 0.09);
        const x = Math.round(from.x + (tx - from.x) * p);
        const y = Math.round(from.y + (ty - from.y) * p + Math.sin(p * Math.PI) * 6);
        diamond(g, x, y, Math.max(1, 5 - i), i ? color : C.white);
        if (!i) diamond(g, x, y, 3, color);
      }
    }
  } else {
    const self = statusOnSelf(cue.move);
    const center = self ? (cue.own ? { x: 33, y: 74 } : { x: 164, y: 25 }) : { x: tx, y: ty };
    const spread = 9 + Math.round(Math.sin(Math.min(1, t / duration) * Math.PI) * 8);
    for (let i = 0; i < 6; i++) {
      const a = i * Math.PI / 3 + t / duration * Math.PI;
      const x = Math.round(center.x + Math.cos(a) * spread);
      const y = Math.round(center.y + Math.sin(a) * 10 - t / duration * 7);
      if (cue.move.fx?.kind === "heal") sparkle(g, x, y, 2, color);
      else diamond(g, x, y, 2, i % 2 ? color : C.white);
    }
    // Upward self buffs, downward debuffs; the affected creature remains visible.
    for (let i = 0; i < 3; i++) {
      const x = center.x - 12 + i * 12;
      const y = center.y + 10 - Math.round(t / duration * 22) * (self ? 1 : -0.4);
      line(g, x - 2, y + (self ? 2 : -2), x, y, color);
      line(g, x, y, x + 2, y + (self ? 2 : -2), color);
    }
  }

  if (!cue.result) return;
  if (missed) {
    // Open arcs and displaced dust; no contact flash, HP loss or impact star.
    for (let i = 0; i < 3; i++) {
      const x = tx + dir * Math.round(after * 13) - i * 3;
      line(g, x, ty + i * 5, x + dir * 7, ty + i * 5 - 2, C.foam);
    }
    g.textShadow(to.x - 12, to.y - 19, "MISS", C.white, C.ink);
  } else if (cue.result.dmg > 0) {
    const r = Math.round((cue.result.crit ? 16 : 11) * (1 - after)) + 2;
    for (let i = 0; i < 8; i++) {
      const a = i * Math.PI / 4;
      const inner = 3 + after * 8;
      line(g, to.x + Math.cos(a) * inner, to.y + Math.sin(a) * inner,
        to.x + Math.cos(a) * (r + inner), to.y + Math.sin(a) * (r + inner), color, 2);
    }
    if (after < 0.4) {
      line(g, to.x - r, to.y + r, to.x + r, to.y - r, C.white, 2);
      line(g, to.x - r, to.y - r, to.x + r, to.y + r, C.white);
    }
    if (cue.result.crit && after < 0.8) {
      sparkle(g, to.x - 19, to.y, 4, C.goldHi);
      sparkle(g, to.x + 19, to.y - 7, 3, C.goldHi);
      g.textShadow(to.x - 12, to.y - 21, "CRIT", C.goldHi, C.ink);
    }
  }
}
