const cache = new Map<string, Uint8Array>();

function glyph(ch: string): Uint8Array {
  const hit = cache.get(ch);
  if (hit) return hit;
  const hex = (RAW[ch] ?? "7088081020F80000").padEnd(16, "0").slice(0, 16);
  const rows = new Uint8Array(8);
  for (let i = 0; i < 8; i++) rows[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  cache.set(ch, rows);
  return rows;
}

export const FONT_W = 6;
export const FONT_H = 8;

export function measureText(text: string): number {
  return text.length * FONT_W;
}

export function drawText(
  img: ImageData,
  x: number,
  y: number,
  text: string,
  color: readonly [number, number, number, number],
  wrap = 0,
): number {
  const w = img.width;
  const data = img.data;
  let cx = x;
  let cy = y;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]!;
    if (ch === "\n") {
      cx = x;
      cy += FONT_H;
      continue;
    }
    if (wrap > 0 && ch === " " && cx + FONT_W > x + wrap) {
      cx = x;
      cy += FONT_H;
      continue;
    }
    const rows = glyph(ch);
    for (let row = 0; row < 8; row++) {
      const bits = rows[row]!;
      for (let col = 0; col < 5; col++) {
        if (((bits >> (7 - col)) & 1) === 0) continue;
        const px = cx + col;
        const py = cy + row;
        if (px < 0 || py < 0 || px >= w || py >= img.height) continue;
        const o = (py * w + px) * 4;
        data[o] = color[0];
        data[o + 1] = color[1];
        data[o + 2] = color[2];
        data[o + 3] = color[3];
      }
    }
    cx += FONT_W;
  }
  return cy + FONT_H;
}

export function wrapLines(text: string, cols: number): string[] {
  const out: string[] = [];
  for (const para of text.split("\n")) {
    const words = para.split(" ");
    let line = "";
    for (const word of words) {
      const next = line ? `${line} ${word}` : word;
      if (next.length > cols && line) {
        out.push(line);
        line = word;
      } else {
        line = next;
      }
    }
    out.push(line);
  }
  return out;
}
