/** Deterministic per-tile hash — port of render_styles.py `thash` (FNV-1a, 32-bit). */
export function thash(...args: number[]): number {
  let h = 2166136261;
  for (const a of args) {
    h = Math.imul(h ^ (a >>> 0), 16777619) >>> 0;
  }
  return h >>> 0;
}

/** `(h >> s) % n` with Python's unsigned semantics. */
export function hs(h: number, shift: number, mod: number): number {
  return (shift >= 32 ? 0 : h >>> shift) % mod;
}
