import { LCD } from "./lcd.ts";
import { R, Toy, type Ramp } from "./toy.ts";
import type { SpeciesId } from "../data/species.ts";

/**
 * Creature painters on the vinyl-toy rig (toy.ts): rounded, key-lit volumes with rim light,
 * glossy eyes and each species' signature accessory, in the locked 32-colour LCD master.
 * Frames are 32×32 with feet on row 29; fronts face the camera, backs are the same volumes
 * seen from behind. Original IP only.
 */
export type Pose = "front" | "back";
type Paint = (t: Toy, back: boolean) => void;

// ---------------------------------------------------------------------------
// face + accessory library
// ---------------------------------------------------------------------------

const INK = R.ink;
const WHITE = R.white;

/** Big glossy toy eye, 4×5, top-left at (x, y). */
function eyeBig(t: Toy, x: number, y: number, iris: Ramp = R.blue): void {
  t.rect(x + 1, y, 2, 1, INK, 1);
  t.rect(x, y + 1, 4, 3, INK, 1);
  t.rect(x + 1, y + 4, 2, 1, INK, 1);
  t.px(x + 2, y + 3, iris, 1);
  t.px(x + 1, y + 1, WHITE);
  t.px(x + 1, y + 2, WHITE);
}

/** 3×3 bead eye with a highlight. */
function eyeBead(t: Toy, x: number, y: number): void {
  t.rect(x, y, 3, 3, INK, 1);
  t.px(x, y, WHITE);
}

/** 2×2 dot eye. */
function eyeDot(t: Toy, x: number, y: number): void {
  t.rect(x, y, 2, 2, INK, 1);
  t.px(x, y, WHITE);
}

/** Half-lidded sly eye, 3 wide. */
function eyeSleepy(t: Toy, x: number, y: number): void {
  t.hline(x, y, 3, INK, 1);
  t.rect(x, y + 1, 3, 2, INK, 1);
  t.px(x + 2, y + 1, WHITE);
}

/** Angry brow over an eye whose top-left is (x, y); `dir` +1 slants down toward the centre. */
function brow(t: Toy, x: number, y: number, dir: 1 | -1): void {
  t.px(x, y - 1 - (dir > 0 ? 1 : 0), INK, 1);
  t.px(x + 1, y - 1, INK, 1);
  t.px(x + 2, y - 1 - (dir > 0 ? 0 : 1), INK, 1);
}

/** Glowing visor band with two laser points. */
function visor(t: Toy, x: number, y: number, w: number): void {
  t.rect(x, y, w, 3, R.slate, 1);
  t.hline(x + 1, y + 1, w - 2, R.blue, 1);
  t.px(x + 2, y + 1, R.blue, 0);
  t.px(x + w - 3, y + 1, R.blue, 0);
  t.px(x + Math.floor(w / 2) - 3, y + 1, R.rose, 1);
  t.px(x + Math.floor(w / 2) + 2, y + 1, R.rose, 1);
}

function nose(t: Toy, x: number, y: number): void {
  t.hline(x, y, 2, INK, 1);
}

/** Small smile, w = 3 or 5. */
function smile(t: Toy, x: number, y: number, w = 3): void {
  t.px(x, y, INK, 1);
  t.hline(x + 1, y + 1, w - 2, INK, 1);
  t.px(x + w - 1, y, INK, 1);
}

function frown(t: Toy, x: number, y: number, w = 4): void {
  t.hline(x, y, w, INK, 1);
}

/** Open mouth with a rose inside and white teeth along the top. */
function grin(t: Toy, x: number, y: number, w: number, h: number): void {
  t.rect(x, y, w, h, INK, 1);
  if (h >= 3) t.rect(x + 1, y + 1, w - 2, h - 2, R.rose, 2);
  for (let i = 1; i < w - 1; i += 2) t.px(x + i, y, WHITE);
}

/** Toothy grin line with alternating teeth. */
function teeth(t: Toy, x: number, y: number, w: number): void {
  t.hline(x, y, w, INK, 1);
  for (let i = 1; i < w - 1; i += 2) t.px(x + i, y, WHITE);
}

/** Pointed ear with apex at (ax, ay) and a base centred on (bx, by). */
function earPoint(t: Toy, bx: number, by: number, ax: number, ay: number, fur: Ramp, inner?: Ramp, half = 3): void {
  t.poly([[bx - half, by], [bx + half, by], [ax, ay]], fur, { grad: true });
  if (inner) t.poly([[bx - half + 1.5, by], [bx + half - 1.5, by], [ax, ay + (by - ay) * 0.35]], inner, { tone: 1 });
}

/** Two paws on the baseline. */
function paws(t: Toy, cx: number, spread: number, r: number, fur: Ramp, o: { shade?: number } = {}): void {
  for (const x of [cx - spread, cx + spread]) {
    t.ell(x, 27.6, r, r * 0.75, fur, { spec: false, shade: o.shade });
    t.darken(Math.round(x) - 1, 29);
    t.darken(Math.round(x) + 1, 29);
  }
}

function crown(t: Toy, cx: number, y: number, w: number): void {
  const x0 = Math.round(cx - w / 2);
  t.rect(x0, y + 2, w, 2, R.gold, 1);
  t.hline(x0 + 1, y + 2, w - 2, R.gold, 0);
  t.vline(x0, y, 2, R.gold, 0);
  t.vline(x0 + w - 1, y, 2, R.gold, 0);
  t.px(Math.round(cx) - (w % 2 ? 0 : 1), y, R.gold, 0);
  t.px(Math.round(cx) - (w % 2 ? 0 : 1), y + 1, R.gold, 0);
  t.px(Math.round(cx) - (w % 2 ? 0 : 1), y + 3, R.rose, 1);
}

/** Candle flame, tip at (x, y), height h. */
function flame(t: Toy, x: number, y: number, h: number): void {
  t.poly([[x - 1.5, y + h], [x + 1.5, y + h], [x, y]], R.gold, { tone: 1 });
  t.vline(x, y + 1, Math.max(1, h - 2), R.gold, 0);
  t.px(x, y + h - 1, WHITE);
}

/** Front arc of a ring (angles in radians, screen space). */
function arc(t: Toy, cx: number, cy: number, rx: number, ry: number, a0: number, a1: number, ramp: Ramp, tone = 0): void {
  const steps = Math.max(16, Math.round((rx + ry) * 3));
  for (let i = 0; i <= steps; i++) {
    const a = a0 + ((a1 - a0) * i) / steps;
    t.px(Math.round(cx + Math.cos(a) * rx), Math.round(cy + Math.sin(a) * ry), ramp, tone);
  }
}

