const diamondshell: Paint = (t, back) => {
  for (const x of [8, 24]) t.ell(x, 26, 3, 2.5, R.blue, { shade: 1, spec: false });
  for (const x of [12, 20]) t.ell(x, 28, 2.5, 1.6, R.blue, { shade: 2, spec: false });
  t.ell(16, 17, 11, 8.5, R.blue);
  // Faceted shell: a diamond lattice cut into the shell only, lit cells toward the key light.
  for (let y = 9; y <= 25; y++) for (let x = 6; x <= 26; x++) {
    if (!t.has(x, y)) continue;
    const a = x + y - 8, b = x - y + 24;
    if (a % 5 === 0 || b % 5 === 0) { t.darken(x, y); continue; }
    const cell = Math.floor(a / 5) + Math.floor(b / 5);
    if (cell % 2 === 0 && x + y < 34) t.lighten(x, y);
  }
  t.ring(16, 17, 11, 8.5, R.gold, 1);
  t.ell(16, 8.5, 4.5, 4, R.blue, { shade: 1 });
  if (back) return;
  eyeBead(t, 13, 7);
  eyeBead(t, 17, 7);
  brow(t, 13, 7, 1);
  brow(t, 17, 7, -1);
  t.px(16, 11, INK, 1);
};

