import { AudioBus } from "../engine/audio.ts";
import { Gfx, OW_W } from "../engine/gfx.ts";
import { Input } from "../engine/input.ts";
import { hashSeed, readSeedFromUrl, Rng } from "../engine/rng.ts";
import { expToNext, mintMon } from "./mon.ts";
import { loadSave, newGame, persist, type SaveState } from "./save.ts";
import { battleScene } from "../scenes/battle.ts";
import {
  bagScene,
  clinicScene,
  indexScene,
  partyScene,
  pauseScene,
  pcScene,
  shopScene,
  summaryScene,
} from "../scenes/menus.ts";
import { overworldScene } from "../scenes/overworld.ts";
import { routePlanScene } from "../scenes/routePlan.ts";
import { routeMapScene } from "../scenes/routeMap.ts";
import { starterScene, titleScene } from "../scenes/title.ts";
import type { Ctx } from "./ctx.ts";
import type { Scene, SceneId, ScenePayload } from "./scenes.ts";
import { CIRCUIT_IDS, TRAINERS } from "../data/trainers.ts";
import type { SpeciesId } from "../data/species.ts";

function readShot(): string | null {
  return new URLSearchParams(window.location.search).get("shot");
}

export class Game implements Ctx {
  g: Gfx;
  input: Input;
  audio: AudioBus;
  rng: Rng;
  state: SaveState;
  reduced: boolean;
  now = 0;
  dt = 0;
  shot: string | null;
  grassQuiet = 0;
  private stack: Scene[] = [];
  private last = 0;

  constructor(canvas: HTMLCanvasElement) {
    this.g = new Gfx(canvas);
    this.input = new Input();
    this.audio = new AudioBus();
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    this.reduced = motion.matches;
    this.g.reduced = this.reduced;
    motion.addEventListener("change", () => {
      this.reduced = motion.matches;
      this.g.reduced = this.reduced;
    });
    this.shot = readShot();
    const seed = readSeedFromUrl();
    this.state = newGame(seed, "shibonk");
    this.rng = new Rng(this.state.rng);
    this.input.attach(document.getElementById("touch") ?? document.body);
    window.addEventListener("keydown", (e) => {
      if (e.repeat) return;
      if (e.key === "h" || e.key === "H") this.g.postEnabled = !this.g.postEnabled;
      else if (e.key === "f" || e.key === "F") this.g.frameEnabled = !this.g.frameEnabled;
    });
    this.boot();
  }

  private make(id: SceneId): Scene {
    switch (id) {
      case "title":
        return titleScene(this);
      case "starter":
        return starterScene(this);
      case "overworld":
        return overworldScene(this);
      case "pause":
        return pauseScene(this);
      case "plan":
        return routePlanScene(this);
      case "map":
        return routeMapScene(this);
      case "battle":
        return battleScene(this);
      case "party":
        return partyScene(this);
      case "summary":
        return summaryScene(this);
      case "bag":
        return bagScene(this);
      case "shop":
        return shopScene(this);
      case "clinic":
        return clinicScene(this);
      case "pc":
        return pcScene(this);
      case "index":
        return indexScene(this);
    }
  }

  private boot(): void {
    const shot = this.shot;
    if (!shot) {
      this.push("title");
      return;
    }
    const seed = this.state.seed;
    const rng = new Rng(hashSeed(`${seed}:shot`));
    if (shot === "title") {
      this.push("title");
      return;
    }
    if (shot === "continue") {
      if (!loadSave()) {
        const pocket = newGame("pond2", "shibonk", "Scout");
        pocket.money = 860;
        persist(pocket);
      }
      this.push("title");
      return;
    }
    if (shot === "starter") {
      this.push("starter");
      return;
    }
    this.state = newGame(seed, "shibonk", "Scout");
    this.state.money = 860;
    this.state.party.push(mintMon(rng, "whalord", 5));
    this.state.party.push(mintMon(rng, "rugfox", 4));
    this.state.party.push(mintMon(rng, "chopperdog", 6));
    this.state.seen = [...new Set([...this.state.seen, "laserpup", "whalord", "apeling", "chopperdog"])] as SaveState["seen"];
    this.state.caught = [...this.state.caught, "bogfiend", "wojakle", "chopperdog"];
    this.state.cosmetics.sticker = true;
    this.rng = rng;
    this.state.rng = rng.state;
    const fieldShots: Record<string, [number, number]> = {
      overworld: [15, 7], plaza: [9, 7], drippond: [26, 7], cliffs: [34, 9],
      chartwood: [13, 20], gulch: [26, 19], yard: [34, 23],
    };
    if (fieldShots[shot]) {
      [this.state.x, this.state.y] = fieldShots[shot]!;
      this.state.dir = 2;
      this.push("overworld");
      return;
    }
    if (shot === "shop") {
      this.state.x = 13;
      this.state.y = 6;
      this.push("overworld");
      this.push("shop");
      return;
    }
    if (shot === "party") {
      this.push("overworld");
      this.push("party");
      return;
    }
    if (shot === "summary") {
      this.push("overworld");
      this.push("party");
      this.push("summary", { partyIndex: 1 });
      return;
    }
    if (shot === "clinic") {
      this.state.party[1]!.hp = Math.max(1, Math.floor(this.state.party[1]!.hp * 0.4));
      this.push("overworld");
      this.push("clinic");
      return;
    }
    if (shot === "pc") {
      this.state.pc.push(mintMon(rng, "moonling", 5));
      this.push("overworld");
      this.push("pc");
      return;
    }
    if (shot === "circuit" || shot === "circuit-final" || shot === "circuit-rematch") {
      const level = shot === "circuit" ? 23 : 28;
      const crews: Record<string, SpeciesId[]> = {
        standard: ["bogbaron", "shibonkx", "laserhound", "wojaked"],
        wetland: ["diamondshell", "slippeel", "yieldyeti", "bogbaron"],
        canopy: ["cloutking", "airdropqueen", "apemajor", "fomobeast"],
        night: ["copiumax", "candlewyrm", "rugwolf", "moonlord"],
      };
      const crew = new URLSearchParams(window.location.search).get("crew") ?? "standard";
      this.state.party = (Object.hasOwn(crews, crew) ? crews[crew] : crews.standard)!.map(id => mintMon(rng, id, level));
      this.state.seen = this.state.party.map(mon => mon.speciesId);
      this.state.caught = [...this.state.seen];
      this.state.defeatedTrainers = shot === "circuit" ? ["vell"] : shot === "circuit-final"
        ? ["vell", "rook", "mica"] : ["vell", ...CIRCUIT_IDS];
      const rival = shot === "circuit-final" ? TRAINERS.nix : TRAINERS.rook;
      this.state.x = rival.x;
      this.state.y = rival.y - 1;
      this.state.dir = 1;
      this.push("overworld");
      return;
    }
    if (shot === "mender") {
      this.state.party = [mintMon(rng, "shibonk", 9), mintMon(rng, "bogfiend", 9), mintMon(rng, "wojakle", 9)];
      this.state.seen = this.state.party.map(mon => mon.speciesId);
      this.state.caught = [...this.state.seen];
      this.state.defeatedTrainers = ["tavi"];
      this.state.x = TRAINERS.pella.x;
      this.state.y = TRAINERS.pella.y - 1;
      this.state.dir = 1;
      this.push("overworld");
      return;
    }
    if (shot === "courier") {
      this.state.party = [mintMon(rng, "shibonk", 15), mintMon(rng, "bogfiend", 15),
        mintMon(rng, "laserpup", 15), mintMon(rng, "hopiumite", 15)];
      this.state.seen = this.state.party.map(mon => mon.speciesId);
      this.state.caught = [...this.state.seen];
      this.state.x = TRAINERS.ilex.x;
      this.state.y = TRAINERS.ilex.y - 1;
      this.state.dir = 1;
      this.push("overworld");
      return;
    }
    if (shot === "boss" || shot === "kits") {
      this.state.party = [mintMon(rng, "bogbaron", 22), mintMon(rng, "shibonkx", 22),
        mintMon(rng, "laserhound", 22), mintMon(rng, "wojaked", 22)];
      this.state.seen = this.state.party.map((mon) => mon.speciesId);
      this.state.caught = [...this.state.seen];
      this.state.x = TRAINERS.vell.x;
      this.state.y = TRAINERS.vell.y - 1;
      this.state.dir = 1;
      this.push("overworld");
      if (shot === "kits") this.push("battle", { wild: mintMon(rng, "moonlord", 22) });
      return;
    }
    if (shot === "batch-a" || shot === "evolve-a") {
      this.state.party = [mintMon(rng, "cloutling", 15), mintMon(rng, "hopiumite", 14),
        mintMon(rng, "chartgob", 15), mintMon(rng, "bagsnail", 14)];
      this.state.seen = this.state.party.map((mon) => mon.speciesId);
      this.state.caught = [...this.state.seen];
      const wild = mintMon(rng, "diamondshell", 17);
      if (shot === "evolve-a") {
        this.state.party[0]!.exp = expToNext(15) - 1;
        wild.hp = 1;
      }
      this.push("overworld");
      this.push("battle", { wild });
      return;
    }
    if (shot === "batch-b" || shot === "evolve-b" || shot === "trainer") {
      this.state.party = [mintMon(rng, "fomoling", 18), mintMon(rng, "gasgob", 14),
        mintMon(rng, "slippeel", 14), mintMon(rng, "mintmoth", 17)];
      this.state.seen = this.state.party.map((mon) => mon.speciesId);
      this.state.caught = [...this.state.seen];
      this.state.x = TRAINERS.sable.x;
      this.state.y = TRAINERS.sable.y - 1;
      this.state.dir = 1;
      this.push("overworld");
      if (shot === "trainer") return; // Approach, accept and play the actual route duel.
      const wild = mintMon(rng, "yieldyeti", 18);
      if (shot === "evolve-b") {
        this.state.party[0]!.exp = expToNext(18) - 1;
        wild.hp = 1;
      }
      this.push("battle", { wild });
      return;
    }
    if (shot === "battle" || shot === "catch" || shot === "moves" || shot === "evolve") {
      const wild =
        shot === "catch"
          ? mintMon(rng, "moonling", 6)
          : shot === "moves"
            ? mintMon(rng, "rugfox", 6)
            : mintMon(rng, "gigachomp", 6);
      if (shot === "evolve") {
        const lead = mintMon(rng, "shibonk", 15);
        lead.exp = expToNext(15) - 1;
        this.state.party[0] = lead;
        wild.hp = 1;
      }
      if (shot === "catch") wild.hp = Math.max(1, Math.floor(wild.hp * 0.25));
      this.push("overworld");
      this.push("battle", { wild });
      return;
    }
    this.push("title");
  }

  push(id: SceneId, payload?: ScenePayload): void {
    this.input.reset();
    const scene = this.make(id);
    this.stack.push(scene);
    scene.enter(payload);
  }

  replace(id: SceneId, payload?: ScenePayload): void {
    const top = this.stack.pop();
    top?.exit();
    if (id === "title") {
      while (this.stack.length) this.stack.pop()!.exit();
    }
    this.push(id, payload);
  }

  pop(): void {
    this.input.reset();
    const top = this.stack.pop();
    top?.exit();
    if (!this.stack.length) this.push("title");
  }

  save(): void {
    this.state.rng = this.rng.state;
    persist(this.state);
  }

  persistRng(): void {
    this.state.rng = this.rng.state;
  }

  start(): void {
    (window as unknown as { memecraft?: Game }).memecraft = this;
    this.last = performance.now();
    const loop = (t: number) => {
      this.dt = Math.min(40, t - this.last);
      this.last = t;
      this.now = t;
      this.state.playMs += this.dt;
      this.stack[this.stack.length - 1]?.update();
      const top = this.stack[this.stack.length - 1];
      const owTop = top?.id === "overworld";
      const wideOw = owTop && window.innerWidth >= OW_W + 48;
      this.g.beginFrame(wideOw);
      this.g.clear();
      const base = this.stack.find((s) => s.id === "overworld" || s.id === "title" || s.id === "starter");
      if (base && base !== top && (top?.id === "pause" || top?.id === "clinic" || top?.id === "shop" || top?.id === "pc")) {
        this.g.beginFrame(false);
        this.g.wideOw = false;
        this.g.clear();
        base.draw();
      }
      top?.draw();
      this.g.postScene = owTop;
      this.g.present();
      this.input.endFrame();
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }
}
