import { MAP, MAP_H, MAP_W, TILES, type TileId } from "../../data/map.ts";
import { brickTexel, cobbleTexel, grain, grassTexel, plankTexel, roofTexel, sandTexel, tallGrassTexel, waterTexel } from "./materials.ts";
import { P, type Rgb } from "./palette.ts";
import { Pix } from "./pix.ts";
import { hs, thash } from "./seed.ts";

/**
 * Stubtown tile painters — port of art/hd2d/render_styles.py.
 * Masonry / furrow / cobble patterns are keyed on GLOBAL pixel coords (gx, gy)
 * so mortar, plank, and furrow lines stay continuous across tile seams.
 */

const T = 16;
const cache = new Map<string, ImageData>();

export function isWaterId(id: TileId): boolean {
  return id === "water" || id === "foam" || id === "reed";
}

export function isPathId(id: TileId): boolean {
  return id === "path";
}

export function isGrassId(id: TileId): boolean {
  return id === "grass" || id === "tall";
}

/** Collision solids that read as built mass (walls, crates, props). Water is solid for gameplay but not here. */
export function isArtSolid(id: TileId): boolean {
  return (
    id === "wall" ||
    id === "roof" ||
    id === "wood" ||
    id === "door" ||
    id === "crate" ||
    id === "barrel" ||
    id === "lamp" ||
    id === "rock" ||
    id === "tree" ||
    id === "fence" ||
    id === "post" ||
    id === "counter" ||
    id === "void"
  );
}

/** Solids whose base darkens the ground below (AO band). Wall-mounted props excluded. */
export function castsAo(id: TileId): boolean {
  return (
    id === "wall" ||
    id === "roof" ||
    id === "wood" ||
    id === "door" ||
    id === "crate" ||
    id === "barrel" ||
    id === "post" ||
    id === "counter" ||
    id === "tree" ||
    id === "void"
  );
}

export function isGroundId(id: TileId): boolean {
  return !isArtSolid(id) && TILES[id] !== undefined;
}

export function mapId(tx: number, ty: number): TileId {
  if (ty < 0 || tx < 0 || ty >= MAP_H || tx >= MAP_W) return "void";
  return MAP[ty]![tx]!;
}

// ---------------------------------------------------------------------------
// ground
// ---------------------------------------------------------------------------

function paintSurface(b: Pix, tx: number, ty: number, sample: (x: number, y: number) => Rgb): void {
  for (let y = 0; y < T; y++) for (let x = 0; x < T; x++) b.p(x, y, sample(tx * T + x, ty * T + y));
}

function paintGrass(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, grassTexel);
}

function paintGrassRows(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, tallGrassTexel);
}

const BED_PETALS: readonly Rgb[] = [P.FLOWER_PET, P.FLOWER_PET, P.SC_HAIR, P.SAND_LT, P.LANT_GOLD];

/** Dense planted bed: dark leafy ground, five mixed-colour blooms with stems, leaves and buds. */
function paintFlowerbed(b: Pix, tx: number, ty: number): void {
  for (let y = 0; y < T; y++) for (let x = 0; x < T; x++) {
    const h = grain(tx * T + x, ty * T + y, 3);
    let col: Rgb = P.BED_GREEN;
    if (h % 5 === 0) col = P.BED_STEM;
    else if (h % 7 === 0) col = P.GRASS_DK;
    else if (h % 17 === 0) col = P.GRASS_LT;
    b.p(x, y, col);
  }
  const h = thash(tx, ty, 3);
  for (let i = 0; i < 4; i++) b.hline(hs(h, i * 3, 15), hs(h, i * 3 + 5, 16), 2, P.GRASS_LT);
  const spots: readonly [number, number][] = [[3, 5], [10, 4], [6, 11], [12, 12], [8, 8]];
  spots.forEach(([sx, sy], i) => {
    const fx = sx + hs(h, i * 5, 3) - 1;
    const fy = sy + hs(h, i * 5 + 2, 3) - 1;
    const petal = BED_PETALS[hs(h, i * 4 + 1, BED_PETALS.length)]!;
    b.vline(fx, fy + 1, 3, P.BED_STEM);
    b.p(fx + 1, fy + 2, P.GRASS_LT);
    b.p(fx, fy - 1, petal); b.p(fx - 1, fy, petal); b.p(fx + 1, fy, petal); b.p(fx, fy + 1, petal);
    b.p(fx, fy, P.FLOWER_CORE);
    if (petal === P.FLOWER_PET) b.p(fx - 1, fy - 1, P.SC_HAIR);
  });
  for (let i = 0; i < 3; i++) {
    const bx = hs(h, i * 6 + 9, 16), by = hs(h, i * 6 + 13, 16);
    b.p(bx, by, P.FLOWER_PET); b.p(bx, by + 1, P.BED_STEM);
  }
}

function paintSand(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, sandTexel);
}

function paintPath(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, cobbleTexel);
  // Worn verge stays inside the existing path footprint.
  for (let i = 0; i < T; i++) {
    if (!isPathId(mapId(tx, ty - 1))) b.p(i, 0, i % 5 ? P.PATH_MORTAR : P.PATH_DOT);
    if (!isPathId(mapId(tx, ty + 1))) b.p(i, T - 1, i % 7 ? P.PATH_DOT : P.SAND);
    if (!isPathId(mapId(tx - 1, ty))) b.p(0, i, i % 5 ? P.PATH_MORTAR : P.PATH_DOT);
    if (!isPathId(mapId(tx + 1, ty))) b.p(T - 1, i, i % 7 ? P.PATH_DOT : P.SAND);
  }
}

function paintWater(b: Pix, tx: number, ty: number, reeds: boolean, phase: number): void {
  paintSurface(b, tx, ty, (x, y) => waterTexel(x, y, phase));
  const north = !isWaterId(mapId(tx, ty - 1)), south = !isWaterId(mapId(tx, ty + 1));
  const west = !isWaterId(mapId(tx - 1, ty)), east = !isWaterId(mapId(tx + 1, ty));
  // Shoreline as drawn structure, never painted onto a walkable neighbour: a wet bank shadow
  // under the north/west banks, a broken white foam line, pale shallows, then sparse wash.
  for (let y = 0; y < T; y++) for (let x = 0; x < T; x++) {
    const dn = north ? y : T, ds = south ? T - 1 - y : T, dw = west ? x : T, de = east ? T - 1 - x : T;
    const d = Math.min(dn, ds, dw, de);
    if (d > 3) continue;
    const gx = tx * T + x, gy = ty * T + y;
    const along = d === dn || d === ds ? gx : gy;
    const wave = grain(Math.floor(along / 5), 0, 26);
    const shaded = d === dn || d === dw;
    if (d === 0) b.p(x, y, shaded ? P.WATER_DEEP : (along + wave) % 6 < 4 ? P.WATER_EDGE : P.WIN_GLINT);
    else if (d === 1) {
      if ((along * 7 + wave + phase * 5) % 29 === 0) b.p(x, y, P.SC_HAIR_HI);
      else if ((along + wave) % 7 < 3) b.p(x, y, P.WIN_GLINT);
      else if ((along + wave + phase) % 11 === 0) b.p(x, y, P.HUD_PANEL);
      else b.p(x, y, P.WATER_EDGE);
    } else if (d === 2) {
      if ((along + wave) % 5 < 3) b.p(x, y, P.WATER_EDGE);
      else if ((along + phase) % 7 === 0) b.p(x, y, P.WATER_DASH);
    } else if ((along + phase) % 13 < 4) b.p(x, y, P.WATER_DASH);
  }
  if (reeds) {
    const h = grain(tx, ty, 6);
    for (let i = 0; i < 3; i++) {
      const x = 3 + i * 5, hgt = 7 + hs(h, i * 4, 5);
      b.hline(x - 2, 14, 5, P.WATER_DEEP);
      b.vline(x, T - hgt, hgt - 1, P.BED_STEM);
      b.vline(x + 1, T - hgt + 2, hgt - 5, P.ROWG_HI);
      b.p(x - 1, T - hgt, P.PLANK); b.p(x - 1, T - hgt + 1, P.PLANK_HI);
      b.p(x - 1, 11, P.ROWG_BASE); b.p(x - 2, 10, P.ROWG_HI);
    }
  }
}

// ---------------------------------------------------------------------------
// building
// ---------------------------------------------------------------------------

function paintBrick(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, brickTexel);
}

function paintPlank(b: Pix, tx: number, ty: number): void {
  paintSurface(b, tx, ty, plankTexel);
}

function paintDoor(b: Pix, half: 0 | 1): void {
  for (let y = 0; y < T; y++) {
    for (let x = 0; x < T; x++) {
      let col = P.DOOR;
      if (x % 5 === 4) col = P.DOOR_DK;
      if (y < 2) col = P.DOOR_DK;
      b.p(x, y, col);
    }
  }
  b.vline(0, 0, T, P.DOOR_DK);
  b.vline(T - 1, 0, T, P.DOOR_DK);
  b.p(half === 0 ? 11 : 4, 9, P.SIGN_GOLD);
}

export function paintCrate(b: Pix, faceVariant: boolean): void {
  for (let y = 0; y < T; y++) {
    for (let x = 0; x < T; x++) {
      let col = P.CRATE_FACE;
      if (x === 0 || x === T - 1 || y === 0 || y === T - 1) col = P.CRATE_DK;
      else if (x === 1 || x === T - 2 || y === 1 || y === T - 2) col = P.CRATE_FRAME;
      b.p(x, y, col);
    }
  }
  // Grain sits behind the recognisable face/frame; tiny end-grain rings stay inside.
  for (let y = 3; y < 13; y++) for (let x = 3; x < 13; x++) {
    if (x === 7) b.p(x, y, P.PLANK);
    if ((x === 4 || x === 11) && y % 5 < 3) b.p(x, y, P.PLANK_HI);
  }
  b.p(4, 2, P.SAND_LT); b.p(11, 2, P.SAND_LT);
  b.hline(2, 1, 12, P.PLANK_HI);
  b.hline(3, 13, 10, P.PLANK);
  b.p(10, 10, P.PLANK); b.p(9, 11, P.PLANK); b.p(11, 11, P.PLANK);
  b.p(10, 12, P.PLANK); b.p(10, 11, P.CRATE_FRAME);
  if (faceVariant) {
    // generic smiley meme-crate (no cloned meme)
    for (const X of [5, 10]) {
      b.p(X, 5, P.CRATE_DK);
      b.p(X, 6, P.CRATE_DK);
    }
    b.hline(6, 10, 4, P.CRATE_DK);
    b.p(5, 9, P.CRATE_DK);
    b.p(10, 9, P.CRATE_DK);
    return;
  }
  for (const sx of [3, 10]) {
    b.hline(sx, 3, 3, P.CRATE_DK);
    b.hline(sx, 4, 3, P.CRATE_DK);
  }
  b.hline(2, 8, T - 4, P.CRATE_FRAME);
}

function paintFence(b: Pix, tx: number, ty: number): void {
  paintSand(b, tx, ty);
  for (const yy of [4, 10]) {
    b.hline(0, yy, T, P.DOOR_DK);
    b.hline(0, yy + 1, T, P.DOOR);
    b.hline(0, yy + 2, T, P.DOOR_DK);
    for (let x = 0; x < T; x++) {
      if (grain(Math.floor((tx * T + x) / 3), ty * T + yy, 44) % 3 === 0) b.p(x, yy, P.PLANK_HI);
      if ((tx * T + x + yy) % 9 === 0) b.p(x, yy + 1, P.CRATE_FRAME);
    }
  }
  for (const xx of [2, 13]) {
    b.vline(xx, 2, 13, P.DOOR_DK);
    b.vline(xx + 1, 2, 13, P.DOOR);
    b.p(xx, 2, P.CRATE_FACE); b.p(xx + 1, 3, P.PLANK_HI);
    b.p(xx + 1, 7, P.PLANK_HI); b.p(xx + 1, 8, P.CRATE_FRAME);
    b.p(xx, 5, P.ROCK_SPECK); b.p(xx, 11, P.ROCK_SPECK);
  }
}

/** Route landmarks stay at native tile scale, with collision matching the visible mass. */
function paintRest(b: Pix, tx: number, ty: number): void {
  paintPath(b, tx, ty);
  b.fill(1, 2, 14, 13, P.ROCK_DK); b.fill(2, 3, 12, 10, P.ROCK_SLAB);
  b.hline(2, 3, 12, P.PATH_HI); b.hline(2, 13, 12, P.WATER_EDGE);
  b.fill(5, 6, 6, 5, P.LANT_FRAME); b.fill(6, 6, 4, 4, P.LANT_GOLD);
  b.fill(11, 6, 2, 3, P.LANT_FRAME); b.p(11, 7, P.ROCK_SLAB);
  b.hline(4, 11, 9, P.PLANK); b.hline(5, 12, 7, P.PLANK_HI);
  b.p(6, 4, P.HUD_PANEL); b.p(8, 2, P.HUD_PANEL); b.p(9, 4, P.HUD_PANEL);
}

/** Drawn contact shadow on lawn: a short dark run to the lower-right of a landmark's footing. */
function groundShade(b: Pix, x: number, y: number, w: number): void {
  b.hline(x, y, w, P.GRASS_DK);
  b.hline(x + 1, y + 1, Math.max(1, w - 2), P.BED_GREEN);
}

function paintRouteSign(b: Pix, tx: number, ty: number): void {
  paintGrass(b, tx, ty);
  groundShade(b, 8, 14, 5);
  // Post: lit left grain, dark right side, footing.
  b.fill(7, 6, 3, 10, P.TRUNK_DK); b.vline(7, 7, 8, P.PLANK); b.vline(8, 10, 5, P.TRUNK);
  b.p(7, 8, P.PLANK_HI); b.p(7, 12, P.PLANK_HI); b.hline(6, 15, 4, P.TRUNK_DK);
  // Board with a lit top rim, timber frame, gold nails, shadow line beneath and the route arrow.
  b.fill(1, 2, 14, 8, P.SIGN_BG); b.hline(1, 2, 14, P.PLANK_HI);
  b.vline(1, 3, 6, P.PLANK); b.vline(14, 3, 6, P.PLANK_SEAM); b.hline(1, 9, 14, P.DOOR_DK);
  b.p(2, 3, P.SIGN_GOLD); b.p(13, 3, P.SIGN_GOLD); b.p(2, 8, P.LANT_FRAME); b.p(13, 8, P.LANT_FRAME);
  b.hline(2, 10, 12, P.GRASS_DK);
  b.hline(3, 6, 9, P.SIGN_GOLD); b.p(10, 4, P.SIGN_GOLD);
  b.p(11, 5, P.SIGN_GOLD); b.p(11, 7, P.SIGN_GOLD); b.p(10, 8, P.SIGN_GOLD);
  b.p(4, 5, P.LANT_GLOW);
}

function paintRouteRock(b: Pix, tx: number, ty: number): void {
  paintGrass(b, tx, ty);
  const h = thash(tx, ty, 86);
  groundShade(b, 4, 14, 11);
  b.oval(8, 10, 8, 6, P.ROCK_DK); b.oval(7, 7, 7, 6, P.ROCK_MID);
  b.oval(6, 5, 5, 3, P.ROCK_HI); b.hline(4, 3, 5, P.ROCK_SLAB);
  // Rim light along the upper-left silhouette, facet crease, lichen on the shaded flank.
  b.p(2, 5, P.ROCK_SLAB); b.p(1, 7, P.ROCK_HI); b.p(3, 4, P.ROCK_SLAB); b.p(6, 2, P.ROCK_SLAB);
  b.hline(5, 11, 7, P.ROCK_DK); b.p(3 + h % 6, 6, P.ROCK_SPECK);
  b.hline(4, 4, 4, P.ROCK_SLAB); b.hline(10, 7, 3, P.ROCK_DK);
  b.p(9, 6, P.ROCK_DK); b.p(8, 5, P.ROCK_SPECK);
  b.hline(4, 9, 4, P.ROCK_SPECK); b.p(3, 8, P.ROCK_HI);
  b.p(6, 6, P.ROCK_SLAB); b.p(11, 11, P.ROCK_MID);
  b.p(9, 9, P.ROCK_DK); b.p(10, 10, P.ROCK_DK); b.p(13, 9, P.ROCK_DK);
  b.p(11, 12, P.BED_GREEN); b.p(12, 12, P.GRASS_DK); b.p(4 + h % 3, 12, P.BED_GREEN);
  if (tx >= 33 && ty < 14) {
    // Chalk ribbons and wind-carved seams distinguish Cope Cliffs in the native stone ramp.
    b.hline(3, 5, 8, P.ROCK_SLAB); b.hline(4, 6, 6, P.ROCK_HI);
    b.hline(2, 9, 11, P.ROCK_DK); b.hline(4, 10, 8, P.ROCK_SLAB);
    b.p(10, 4, P.ROCK_MID); b.p(11, 5, P.ROCK_MID); b.p(12, 9, P.ROCK_HI);
    if(h % 2 === 0) { b.p(6, 7, P.ROCK_DK); b.p(7, 8, P.ROCK_DK); }
  }
  if (tx >= 17 && tx < 30 && ty >= 14) {
    b.hline(6, 8, 5, P.ROCK_DK); b.p(7, 8, P.PLANK_HI); b.p(10, 9, P.LANT_GOLD);
  }
}

function paintRouteTree(b: Pix, tx: number, ty: number): void {
  paintGrass(b, tx, ty);
  const h = thash(tx, ty, 88);
  groundShade(b, 8, 15, 6);
  // Trunk with a lit grain edge, dark far side and a root flare.
  b.fill(7, 10, 3, 6, P.TRUNK_DK); b.vline(7, 10, 5, P.TRUNK); b.p(7, 11, P.PLANK);
  b.hline(6, 15, 5, P.TRUNK_DK); b.p(5, 15, P.TRUNK);
  // Lobed canopy: dark underside, lit rim toward the upper-left, dappled clusters.
  b.oval(8, 7, 7, 6, P.TREE_DARK); b.oval(4, 8, 3, 3, P.TREE_DARK); b.oval(12, 8, 3, 3, P.TREE_DARK);
  b.oval(7, 6, 6, 5, P.TREE_BODY); b.oval(4, 8, 2, 2, P.TREE_BODY); b.oval(12, 8, 2, 2, P.TREE_BODY);
  b.oval(5, 4, 3, 2, P.TREE_HI); b.hline(4, 2, 4, P.TREE_HI); b.p(3, 3, P.TREE_LT); b.p(2, 5, P.TREE_LT);
  b.p(4, 3, P.TREE_LT); b.p(6, 3, P.TREE_LT); b.p(8, 4, P.TREE_HI); b.p(3, 7, P.TREE_HI);
  b.hline(9, 5, 2, P.TREE_HI); b.p(10, 6, P.TREE_HI); b.p(6, 8, P.TREE_HI);
  b.p(10, 9, P.TREE_DARK); b.p(11, 10, P.TREE_DARK); b.p(9, 10, P.TREE_DARK); b.p(12, 8, P.TREE_DARK);
  b.p(8, 9, P.TREE_DARK); b.p(13, 7, P.TREE_DARK);
  if (h % 2 === 0) { b.p(11, 5, P.TREE_LT); b.p(7, 2, P.TREE_LT); }
  if ((tx + ty) % 3 === 0) { b.p(5, 9, P.SIGN_GOLD); b.p(11, 8, P.PLANK_HI); }
}

/** 16×16 gold lantern emblem, transparent outside — blit over a plank wall. */
export function paintLanternEmblem(b: Pix): void {
  b.fill(3, 2, 10, 12, P.LANT_FRAME);
  b.fill(4, 3, 8, 10, P.LANT_GOLD);
  b.fill(6, 5, 4, 6, P.LANT_GLOW);
  b.fill(7, 6, 2, 3, P.HUD_PANEL);
  b.vline(4, 4, 7, P.LAMP_HEAD);
  b.hline(5, 12, 6, P.LAMP_PANEL);
  b.p(5, 3, P.LANT_GLOW); b.p(10, 3, P.LANT_GLOW);
  b.p(5, 14, P.PLANK_HI); b.p(10, 14, P.PLANK_HI);
  b.hline(6, 1, 4, P.LANT_FRAME);
}

// ---------------------------------------------------------------------------
// dispatch
// ---------------------------------------------------------------------------

function paintKind(b: Pix, id: TileId, tx: number, ty: number, phase: number): void {
  switch (id) {
    case "path":
      paintPath(b, tx, ty);
      return;
    case "rest":
      paintRest(b, tx, ty);
      return;
    case "tree":
      paintRouteTree(b, tx, ty);
      return;
    case "rock":
      paintRouteRock(b, tx, ty);
      return;
    case "grass":
      paintGrass(b, tx, ty);
      return;
    case "tall":
      paintGrassRows(b, tx, ty);
      return;
    case "flower":
      paintFlowerbed(b, tx, ty);
      return;
    case "water":
    case "foam":
      paintWater(b, tx, ty, false, phase);
      return;
    case "reed":
      paintWater(b, tx, ty, true, phase);
      return;
    case "wall":
      if (tx >= 23 || ty >= 13) {
        paintRouteRock(b, tx, ty);
        return;
      }
      paintBrick(b, tx, ty);
      return;
    case "roof":
      paintSurface(b, tx, ty, roofTexel);
      return;
    case "void":
      paintBrick(b, tx, ty);
      return;
    case "wood":
      paintPlank(b, tx, ty);
      return;
    case "door":
      paintDoor(b, mapId(tx - 1, ty) === "door" ? 1 : 0);
      return;
    case "crate":
    case "barrel":
    case "counter":
      paintCrate(b, false);
      return;
    case "post":
      if (tx >= 16 || ty >= 14) paintRouteSign(b, tx, ty);
      else paintCrate(b, true);
      return;
    case "fence":
      paintFence(b, tx, ty);
      return;
    default:
      // floor and lamp (2×2 props overlay the ground)
      paintSand(b, tx, ty);
  }
}

export function hd2dTile(id: TileId, tx: number, ty: number, waterPhase = 0): ImageData {
  const phase = isWaterId(id) ? ((waterPhase % 4) + 4) % 4 : 0;
  const key = `grok-look:${phase}:${id}:${tx}:${ty}:${mapId(tx, ty - 1)}:${mapId(tx, ty + 1)}:${mapId(tx + 1, ty)}:${mapId(tx - 1, ty)}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const b = new Pix(T, T);
  paintKind(b, id, tx, ty, phase);
  const img = b.toImage();
  cache.set(key, img);
  return img;
}

let lanternImg: ImageData | null = null;
export function hd2dLantern(): ImageData {
  if (lanternImg) return lanternImg;
  const b = new Pix(T, T);
  paintLanternEmblem(b);
  lanternImg = b.toImage();
  return lanternImg;
}
