import { speciesById } from "../data/species.ts";
import { TYPE_META, bestTypesAgainst } from "../data/types.ts";
import { C, type Gfx, type Rgba } from "../engine/gfx.ts";
import type { BattleMon } from "../game/combat.ts";
import { maxHp } from "../game/mon.ts";
import { P, rgba } from "./hd2d/palette.ts";
import { Pix } from "./hd2d/pix.ts";
import { applyHd2dPost } from "./hd2d/post.ts";
import { hd2dProp } from "./hd2d/props.ts";
import { thash } from "./hd2d/seed.ts";
import { brickTexel, grain, plankTexel, stoneTexel, waterTexel } from "./hd2d/materials.ts";

// Battle-local platinum chrome; the shared menus and overworld keep their styling.
export const B = {
  paper: rgba(P.HUD_PANEL), shade: rgba(P.HUD_SHADE), rim: rgba(P.WIN_PANE),
  light: rgba(P.WIN_GLINT), ink: rgba(P.HUD_INK), muted: C.slate,
  accent: C.waterHi, gold: rgba(P.COIN),
};

let rawStage: ImageData | undefined;
/** Posted stage per look; the frame stays off so the arena keeps its denser LCD read. */
const postStages = new Map<string, ImageData>();

/** A pocket-sized Stubtown plaza, using the same painters, palette and post as the street. */
function stage(): ImageData {
  if (rawStage) return rawStage;
  const b = new Pix(240, 160);
  b.fill(0, 0, 240, 160, P.PATH_MID);
  b.fill(0, 0, 240, 28, P.TREE_DARK);
  // Far canopy, brick shop and its recessed window. All noise is coordinate seeded.
  for (let i = 0; i < 30; i++) {
    const h = thash(i, 4, 71);
    b.oval(i * 9 - 6, 4 + h % 13, 10, 9, i % 3 ? P.TREE_BODY : P.TREE_HI);
  }
  b.fill(0, 0, 80, 39, P.BRICK_DK);
  for (let y = 0; y < 35; y++) for (let x = 0; x < 76; x++) b.p(x, y, brickTexel(x, y));
  b.fill(10, 2, 21, 22, P.WIN_FRAME);
  b.fill(12, 3, 17, 18, P.WIN_DK);
  b.fill(14, 4, 5, 14, P.WIN_PANE);
  b.fill(22, 4, 5, 14, P.WIN_PANE);
  b.hline(15, 5, 3, P.WIN_GLINT); b.hline(23, 5, 3, P.WIN_GLINT);
  b.hline(11, 22, 21, P.PLANK_HI);
  for (let y = 29; y < 33; y++) for (let x = 0; x < 80; x++) b.p(x, y, plankTexel(x, y));
  // Canal, masonry lip and staggered reflections behind the far fighter.
  b.fill(80, 19, 160, 15, P.WATER_DEEP);
  for (let y = 20; y < 31; y++) for (let x = 80; x < 240; x++) b.p(x, y, waterTexel(x, y));
  for (let x = 80; x < 240; x++) {
    b.p(x, 30, x % 11 < 5 ? P.WATER_EDGE : P.WATER_DEEP);
    if (x % 17 < 3) b.p(x, 31, P.WIN_GLINT);
  }
  b.fill(77, 33, 163, 5, P.ROCK_DK);
  b.fill(77, 32, 163, 3, P.ROCK_SLAB);
  b.hline(77, 32, 163, P.PATH_HI);
  for (let x = 78; x < 240; x += 13) b.vline(x, 33, 3, P.ROCK_MID);
  // Perspective cobbles: rows deepen and stones widen toward the foreground.
  let row = 0;
  for (let y = 38; y < 112; row++) {
    const h = 4 + Math.floor(row / 2);
    const w = 11 + row * 2;
    for (let x = -(row % 2) * (w >> 1); x < 240; x += w) {
      const seed = grain(x, y, 11);
      for (let yy = 0; yy < h; yy++) for (let xx = 0; xx < w; xx++) b.p(x + xx, y + yy, stoneTexel(xx, yy, w, h, seed));
    }
    y += h;
  }
  // Flower beds break the hard plaza edge, leaving a clear diagonal attack lane.
  for (const [x, y, w] of [[0, 44, 14], [210, 39, 30], [0, 99, 96]]) {
    b.fill(x, y, w, 10, P.ROCK_DK);
    b.fill(x, y - 1, w, 8, P.BED_GREEN);
    for (let yy = y; yy < y + 6; yy++) for (let xx = x; xx < x + w; xx++) {
      if (grain(xx, yy, 3) % 7 === 0) b.p(xx, yy, P.BED_STEM);
      if (grain(xx, yy, 9) % 11 === 0) b.p(xx, yy, P.GRASS_LT);
    }
    b.hline(x, y + 7, w, P.ROCK_SLAB);
    for (let xx = x + 3; xx < x + w; xx += 6) {
      b.vline(xx, y, 5, P.BED_STEM);
      b.hline(xx - 1, y, 3, P.FLOWER_PET);
      b.p(xx, y - 1, P.FLOWER_PET);
      b.p(xx, y, P.FLOWER_CORE);
      b.p(xx - 1, y - 1, P.SC_HAIR); b.p(xx + 1, y + 3, P.ROWG_HI);
    }
  }
  // Inlaid stone duelling circles, with an offset ambient shadow under each shelf.
  for (const [x, y, rx, ry] of [[164, 43, 31, 8], [33, 91, 34, 10]]) {
    b.oval(x + 3, y + 4, rx + 3, ry, P.SAND_DK);
    b.oval(x, y + 2, rx, ry, P.ROCK_DK);
    b.oval(x, y, rx, ry, P.ROCK_SLAB);
    b.oval(x, y - 1, rx - 2, ry - 2, P.PATH_HI);
    b.oval(x, y - 1, rx - 4, ry - 3, P.PATH_MORTAR);
    b.oval(x, y - 1, rx - 5, ry - 4, P.PATH_MID);
    // Cut-stone segments, shallow pits and radial joints respect the oval silhouette.
    for (let yy = -ry; yy <= ry; yy++) for (let xx = -rx; xx <= rx; xx++) {
      const inner = xx * xx / ((rx - 5) ** 2) + (yy + 1) ** 2 / ((ry - 4) ** 2);
      if (inner <= 1) b.p(x + xx, y + yy, stoneTexel((xx + rx) % 15, (yy + ry) % 7, 15, 7, grain(Math.floor((xx + rx) / 15), y, 81)));
      const ring = xx * xx / (rx * rx) + yy * yy / (ry * ry);
      if (ring < 0.95 && ring > 0.73 && (xx + rx) % 13 === 0) b.p(x + xx, y + yy, P.ROCK_SPECK);
    }
    b.hline(x - rx + 9, y + ry - 2, rx * 2 - 18, P.SAND_LT);
  }
  // Reuse the street's tree and lantern sprites without involving the map or its tiles.
  const stamp = (img: ImageData, x: number, y: number) => {
    for (let yy = 0; yy < img.height; yy++) for (let xx = 0; xx < img.width; xx++) {
      const o = (yy * img.width + xx) * 4;
      if (img.data[o + 3]) b.p(x + xx, y + yy, [img.data[o]!, img.data[o + 1]!, img.data[o + 2]!]);
    }
  };
  stamp(hd2dProp("tree", 0, 0), 218, -8);
  stamp(hd2dProp("lamp", 0, 0), 190, 3);
  rawStage = b.toImage();
  return rawStage;
}

export function battleStage(g: Gfx): void {
  const raw = stage();
  if (!g.postEnabled) {
    g.blit(raw, 0, 0);
    return;
  }
  let posted = postStages.get(g.look.name);
  if (!posted) {
    posted = new ImageData(240, 160);
    posted.data.set(raw.data);
    // Cached at native battle resolution: the canvas and every UI glyph stay 240×160.
    applyHd2dPost(posted.data, 240, 160, { look: g.look, frame: false });
    postStages.set(g.look.name, posted);
  }
  g.blit(posted, 0, 0);
}

export function battlePanel(g: Gfx, x: number, y: number, w: number, h: number): void {
  g.fill(x + 1, y + 2, w, h, C.shadow);
  g.fill(x, y, w, h, B.paper);
  g.rect(x, y, w, h, B.ink);
  g.hline(x + 1, y + 1, w - 2, B.light);
  g.fill(x + w - 2, y + 2, 1, h - 3, B.rim);
  g.hline(x + 1, y + h - 2, w - 2, B.shade);
}

export function battlePlate(g: Gfx, b: BattleMon, own: boolean, rival: boolean | "BOSS" = false): void {
  const x = own ? 117 : 4, y = own ? 72 : 4, w = 119;
  const sp = speciesById(b.mon.speciesId);
  const type = TYPE_META[sp.types[0]!];
  battlePanel(g, x, y, w, 32);
  g.fill(x + 1, y + 2, 2, 27, type.ink);
  g.text(x + 6, y + 4, b.mon.nick.slice(0, 12), B.ink);
  const level = `Lv${b.mon.level}`;
  g.text(x + w - 5 - level.length * 6, y + 4, level, B.muted);
  g.text(x + 6, y + 15, "HP", B.muted);
  const width = 91;
  const hp = maxHp(b.mon);
  const ratio = b.shownHp / hp;
  const live = Math.round((width - 2) * Math.max(0, b.mon.hp / hp));
  const shown = Math.round((width - 2) * Math.max(0, ratio));
  g.fill(x + 21, y + 14, width, 6, B.ink);
  g.fill(x + 22, y + 15, width - 2, 4, B.shade);
  g.fill(x + 22, y + 15, Math.max(live, shown), 4, B.gold);
  g.fill(x + 22, y + 15, Math.min(live, shown), 4, g.hpColor(ratio));
  g.hline(x + 22, y + 15, Math.min(live, shown), C.mossHi);
  for (let n = 1; n < 5; n++) g.fill(x + 22 + Math.round(n * (width - 2) / 5), y + 15, 1, 4, [24, 28, 32, 65]);
  if (own) g.text(x + 6, y + 23, b.faint === 1 ? "OUT" : `${Math.ceil(b.shownHp)}/${hp}`, B.ink);
  else g.text(x + 6, y + 23, b.faint === 1 ? "OUT" : rival === "BOSS" ? "BOSS" : rival ? "RIVAL" : "WILD", B.muted);
  const chips = sp.types.map((t) => TYPE_META[t].chip).join("/");
  g.text(x + w - 6 - chips.length * 6, y + 23, chips, B.muted);
}

export function battleMessage(g: Gfx, text: string, more: boolean, label = "BATTLE LOG"): void {
  battlePanel(g, 4, 110, 232, 46);
  g.fill(5, 111, 230, 10, B.shade);
  g.text(10, 113, label, B.muted);
  g.lines(10, 125, text, 36, B.ink);
  if (more) g.text(220, 145, ">", B.accent);
}

/** Free field notes use the battle's existing pixel typography and chrome. */
export function battleTactics(g: Gfx, you: BattleMon, foe: BattleMon, actionHint: string | null = null): void {
  const sp = speciesById(foe.mon.speciesId);
  const hint = bestTypesAgainst(sp.types);
  const steps = (b: BattleMon) => (["atk", "def", "spd"] as const)
    .map(stat => `${stat.toUpperCase()} ${b[stat] > 0 ? "+" : ""}${b[stat]}`).join("  ");
  battlePanel(g, 4, 4, 232, 152);
  g.fill(5, 5, 230, 14, B.shade);
  g.text(10, 8, "TACTICS", B.ink);
  g.text(178, 8, "A/B back", B.muted);
  g.text(10, 26, `FOE  ${foe.mon.nick}`, B.ink);
  g.text(10, 38, sp.types.map(type => TYPE_META[type].name).join(" / "), B.muted);
  g.text(10, 50, steps(foe), B.ink);
  g.text(10, 62, hint.multiplier > 1
    ? `Try ${hint.types.map(type => TYPE_META[type].chip).join("/")} x${hint.multiplier}`
    : "No type has an extra bite here.", B.accent);
  g.hline(10, 76, 220, B.shade);
  g.text(10, 84, `YOU  ${you.mon.nick}`, B.ink);
  g.text(10, 96, steps(you), B.ink);
  g.text(10, 110, "Switch clears steps; costs a turn.", B.muted);
  g.fill(5, 123, 230, 32, B.shade);
  g.text(10, 128, actionHint ?? "ATK power / DEF guard / SPD speed", B.ink);
  g.text(10, 142, "Reading tactics costs no turn.", B.muted);
}

/** Four visible rows, including scrolling pack/crew entries. */
export function battleList(g: Gfx, items: string[], index: number): void {
  battlePanel(g, 4, 110, 232, 46);
  const first = Math.max(0, index - 3);
  items.slice(first, first + 4).forEach((label, row) => {
    const y = 114 + row * 10;
    if (row + first === index) {
      g.fill(7, y - 1, 220, 9, B.shade);
      g.fill(7, y - 1, 2, 9, B.accent);
    }
    g.text(12, y, `${row + first === index ? ">" : " "}${label}`, B.ink);
  });
  if (first > 0) g.text(228, 113, "-", B.muted);
  if (first + 4 < items.length) g.text(228, 146, "+", B.muted);
}

export function battleSelection(g: Gfx, x: number, y: number, w: number, h: number, color: Rgba = B.accent): void {
  g.fill(x, y, w, h, B.shade);
  g.fill(x, y, 2, h, color);
}
