export const MAP_W = Math.max(...RAW.map((row) => row.length));
export const MAP_H = RAW.length;

export const MAP: TileId[][] = RAW.map((row) =>
  [...row.padEnd(MAP_W, "#")].map((ch) => LEGEND[ch] ?? "void"),
);

