export const GRASS_PITY = 10;
export const GRASS_QUIET = 2;

/** 12% base, +0.8% per step, guaranteed on the pity step. */
export function grassEncounterChance(streak: number): number {
  if (streak <= 0) return 0;
  if (streak >= GRASS_PITY) return 1;
  return 0.12 + (streak / GRASS_PITY) * 0.08;
}

