export function zoneAt(x: number, y: number): ZoneId {
  if (x >= 30) return y < 16 ? "copeCliffs" : "yieldYard";
  if (y >= 14) return x < 17 ? "chartwood" : "gasGulch";
  return x < 16 ? "stubtown" : "drippond";
}

