export function encountersAt(x: number, y: number, canopyCleared = false): EncounterRow[] {
  const zone = zoneAt(x, y);
  return (canopyCleared && y >= 21 ? VETERAN_ENCOUNTERS[zone] : undefined) ?? ZONES[zone].encounters;
}

export function tileAt(x: number, y: number): TileDef {
  if (y < 0 || x < 0 || y >= MAP_H || x >= MAP_W) return TILES.void;
  const id = MAP[y]?.[x];
  return id ? TILES[id] : TILES.void;
}

export function spotAt(x: number, y: number): Spot | undefined {
  return SPOTS.find((s) => s.x === x && s.y === y);
}

export function spotFacing(px: number, py: number, dx: number, dy: number): Spot | undefined {
  return spotAt(px + dx, py + dy) ?? spotAt(px, py);
}
